#region Transport
# Read-only HTTPS client for NSX and the vCenter appliance REST API.
# - Only GET, plus an explicit allowlist of session create/destroy operations.
# - Redirects are never followed (credentials must not be forwarded to another host).
# - TLS validation uses the OS trust store; an operator-approved per-endpoint SHA-256
#   pin is the only alternative. Global validation is never disabled.

$script:VsatPins = @{}
$script:VsatPinTypeLoaded = $false
$script:VsatRestAllowlist = @(
    @{ Method = 'POST';   Path = '/api/session/create' }    # NSX session login
    @{ Method = 'POST';   Path = '/api/session/destroy' }   # NSX session logout
    @{ Method = 'POST';   Path = '/api/session' }           # vCenter REST session login
    @{ Method = 'DELETE'; Path = '/api/session' }           # vCenter REST session logout
)
$script:VsatRestMaxBytes = 64MB
$script:VsatRestTimeoutSec = 60
$script:VsatRestOperations = [System.Collections.Generic.List[string]]::new()

function Initialize-VsatTls {
    if ($script:VsatPinTypeLoaded) { return $true }
    try {
        if ($PSVersionTable.PSVersion.Major -lt 6) { Add-Type -AssemblyName System.Net.Http }
        if (-not ('VsatTls' -as [type])) {
            $refs = @('System.Net.Http', 'System.Net.Primitives', 'System.Net.Security', 'System.Net.Sockets', 'System.Security.Cryptography.X509Certificates', 'System.Security.Cryptography', 'System.Runtime', 'System.Collections')
            $src = @'
using System;
using System.Net.Http;
using System.Net.Security;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
public static class VsatTls {
    public static string Sha256(X509Certificate cert) {
        using (var sha = SHA256.Create()) {
            return BitConverter.ToString(sha.ComputeHash(cert.GetRawCertData())).Replace("-", "").ToLowerInvariant();
        }
    }
    // Accepts a certificate only when it chains to a trusted root with a matching name,
    // or when its SHA-256 fingerprint equals the operator-approved pin for this endpoint.
    public static HttpClientHandler CreateHandler(string pin) {
        var h = new HttpClientHandler();
        h.AllowAutoRedirect = false;
        h.UseCookies = true;
        h.CookieContainer = new System.Net.CookieContainer();
        h.UseProxy = false;
        h.UseDefaultCredentials = false;
        if (!String.IsNullOrEmpty(pin)) {
            string expected = pin.Replace(":", "").ToLowerInvariant();
            h.ServerCertificateCustomValidationCallback = (req, cert, chain, errors) => {
                if (cert == null) return false;
                return String.Equals(Sha256(cert), expected, StringComparison.Ordinal);
            };
        }
        return h;
    }
    // Reads the presented certificate without sending any application data or credentials.
    public static string[] Probe(string host, int port, int timeoutMs) {
        using (var client = new TcpClient()) {
            var ar = client.BeginConnect(host, port, null, null);
            if (!ar.AsyncWaitHandle.WaitOne(timeoutMs)) throw new TimeoutException("TCP connect timeout");
            client.EndConnect(ar);
            X509Certificate seen = null; SslPolicyErrors seenErrors = SslPolicyErrors.None;
            using (var ssl = new SslStream(client.GetStream(), false, (s, c, ch, e) => { seen = c; seenErrors = e; return true; })) {
                ssl.ReadTimeout = timeoutMs; ssl.WriteTimeout = timeoutMs;
                ssl.AuthenticateAsClient(host);
                var c2 = new X509Certificate2(seen);
                return new string[] { Sha256(seen), c2.Subject, c2.Issuer, c2.NotAfter.ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ"), seenErrors.ToString() };
            }
        }
    }
}
'@
            Add-Type -TypeDefinition $src -Language CSharp -ReferencedAssemblies $refs -ErrorAction Stop -WarningAction SilentlyContinue 2>$null
        }
        $script:VsatPinTypeLoaded = $true
        return $true
    }
    catch {
        Write-VsatLog -Level warn -Source 'tls' -Message "TLS helper unavailable (Add-Type blocked?): $($_.Exception.Message). Certificate pinning disabled; OS trust store is still enforced."
        return $false
    }
}

function Register-VsatPins {
    param([string[]]$Pins)
    foreach ($p in @($Pins)) {
        if (-not $p) { continue }
        if ($p -match '^\s*([^=\s]+)\s*=\s*(SHA256:[A-Za-z0-9+/]{43}=?)\s*$') { $script:VsatSshPins[$Matches[1].ToLowerInvariant()] = $Matches[2].TrimEnd('='); continue }
        if ($p -notmatch '^\s*([^=\s]+)\s*=\s*([0-9A-Fa-f:]{64,95})\s*$') { throw "Invalid -TrustedThumbprint '$p'. Expected host=SHA256HEX." }
        $hex = ($Matches[2] -replace ':', '').ToLowerInvariant()
        if ($hex.Length -ne 64) { throw "Invalid SHA-256 fingerprint for $($Matches[1])." }
        $script:VsatPins[$Matches[1].ToLowerInvariant()] = $hex
    }
}

function Split-VsatAddress {
    # "host", "host:port", "[v6]:port" or bare IPv6 -> @{ host; port }
    param([Parameter(Mandatory)][string]$Address, [int]$DefaultPort = 443)
    if ($Address -match '^\[(.+)\](?::(\d+))?$') { return @{ host = $Matches[1]; port = $(if ($Matches[2]) { [int]$Matches[2] } else { $DefaultPort }) } }
    if ($Address -match '^([^:]+):(\d{1,5})$') { return @{ host = $Matches[1]; port = [int]$Matches[2] } }
    return @{ host = $Address; port = $DefaultPort }
}

function Get-VsatCertificateInfo {
    param([Parameter(Mandatory)][string]$HostName, [int]$Port = 0)
    if (-not (Initialize-VsatTls)) { return $null }
    $a = Split-VsatAddress $HostName
    if ($Port -eq 0) { $Port = $a.port }
    $r = [VsatTls]::Probe($a.host, $Port, 8000)
    return [ordered]@{ sha256 = $r[0]; subject = $r[1]; issuer = $r[2]; notAfter = $r[3]; policyErrors = $r[4]; trusted = ($r[4] -eq 'None') }
}

function Assert-VsatRestAllowed {
    # Read-only is defined by operation semantics: GET, or an allowlisted session operation.
    param([Parameter(Mandatory)][string]$Method, [Parameter(Mandatory)][string]$Path)
    $m = $Method.ToUpperInvariant()
    $p = ($Path -split '\?')[0]
    if ($p -notmatch '^/[A-Za-z0-9_\-./%:=,~@]*$' -or $p -match '\.\.|//|\\') { throw "VSAT read-only guard: rejected path '$Path'." }
    if ($m -eq 'GET') { return }
    foreach ($a in $script:VsatRestAllowlist) { if ($a.Method -eq $m -and $a.Path -eq $p) { return } }
    throw "VSAT read-only guard: $m $p is not an approved session/read operation."
}

function New-VsatRestSession {
    param([Parameter(Mandatory)][string]$Address, [ValidateSet('nsx', 'vcenter')][string]$Kind = 'nsx')
    if (-not (Initialize-VsatTls)) {
        $pinned = $script:VsatPins.ContainsKey($Address.ToLowerInvariant())
        if ($pinned) { throw "A certificate pin was supplied for $Address but the TLS helper is unavailable; refusing to connect without the requested pin." }
        if ($PSVersionTable.PSVersion.Major -lt 6) { Add-Type -AssemblyName System.Net.Http }
        $handler = New-Object System.Net.Http.HttpClientHandler
        $handler.AllowAutoRedirect = $false; $handler.UseProxy = $false
        $handler.CookieContainer = New-Object System.Net.CookieContainer
    }
    else {
        $pin = $script:VsatPins[$Address.ToLowerInvariant()]
        $handler = [VsatTls]::CreateHandler($pin)
    }
    $client = New-Object System.Net.Http.HttpClient($handler)
    $client.Timeout = [TimeSpan]::FromSeconds($script:VsatRestTimeoutSec)
    $baseAddr = if ($Address -match '^[0-9a-fA-F:]+$' -and $Address.Contains(':')) { "[$Address]" } else { $Address }
    return [ordered]@{ address = $Address; base = "https://$baseAddr"; kind = $Kind; client = $client; handler = $handler; headers = @{}; calls = 0 }
}

function Invoke-VsatRest {
    param(
        [Parameter(Mandatory)]$Session,
        [ValidateSet('GET', 'POST', 'DELETE')][string]$Method = 'GET',
        [Parameter(Mandatory)][string]$Path,
        [string]$Body,
        [string]$ContentType = 'application/json',
        [hashtable]$Headers,
        [switch]$Raw
    )
    Assert-VsatRestAllowed -Method $Method -Path $Path
    $attempt = 0
    while ($true) {
        $attempt++
        $req = New-Object System.Net.Http.HttpRequestMessage((New-Object System.Net.Http.HttpMethod($Method)), ($Session.base + $Path))
        [void]$req.Headers.TryAddWithoutValidation('Accept', 'application/json')
        foreach ($k in $Session.headers.Keys) { [void]$req.Headers.TryAddWithoutValidation($k, [string]$Session.headers[$k]) }
        if ($Headers) { foreach ($k in $Headers.Keys) { [void]$req.Headers.TryAddWithoutValidation($k, [string]$Headers[$k]) } }
        if ($null -ne $Body) { $req.Content = New-Object System.Net.Http.StringContent($Body, [System.Text.Encoding]::UTF8, $ContentType) }
        $Session.calls++
        $script:VsatRestOperations.Add("$Method $($Session.address)$(($Path -split '\?')[0])")
        try {
            $resp = $Session.client.SendAsync($req, [System.Net.Http.HttpCompletionOption]::ResponseHeadersRead).GetAwaiter().GetResult()
        }
        catch {
            $inner = $_.Exception
            while ($inner.InnerException) { $inner = $inner.InnerException }
            throw "Connection to $($Session.address) failed: $($inner.Message)"
        }
        finally { $req.Dispose() }
        $code = [int]$resp.StatusCode
        if (($code -eq 429 -or $code -eq 503) -and $attempt -lt 4) {
            $delay = [Math]::Min(30, [Math]::Pow(2, $attempt))
            $ra = $resp.Headers.RetryAfter
            if ($ra -and $ra.Delta) { $delay = [Math]::Min(60, $ra.Delta.TotalSeconds) }
            $resp.Dispose()
            Write-VsatLog -Level warn -Source 'rest' -Message "$($Session.address) throttled ($code); backing off $delay s"
            Start-Sleep -Seconds $delay
            continue
        }
        if ($code -ge 300 -and $code -lt 400) {
            $resp.Dispose()
            throw "Endpoint $($Session.address) returned redirect $code for $Path; redirects are not followed to protect credentials."
        }
        $len = $resp.Content.Headers.ContentLength
        if ($len -and $len -gt $script:VsatRestMaxBytes) { $resp.Dispose(); throw "Response from $Path exceeds size limit." }
        $text = $resp.Content.ReadAsStringAsync().GetAwaiter().GetResult()
        if ($text.Length -gt $script:VsatRestMaxBytes) { $resp.Dispose(); throw "Response from $Path exceeds size limit." }
        if ($code -ge 400) {
            $resp.Dispose()
            $snippet = if ($text.Length -gt 300) { $text.Substring(0, 300) } else { $text }
            throw ("HTTP {0} {1} on {2}: {3}" -f $code, $resp.ReasonPhrase, ($Path -split '\?')[0], (Protect-VsatText $snippet))
        }
        if ($Raw) { $out = @{ status = $code; headers = $resp.Headers; body = $text }; $resp.Dispose(); return $out }
        $resp.Dispose()
        if ([string]::IsNullOrWhiteSpace($text)) { return $null }
        return (ConvertFrom-VsatJson $text)
    }
}

function Get-VsatNsxPaged {
    # Follows NSX cursors; detects repeated cursors and truncated result sets.
    param([Parameter(Mandatory)]$Session, [Parameter(Mandatory)][string]$Path, [int]$MaxPages = 2000, [int]$PageSize = 1000)
    $items = [System.Collections.Generic.List[object]]::new()
    $cursor = $null; $seen = @{}; $expected = $null; $pages = 0
    do {
        $sep = if ($Path.Contains('?')) { '&' } else { '?' }
        $p = "$Path${sep}page_size=$PageSize"
        if ($cursor) { $p += '&cursor=' + [uri]::EscapeDataString($cursor) }
        $r = Invoke-VsatRest -Session $Session -Path $p
        $pages++
        foreach ($i in @(Get-VsatProp $r 'results' @())) { $items.Add($i) }
        $rc = Get-VsatProp $r 'result_count'
        if ($null -ne $rc) { $expected = [int]$rc }
        $cursor = Get-VsatProp $r 'cursor'
        if ($cursor) {
            if ($seen.ContainsKey($cursor)) { throw "NSX pagination loop detected on $Path" }
            $seen[$cursor] = $true
        }
        if ($pages -ge $MaxPages) { throw "NSX pagination exceeded $MaxPages pages on $Path" }
    } while ($cursor)
    $truncated = ($null -ne $expected -and $items.Count -lt $expected)
    return [ordered]@{ items = $items.ToArray(); truncated = $truncated; expected = $expected }
}

function Close-VsatRestSession {
    param($Session)
    if (-not $Session) { return }
    try {
        if ($Session.kind -eq 'nsx' -and $Session.headers.ContainsKey('X-XSRF-TOKEN')) { [void](Invoke-VsatRest -Session $Session -Method POST -Path '/api/session/destroy' -Raw) }
        elseif ($Session.kind -eq 'vcenter' -and $Session.headers.ContainsKey('vmware-api-session-id')) { [void](Invoke-VsatRest -Session $Session -Method DELETE -Path '/api/session' -Raw) }
    }
    catch { Write-VsatLog -Level debug -Source 'rest' -Message "Logout from $($Session.address) failed: $($_.Exception.Message)" }
    finally {
        $Session.headers.Clear()
        try { $Session.client.Dispose() } catch { }
    }
}

#endregion Transport

# ---- src/40-CollectVSphere.ps1 ----
#region vSphere collector
# Read-only vSphere collection through PowerCLI. Only Get-* cmdlets, Get-View property
# reads and read-only esxcli namespaces (*.get / *.list) are used; see the mutation
# guard test (tests/ReadOnly.Tests.ps1) which rejects any other VMware cmdlet.

$script:VsatEsxcliAllowed = @(
    'software.acceptance.get', 'system.settings.kernel.list', 'system.module.list',
    'system.coredump.network.get', 'system.coredump.file.list', 'system.syslog.config.get',
    'network.firewall.get', 'network.firewall.ruleset.list', 'network.firewall.ruleset.allowedip.list',
    'system.security.fips140.ssh.get', 'system.settings.encryption.get', 'system.account.list',
    'iscsi.adapter.list', 'iscsi.adapter.auth.chap.get', 'software.vib.list'
)

function Import-VsatPowerCli {
    # Loads the core PowerCLI module process-locally (offline package ./modules first).
    if (Get-Command -Name Connect-VIServer -ErrorAction SilentlyContinue) { return $true }
    try {
        Import-Module VMware.VimAutomation.Core -ErrorAction Stop -WarningAction SilentlyContinue 3>$null 6>$null | Out-Null
        # No telemetry: opt out of PowerCLI CEIP for this process only (user settings untouched).
        try { Set-PowerCLIConfiguration -Scope Session -ParticipateInCEIP $false -Confirm:$false -ErrorAction Stop | Out-Null } catch { }
        return $true
    }
    catch {
        Write-VsatLog -Level error -Source 'doctor' -Message "PowerCLI (VMware.VimAutomation.Core) is not available: $($_.Exception.Message)"
        return $false
    }
}

function Connect-VsatVSphere {
    param([Parameter(Mandatory)][string]$Address, [Parameter(Mandatory)][pscredential]$Credential)
    if (-not (Import-VsatPowerCli)) { throw 'PowerCLI is required for vCenter/ESXi collection. Run .\vsat.ps1 -Doctor.' }
    Register-VsatSecret $Credential.GetNetworkCredential().Password
    $pin = $script:VsatPins[$Address.ToLowerInvariant()]
    $restore = $null
    try {
        if ($pin) {
            # Explicit per-endpoint approval: verify the presented certificate matches the pin,
            # then relax PowerCLI validation for this session scope only and restore it after.
            $cert = Get-VsatCertificateInfo -HostName $Address
            if (-not $cert -or $cert.sha256 -ne $pin) { throw "Certificate presented by $Address does not match the approved fingerprint; refusing to connect." }
            $restore = (Get-PowerCLIConfiguration -Scope Session).InvalidCertificateAction
            Set-PowerCLIConfiguration -Scope Session -InvalidCertificateAction Ignore -Confirm:$false -ErrorAction Stop | Out-Null
            Write-VsatLog -Source 'tls' -Message "Using operator-approved certificate pin for $Address (session scope only)."
        }
        $hp = Split-VsatAddress $Address
        $conn = Connect-VIServer -Server $hp.host -Port $hp.port -Credential $Credential -Protocol https -NotDefault -ErrorAction Stop -WarningAction SilentlyContinue
    }
    finally {
        if ($pin) { Set-PowerCLIConfiguration -Scope Session -InvalidCertificateAction $(if ($restore) { $restore } else { 'Unset' }) -Confirm:$false -ErrorAction SilentlyContinue | Out-Null }
    }
    return $conn
}

function Invoke-VsatEsxcli {
    param([Parameter(Mandatory)]$EsxCli, [Parameter(Mandatory)][string]$Namespace, [hashtable]$Arguments)
    if ($script:VsatEsxcliAllowed -notcontains $Namespace) { throw "VSAT read-only guard: esxcli $Namespace is not allowlisted." }
    $obj = $EsxCli
    $parts = $Namespace.Split('.')
    foreach ($p in $parts) { $obj = $obj.$p }
    if ($Arguments) { return $obj.Invoke($Arguments) }
    return $obj.Invoke()
}

function Get-VsatMoRef { param($View) return [string]$View.MoRef.Value }

function ConvertTo-VsatSecurityPolicy {
    param($Policy)
    if ($null -eq $Policy) { return $null }
    $o = [ordered]@{}
    foreach ($n in 'AllowPromiscuous', 'MacChanges', 'ForgedTransmits') {
        $v = $Policy.$n
        if ($null -ne $v -and $v.PSObject.Properties['Value']) { $v = $v.Value }
        $o[$n.Substring(0, 1).ToLower() + $n.Substring(1)] = $v
    }
    return $o
}

function Invoke-VsatVSphereCollection {
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)]$Endpoint, [Parameter(Mandatory)]$Connection)
    $ep = $Endpoint.id
    $srv = $Connection
    $about = $srv.ExtensionData.Content.About
    $Endpoint.product = [string]$about.FullName
    $Endpoint.version = [string]$about.Version
    $Endpoint.build = [string]$about.Build
    $Endpoint.instanceUuid = [string]$about.InstanceUuid
    $Endpoint.apiVersion = [string]$about.ApiVersion
    $isVc = ($about.ApiType -eq 'VirtualCenter')
    if (-not $isVc) { $Endpoint.type = 'esxi' }
    $rootId = "${ep}:root"
    $root = Add-VsatAsset -Evidence $Evidence -Id $rootId -Type $(if ($isVc) { 'vcenter' } else { 'esxi-endpoint' }) -Name $Endpoint.address -Endpoint $ep -Version $about.Version -Build $about.Build -Props ([ordered]@{ product = $about.FullName; instanceUuid = $about.InstanceUuid; apiType = $about.ApiType })
    $hostIndex = @{}; $netIndex = @{}; $dsIndex = @{}

    Invoke-VsatCollector -Evidence $Evidence -Name 'vsphere.vcenter' -Endpoint $ep -Affects @('VC-*') -Script {
        if (-not $isVc) { return @{ count = 0; status = 'skipped'; error = 'Direct ESXi connection' } }
        Invoke-VsatFact $root 'extensions' {
            $em = Get-View -Server $srv -Id $srv.ExtensionData.Content.ExtensionManager -Property ExtensionList
            @($em.ExtensionList | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ key = $_.Key; company = $_.Company; version = $_.Version; urls = @($_.Server | Where-Object { $null -ne $_ } | ForEach-Object { $_.Url }) } })
        }
        Invoke-VsatFact $root 'permissions' {
            @(Get-VIPermission -Server $srv -ErrorAction Stop | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ principal = $_.Principal; role = $_.Role; entity = [string]$_.Entity; entityId = $_.EntityId; propagate = $_.Propagate; isGroup = $_.IsGroup } })
        }
        Invoke-VsatFact $root 'roles' {
            @(Get-VIRole -Server $srv -ErrorAction Stop | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ name = $_.Name; system = $_.IsSystem; privilegeCount = @($_.PrivilegeList).Count } })
        }
        Invoke-VsatFact $root 'settings' {
            $om = Get-View -Server $srv -Id $srv.ExtensionData.Content.Setting -Property Setting
            $h = [ordered]@{}
            foreach ($s in $om.Setting) { if ($s.Key -match '^(config\.vpxd\.(hostPasswordLength|event\.maxAge|task\.maxAge)|VirtualCenter\.VimPasswordExpirationInDays|log\.level|config\.log\.level|vpxd\.event\.maxAge|event\.maxAge|task\.maxAge|config\.vpxd\.sso\..*)$') { $h[$s.Key] = [string]$s.Value } }
            $h
        }
        Invoke-VsatFact $root 'keyProviders' {
            $cm = Get-View -Server $srv -Id $srv.ExtensionData.Content.CryptoManager -ErrorAction Stop
            @($cm.KmipServers | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ cluster = $_.ClusterId.Id; servers = @($_.Servers | Where-Object { $null -ne $_ } | ForEach-Object { $_.Name }) } })
        }
        1
    }

    Invoke-VsatCollector -Evidence $Evidence -Name 'vsphere.inventory' -Endpoint $ep -Affects @('CL-*') -Script {
        $dcs = Get-View -Server $srv -ViewType Datacenter -Property Name, HostFolder
        foreach ($dc in $dcs) {
            $dcId = "${ep}:" + (Get-VsatMoRef $dc)
            [void](Add-VsatAsset -Evidence $Evidence -Id $dcId -Type 'datacenter' -Name $dc.Name -Endpoint $ep)
            if ($isVc) { Add-VsatRelationship -Evidence $Evidence -Source $rootId -Target $dcId -Type contains -Provenance 'vsphere.inventory' }
            $clusters = Get-View -Server $srv -ViewType ClusterComputeResource -SearchRoot $dc.MoRef -Property Name, Host, ConfigurationEx, Summary
            foreach ($cl in $clusters) {
                $clId = "${ep}:" + (Get-VsatMoRef $cl)
                $cfg = $cl.ConfigurationEx
                $ha = $cfg.DasConfig
                $a = Add-VsatAsset -Evidence $Evidence -Id $clId -Type 'cluster' -Name $cl.Name -Endpoint $ep
                Add-VsatRelationship -Evidence $Evidence -Source $dcId -Target $clId -Type contains -Provenance 'vsphere.inventory'
                Set-VsatFact -Asset $a -Name 'ha' -Value ([ordered]@{
                        enabled = [bool]$ha.Enabled; admissionControl = [bool]$ha.AdmissionControlEnabled
                        policy = $(if ($ha.AdmissionControlPolicy) { $ha.AdmissionControlPolicy.GetType().Name } else { $null })
                        hostMonitoring = [string]$ha.HostMonitoring; vmMonitoring = [string]$ha.VmMonitoring
                        isolationResponse = $(if ($ha.DefaultVmSettings) { [string]$ha.DefaultVmSettings.IsolationResponse } else { $null })
                        heartbeatDatastorePolicy = [string]$ha.HBDatastoreCandidatePolicy
                    })
                Set-VsatFact -Asset $a -Name 'drs' -Value ([ordered]@{ enabled = [bool]$cfg.DrsConfig.Enabled; behavior = [string]$cfg.DrsConfig.DefaultVmBehavior; rules = @($cfg.Rule | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ name = $_.Name; type = $_.GetType().Name; enabled = $_.Enabled } }) })
                Set-VsatFact -Asset $a -Name 'summary' -Value ([ordered]@{ hosts = [int]$cl.Summary.NumHosts; effectiveHosts = [int]$cl.Summary.NumEffectiveHosts })
                foreach ($h in $cl.Host) { $hostIndex[[string]$h.Value] = $clId }
            }
        }
        @($dcs).Count
    }

    Invoke-VsatCollector -Evidence $Evidence -Name 'vsphere.hosts' -Endpoint $ep -Affects @('ESXI-*') -Script {
        $props = 'Name', 'Parent', 'Runtime', 'Summary.Config.Product', 'Config.LockdownMode', 'Config.AdminDisabled', 'Config.Certificate', 'Config.Network', 'Config.DateTimeInfo', 'Config.Option', 'Config.Service', 'Config.Firewall', 'Config.StorageDevice', 'Capability', 'ConfigManager', 'Datastore', 'Hardware.SystemInfo'
        $hosts = Get-View -Server $srv -ViewType HostSystem -Property $props
        $n = 0
        foreach ($h in $hosts) {
            if (Test-VsatCancel) { break }
            $hid = "${ep}:" + (Get-VsatMoRef $h)
            $prod = $h.Summary.Config.Product
            $a = Add-VsatAsset -Evidence $Evidence -Id $hid -Type 'host' -Name $h.Name -Endpoint $ep -Version $prod.Version -Build $prod.Build -Props ([ordered]@{
                    product = $prod.FullName; connectionState = [string]$h.Runtime.ConnectionState; powerState = [string]$h.Runtime.PowerState
                    maintenance = [bool]$h.Runtime.InMaintenanceMode; vendor = $h.Hardware.SystemInfo.Vendor; model = $h.Hardware.SystemInfo.Model
                })
            if ($hostIndex.ContainsKey((Get-VsatMoRef $h))) { Add-VsatRelationship -Evidence $Evidence -Source $hostIndex[(Get-VsatMoRef $h)] -Target $hid -Type contains -Provenance 'vsphere.inventory' }
            elseif ($isVc) { Add-VsatRelationship -Evidence $Evidence -Source $rootId -Target $hid -Type contains -Provenance 'vsphere.inventory' -Confidence inferred }
            if ([string]$h.Runtime.ConnectionState -ne 'connected') {
                foreach ($f in 'lockdown', 'advanced', 'services', 'ntp', 'firewall') { Set-VsatFact -Asset $a -Name $f -Status error -Value $null -ErrorMessage "Host is $($h.Runtime.ConnectionState); configuration not readable" }
                continue
            }
            # HostConfigInfo.lockdownMode is the authoritative enum; adminDisabled is a deprecated Boolean.
            $lm = $h.Config.LockdownMode
            if ($null -ne $lm) { Set-VsatFact -Asset $a -Name 'lockdown' -Value ([ordered]@{ mode = [string]$lm }) }
            else { Set-VsatFact -Asset $a -Name 'lockdown' -Status unsupported -Value $null -ErrorMessage 'lockdownMode not exposed by this host version' }
            Invoke-VsatFact $a 'advanced' { $o = [ordered]@{}; foreach ($opt in $h.Config.Option) { $o[$opt.Key] = $opt.Value }; $o }
            Invoke-VsatFact $a 'services' { @($h.Config.Service.Service | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ key = $_.Key; label = $_.Label; running = [bool]$_.Running; policy = [string]$_.Policy } }) }
            Invoke-VsatFact $a 'ntp' { [ordered]@{ servers = @($h.Config.DateTimeInfo.NtpConfig.Server); protocol = [string]$h.Config.DateTimeInfo.Protocol } }
            Invoke-VsatFact $a 'firewall' {
                $fw = $h.Config.Firewall
                [ordered]@{
                    defaultIncomingBlocked = [bool]$fw.DefaultPolicy.IncomingBlocked; defaultOutgoingBlocked = [bool]$fw.DefaultPolicy.OutgoingBlocked
                    rulesets = @($fw.Ruleset | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ key = $_.Key; enabled = [bool]$_.Enabled; allIp = [bool]$_.AllowedHosts.AllIp; allowedIps = @($_.AllowedHosts.IpAddress) + @($_.AllowedHosts.IpNetwork | Where-Object { $null -ne $_ } | ForEach-Object { "$($_.Network)/$($_.PrefixLength)" }) } })
                }
            }
            Invoke-VsatFact $a 'certificate' {
                if (-not $h.Config.Certificate) { return $null }
                $x = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 (, [byte[]]$h.Config.Certificate)
                [ordered]@{ subject = $x.Subject; issuer = $x.Issuer; notAfter = $x.NotAfter.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ'); selfSigned = ($x.Subject -eq $x.Issuer); vmcaSigned = ($x.Issuer -match 'VMCA|CA,.*VMware|O=VMware') }
            }
            Invoke-VsatFact $a 'secureBoot' {
                $cap = $h.Capability
                [ordered]@{ uefiSecureBoot = $cap.UefiSecureBoot; tpmSupported = $cap.TpmSupported; tpmVersion = $cap.TpmVersion }
            }
            Invoke-VsatFact $a 'attestation' {
                $h2 = Get-View -Server $srv -Id $h.MoRef -Property 'Runtime.TpmAttestation', 'Summary.TpmAttestation' -ErrorAction Stop
                $t = $h2.Runtime.TpmAttestation
                if ($null -eq $t) { return $null }
                [ordered]@{ status = [string]$t.Status; message = $(if ($t.Message) { $t.Message.Message } else { $null }) }
            }
            $esx = $null
            try { $esx = Get-EsxCli -Server $srv -VMHost (Get-VMHost -Server $srv -Id $h.MoRef -ErrorAction Stop) -V2 -ErrorAction Stop }
            catch { foreach ($f in 'acceptance', 'coredump', 'syslog', 'kernel', 'modules', 'iscsiAdapters') { Set-VsatFact -Asset $a -Name $f -Status (Get-VsatErrorClass $_) -Value $null -ErrorMessage $_.Exception.Message } }
            if ($esx) {
                Invoke-VsatFact $a 'acceptance' { [string](Invoke-VsatEsxcli $esx 'software.acceptance.get') }
                Invoke-VsatFact $a 'kernel' { $o = [ordered]@{}; foreach ($k in (Invoke-VsatEsxcli $esx 'system.settings.kernel.list')) { $o[$k.Name] = $k.Configured }; $o }
                Invoke-VsatFact $a 'modules' { @(Invoke-VsatEsxcli $esx 'system.module.list' | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ name = $_.Name; loaded = $_.IsLoaded; enabled = $_.IsEnabled } }) }
                Invoke-VsatFact $a 'coredump' {
                    $net = Invoke-VsatEsxcli $esx 'system.coredump.network.get'
                    $file = @(Invoke-VsatEsxcli $esx 'system.coredump.file.list')
                    [ordered]@{ networkEnabled = [bool]($net.Enabled -eq 'true' -or $net.Enabled -eq $true); networkServer = $net.NetworkServerIP; fileActive = @($file | Where-Object { $_.Active -eq 'true' -or $_.Active -eq $true }).Count }
                }
                Invoke-VsatFact $a 'syslog' { $s = Invoke-VsatEsxcli $esx 'system.syslog.config.get'; [ordered]@{ remoteHost = [string]$s.RemoteHost; logDir = [string]$s.LocalLogOutput; logDirUnique = $s.LocalLogOutputIsPersistent } }
                Invoke-VsatFact $a 'iscsiAdapters' {
                    $ads = @(Invoke-VsatEsxcli $esx 'iscsi.adapter.list')
                    @(foreach ($ad in $ads) {
                            $chap = $null; $mchap = $null
                            try { $chap = Invoke-VsatEsxcli $esx 'iscsi.adapter.auth.chap.get' @{ adapter = $ad.Adapter; direction = 'uni' } } catch { }
                            try { $mchap = Invoke-VsatEsxcli $esx 'iscsi.adapter.auth.chap.get' @{ adapter = $ad.Adapter; direction = 'mutual' } } catch { }
                            [ordered]@{ adapter = $ad.Adapter; chapLevel = $(if ($chap) { [string]$chap.Level } else { $null }); mutualChapLevel = $(if ($mchap) { [string]$mchap.Level } else { $null }) }
                        })
                }
            }
            Add-VsatHostNetwork -Evidence $Evidence -Asset $a -HostView $h -Server $srv -NetIndex $netIndex -Endpoint $ep
            foreach ($ds in $h.Datastore) { $dsIndex[[string]$ds.Value] = $true; Add-VsatRelationship -Evidence $Evidence -Source $hid -Target ("${ep}:" + $ds.Value) -Type depends -Provenance 'vsphere.hosts' -Props ([ordered]@{ kind = 'mount' }) }
            $n++
        }
        $n
    }

    Invoke-VsatCollector -Evidence $Evidence -Name 'vsphere.vds' -Endpoint $ep -Affects @('NET-VDS-*') -Script {
        if (-not $isVc) { return @{ count = 0; status = 'skipped'; error = 'Distributed switches require vCenter' } }
        $vdsSec = @{}
        $dvs = Get-View -Server $srv -ViewType VmwareDistributedVirtualSwitch -Property Name, Config, Summary
        foreach ($d in $dvs) {
            $did = "${ep}:" + (Get-VsatMoRef $d)
            $cfg = $d.Config
            $def = $cfg.DefaultPortConfig
            $a = Add-VsatAsset -Evidence $Evidence -Id $did -Type 'vds' -Name $d.Name -Endpoint $ep -Version $cfg.ProductInfo.Version
            Set-VsatFact -Asset $a -Name 'policy' -Value ([ordered]@{
                    security = (ConvertTo-VsatSecurityPolicy $def.SecurityPolicy)
                    netflow = [ordered]@{ collectorIp = $(if ($cfg.IpfixConfig) { $cfg.IpfixConfig.CollectorIpAddress } else { $null }); collectorPort = $(if ($cfg.IpfixConfig) { $cfg.IpfixConfig.CollectorPort } else { $null }) }
                    healthCheck = @($cfg.HealthCheckConfig | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ type = $_.GetType().Name; enabled = [bool]$_.Enable } })
                    mirroring = @($cfg.VspanSession | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ name = $_.Name; enabled = [bool]$_.Enabled; destinations = @($_.DestinationPort.IpAddress) } })
                    lacp = [string]$cfg.LacpApiVersion; mtu = $cfg.MaxMtu
                    uplinks = @($cfg.UplinkPortPolicy.UplinkPortName)
                })
            foreach ($hm in $cfg.Host) { Add-VsatRelationship -Evidence $Evidence -Source $did -Target ("${ep}:" + $hm.Config.Host.Value) -Type depends -Provenance 'vsphere.vds' -Props ([ordered]@{ kind = 'member-host' }) }
            $vdsSec[$did] = $a.facts.policy.value.security
        }
        $pgs = Get-View -Server $srv -ViewType DistributedVirtualPortgroup -Property Name, Config, Key
        foreach ($pg in $pgs) {
            $pid2 = "${ep}:" + (Get-VsatMoRef $pg)
            $c = $pg.Config
            $dp = $c.DefaultPortConfig
            $vlan = $null; $vlanType = $null
            if ($dp -and $dp.Vlan) {
                $vlanType = $dp.Vlan.GetType().Name
                if ($dp.Vlan.PSObject.Properties['VlanId']) { $v = $dp.Vlan.VlanId; $vlan = $(if ($v -is [array]) { @($v | Where-Object { $null -ne $_ } | ForEach-Object { "$($_.Start)-$($_.End)" }) } else { $v }) }
                elseif ($dp.Vlan.PSObject.Properties['PvlanId']) { $vlan = $dp.Vlan.PvlanId }
            }
            $ov = $c.Policy
            $a = Add-VsatAsset -Evidence $Evidence -Id $pid2 -Type 'dvportgroup' -Name $pg.Name -Endpoint $ep -Props ([ordered]@{ key = [string]$pg.Key; uplink = [bool]$c.Uplink; vlan = $vlan; vlanType = $vlanType; backingType = [string]$c.BackingType; segmentId = $c.SegmentId; logicalSwitchUuid = $c.LogicalSwitchUuid })
            # Effective policy: portgroup value where set, otherwise inherited from the switch default.
            $own = ConvertTo-VsatSecurityPolicy $(if ($dp) { $dp.SecurityPolicy } else { $null })
            $parent = if ($c.DistributedVirtualSwitch) { $vdsSec["${ep}:" + $c.DistributedVirtualSwitch.Value] } else { $null }
            $eff = [ordered]@{}
            foreach ($k in 'allowPromiscuous', 'macChanges', 'forgedTransmits') {
                $v = if ($own -and $null -ne $own[$k]) { $own[$k] } elseif ($parent) { $parent[$k] } else { $null }
                $eff[$k] = $v
            }
            Set-VsatFact -Asset $a -Name 'policy' -Value ([ordered]@{
                    security = $eff
                    overrides = [ordered]@{
                        security = [bool]$ov.SecurityPolicyOverrideAllowed; vlan = [bool]$ov.VlanOverrideAllowed; shaping = [bool]($ov.ShapingOverrideAllowed); blockOverride = [bool]$ov.BlockOverrideAllowed
                        uplinkTeaming = [bool]$ov.UplinkTeamingOverrideAllowed; ipfix = [bool]$ov.IpfixOverrideAllowed; resetAtDisconnect = [bool]$ov.PortConfigResetAtDisconnect
                    }
                    ipfixEnabled = $(if ($dp.IpfixEnabled) { [bool]$dp.IpfixEnabled.Value } else { $null })
                    teaming = $(if ($dp.UplinkTeamingPolicy -and $dp.UplinkTeamingPolicy.UplinkPortOrder) { [ordered]@{ active = @($dp.UplinkTeamingPolicy.UplinkPortOrder.ActiveUplinkPort); standby = @($dp.UplinkTeamingPolicy.UplinkPortOrder.StandbyUplinkPort) } } else { $null })
                })
            if ($c.DistributedVirtualSwitch) { Add-VsatRelationship -Evidence $Evidence -Source ("${ep}:" + $c.DistributedVirtualSwitch.Value) -Target $pid2 -Type contains -Provenance 'vsphere.vds' }
            $netIndex[[string]$pg.MoRef.Value] = $pid2
            # Per-port effective settings: overrides that diverge from the portgroup default.
            if ($ov.SecurityPolicyOverrideAllowed -and -not $c.Uplink) {
                Invoke-VsatFact $a 'portOverrides' {
                    $dvsView = Get-View -Server $srv -Id $c.DistributedVirtualSwitch -Property Name
                    $crit = New-Object VMware.Vim.DistributedVirtualSwitchPortCriteria
                    $crit.PortgroupKey = @($pg.Key); $crit.Inside = $true
                    $ports = $dvsView.FetchDVPorts($crit)
                    @($ports | Where-Object { $null -ne $_ } | ForEach-Object {
                            $sp = ConvertTo-VsatSecurityPolicy $_.Config.Setting.SecurityPolicy
                            if ($sp -and ($sp.allowPromiscuous -or $sp.macChanges -or $sp.forgedTransmits)) { [ordered]@{ port = $_.Key; connectee = $(if ($_.Connectee) { $_.Connectee.ConnectedEntity.Value } else { $null }); security = $sp } }
                        })
                }
            }
        }
        @($dvs).Count + @($pgs).Count
    }

    Invoke-VsatCollector -Evidence $Evidence -Name 'vsphere.datastores' -Endpoint $ep -Affects @('ST-*') -Script {
        $dss = Get-View -Server $srv -ViewType Datastore -Property Name, Summary, Info, Host
        foreach ($d in $dss) {
            $did = "${ep}:" + (Get-VsatMoRef $d)
            $info = $d.Info
            $nas = if ($info.PSObject.Properties['Nas'] -and $info.Nas) { [ordered]@{ remoteHost = $info.Nas.RemoteHost; remoteHosts = @($info.Nas.RemoteHostNames); type = $info.Nas.Type; securityType = $info.Nas.SecurityType } } else { $null }
            $a = Add-VsatAsset -Evidence $Evidence -Id $did -Type 'datastore' -Name $d.Name -Endpoint $ep -Props ([ordered]@{ type = [string]$d.Summary.Type; capacityGB = [math]::Round($d.Summary.Capacity / 1GB, 1); freeGB = [math]::Round($d.Summary.FreeSpace / 1GB, 1); accessible = [bool]$d.Summary.Accessible; multipleHostAccess = $d.Summary.MultipleHostAccess; hostCount = @($d.Host).Count })
            if ($nas) { Set-VsatFact -Asset $a -Name 'nas' -Value $nas }
            if ([string]$d.Summary.Type -eq 'vsan') {
                Invoke-VsatFact $a 'vsan' {
                    $cl = Get-Cluster -Server $srv -ErrorAction Stop | Where-Object { $_.VsanEnabled } | Select-Object -First 1
                    if (-not $cl) { return $null }
                    $cfg = Get-VsanClusterConfiguration -Server $srv -Cluster $cl -ErrorAction Stop
                    [ordered]@{ cluster = $cl.Name; encryption = [bool]$cfg.EncryptionEnabled; dataInTransitEncryption = [bool]$cfg.DataInTransitEncryptionEnabled; stretched = [bool]$cfg.StretchedClusterEnabled }
                }
            }
        }
        @($dss).Count
    }

    Invoke-VsatCollector -Evidence $Evidence -Name 'vsphere.vms' -Endpoint $ep -Affects @('VM-*') -Script {
        $props = 'Name', 'Runtime.Host', 'Runtime.PowerState', 'Config.Uuid', 'Config.InstanceUuid', 'Config.Template', 'Config.Firmware', 'Config.BootOptions', 'Config.ExtraConfig', 'Config.Hardware.Device', 'Config.Version', 'Config.KeyId', 'Config.GuestFullName', 'Config.Flags', 'Config.MaxMksConnections', 'Guest.ToolsVersionStatus2', 'Guest.ToolsRunningStatus', 'Guest.Net', 'Snapshot', 'Datastore', 'Network', 'ResourceConfig'
        $vms = Get-View -Server $srv -ViewType VirtualMachine -Property $props
        $n = 0
        $now = [DateTime]::UtcNow
        foreach ($v in $vms) {
            if (Test-VsatCancel) { break }
            $vid = "${ep}:" + (Get-VsatMoRef $v)
            $c = $v.Config
            if ($null -eq $c) {
                $a = Add-VsatAsset -Evidence $Evidence -Id $vid -Type 'vm' -Name $v.Name -Endpoint $ep
                foreach ($f in 'extraConfig', 'devices', 'security') { Set-VsatFact -Asset $a -Name $f -Status error -Value $null -ErrorMessage 'VM configuration unavailable (orphaned or inaccessible)' }
                continue
            }
            $ips = @($v.Guest.Net | Where-Object { $null -ne $_ } | ForEach-Object { $_.IpAddress } | Where-Object { $_ })
            $a = Add-VsatAsset -Evidence $Evidence -Id $vid -Type 'vm' -Name $v.Name -Endpoint $ep -Props ([ordered]@{
                    instanceUuid = $c.InstanceUuid; biosUuid = $c.Uuid; template = [bool]$c.Template; powerState = [string]$v.Runtime.PowerState
                    hardwareVersion = $c.Version; guest = $c.GuestFullName; ipAddresses = $ips
                })
            if ($v.Runtime.Host) { Add-VsatRelationship -Evidence $Evidence -Source $vid -Target ("${ep}:" + $v.Runtime.Host.Value) -Type runs-on -Provenance 'vsphere.vms' }
            foreach ($ds in $v.Datastore) { Add-VsatRelationship -Evidence $Evidence -Source $vid -Target ("${ep}:" + $ds.Value) -Type stores -Provenance 'vsphere.vms' }
            Invoke-VsatFact $a 'extraConfig' { $o = [ordered]@{}; foreach ($e in $c.ExtraConfig) { $o[$e.Key] = $e.Value }; $o }
            Invoke-VsatFact $a 'security' {
                [ordered]@{
                    firmware = [string]$c.Firmware; secureBoot = $(if ($c.BootOptions) { [bool]$c.BootOptions.EfiSecureBootEnabled } else { $false })
                    vtpm = [bool](@($c.Hardware.Device | Where-Object { $_.GetType().Name -eq 'VirtualTPM' }).Count)
                    encrypted = [bool]$c.KeyId; keyProvider = $(if ($c.KeyId) { $c.KeyId.ProviderId.Id } else { $null })
                    maxMksConnections = $c.MaxMksConnections
                    toolsStatus = [string]$v.Guest.ToolsVersionStatus2; toolsRunning = [string]$v.Guest.ToolsRunningStatus
                }
            }
            Invoke-VsatFact $a 'devices' {
                @(foreach ($d in $c.Hardware.Device) {
                        $t = $d.GetType().Name
                        if ($t -match '^(VirtualFloppy|VirtualCdrom|VirtualSerialPort|VirtualParallelPort|VirtualUSB|VirtualUSBController|VirtualUSBXHCIController|VirtualPCIPassthrough|VirtualSriovEthernetCard|VirtualE1000|VirtualE1000e|VirtualVmxnet3|VirtualVmxnet2|VirtualPCNet32|VirtualDisk|VirtualTPM)$') {
                            $o = [ordered]@{ type = $t; label = $d.DeviceInfo.Label; connected = $(if ($d.Connectable) { [bool]$d.Connectable.Connected } else { $null }); startConnected = $(if ($d.Connectable) { [bool]$d.Connectable.StartConnected } else { $null }) }
                            if ($t -eq 'VirtualDisk') { $o.mode = [string]$d.Backing.DiskMode; $o.datastore = $(if ($d.Backing.Datastore) { $d.Backing.Datastore.Value } else { $null }) }
                            if ($t -eq 'VirtualSerialPort' -and $d.Backing) { $o.backing = $d.Backing.GetType().Name; $o.serviceUri = $(if ($d.Backing.PSObject.Properties['ServiceURI']) { $d.Backing.ServiceURI } else { $null }) }
                            if ($d.PSObject.Properties['MacAddress']) {
                                $o.mac = $d.MacAddress
                                $b = $d.Backing
                                if ($b -and $b.PSObject.Properties['Port'] -and $b.Port) { $o.network = $netIndex[[string]$b.Port.PortgroupKey]; $o.portgroupKey = $b.Port.PortgroupKey; $o.port = $b.Port.PortKey }
                                elseif ($b -and $b.PSObject.Properties['OpaqueNetworkId']) { $o.opaqueNetworkId = $b.OpaqueNetworkId }
                                elseif ($b -and $b.PSObject.Properties['DeviceName'] -and $b.DeviceName -and $v.Runtime.Host) { $o.network = "${ep}:" + $v.Runtime.Host.Value + '/pg/' + $b.DeviceName; $o.networkName = $b.DeviceName }
                            }
                            $o
                        }
                    })
            }
            foreach ($d in @($a.facts.devices.value | Where-Object { $_.Contains('mac') })) {
                if ($d.network) { Add-VsatRelationship -Evidence $Evidence -Source $vid -Target $d.network -Type connects -Provenance 'vsphere.vms' -Props ([ordered]@{ nic = $d.label }) }
                elseif ($d.portgroupKey) {
                    # dvPortgroup keys may differ from MoRef values on older releases; record for correlation.
                    Add-VsatRelationship -Evidence $Evidence -Source $vid -Target ("${ep}:dvpg-key:" + $d.portgroupKey) -Type connects -Provenance 'vsphere.vms' -Confidence inferred -Props ([ordered]@{ nic = $d.label })
                }
                elseif ($d.opaqueNetworkId) { Add-VsatRelationship -Evidence $Evidence -Source $vid -Target ("opaque:" + $d.opaqueNetworkId) -Type connects -Provenance 'vsphere.vms' -Props ([ordered]@{ nic = $d.label }) }
            }
            Invoke-VsatFact $a 'snapshots' {
                if (-not $v.Snapshot) { return @() }
                $list = [System.Collections.Generic.List[object]]::new()
                $stack = New-Object System.Collections.Stack
                foreach ($s in $v.Snapshot.RootSnapshotList) { $stack.Push($s) }
                while ($stack.Count -gt 0) {
                    $s = $stack.Pop()
                    $list.Add([ordered]@{ name = $s.Name; createdUtc = $s.CreateTime.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ'); ageDays = [int]($now - $s.CreateTime.ToUniversalTime()).TotalDays })
                    foreach ($ch in $s.ChildSnapshotList) { $stack.Push($ch) }
                }
                , $list.ToArray()
            }
            $n++
        }
        $n
    }
}

function Add-VsatHostNetwork {
    param($Evidence, $Asset, $HostView, $Server, [hashtable]$NetIndex, [string]$Endpoint)
    $ep = $Endpoint; $hid = $Asset.id
    $net = $HostView.Config.Network
    if (-not $net) { Set-VsatFact -Asset $Asset -Name 'network' -Status error -Value $null -ErrorMessage 'Host network configuration unavailable'; return }
    $pnicIds = @{}
    foreach ($p in $net.Pnic) {
        $pid2 = "${hid}/pnic/" + $p.Device
        $pa = Add-VsatAsset -Evidence $Evidence -Id $pid2 -Type 'pnic' -Name ("{0} {1}" -f $Asset.name, $p.Device) -Endpoint $ep -Props ([ordered]@{ device = $p.Device; mac = $p.Mac; linkUp = [bool]$p.LinkSpeed; speedMb = $(if ($p.LinkSpeed) { $p.LinkSpeed.SpeedMb } else { 0 }) })
        Add-VsatRelationship -Evidence $Evidence -Source $hid -Target $pid2 -Type contains -Provenance 'vsphere.hosts'
        $pnicIds[$p.Key] = $pid2
    }
    # LLDP/CDP hints give immediate-neighbor evidence only, not the physical fabric.
    try {
        $ns = Get-View -Server $Server -Id $HostView.ConfigManager.NetworkSystem -ErrorAction Stop
        $hints = $ns.QueryNetworkHint($null)
        foreach ($hint in $hints) {
            $pid2 = "${hid}/pnic/" + $hint.Device
            $nb = $null
            if ($hint.ConnectedSwitchPort) { $nb = [ordered]@{ proto = 'CDP'; device = $hint.ConnectedSwitchPort.DevId; port = $hint.ConnectedSwitchPort.PortId; vlan = $hint.ConnectedSwitchPort.Vlan; mgmt = $hint.ConnectedSwitchPort.MgmtAddr } }
            elseif ($hint.LldpInfo) { $nb = [ordered]@{ proto = 'LLDP'; device = $hint.LldpInfo.ChassisId; port = $hint.LldpInfo.PortId; name = @($hint.LldpInfo.Parameter | Where-Object { $_.Key -eq 'System Name' } | Where-Object { $null -ne $_ } | ForEach-Object { $_.Value })[0]; vlan = @($hint.LldpInfo.Parameter | Where-Object { $_.Key -eq 'Vlan ID' } | Where-Object { $null -ne $_ } | ForEach-Object { $_.Value })[0] } }
            if ($nb -and $nb.device) {
                $nid = "physical:" + ([string]$nb.device).ToLowerInvariant()
                [void](Add-VsatAsset -Evidence $Evidence -Id $nid -Type 'physical-neighbor' -Name $(if ($nb.name) { $nb.name } else { $nb.device }) -Endpoint $ep -Props ([ordered]@{ protocol = $nb.proto; mgmt = $nb.mgmt }))
                Add-VsatRelationship -Evidence $Evidence -Source $pid2 -Target $nid -Type neighbor -Provenance 'vsphere.networkhint' -Props ([ordered]@{ port = $nb.port; nativeVlan = $nb.vlan })
            }
        }
        Set-VsatFact -Asset $Asset -Name 'neighbors' -Value @($hints | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ device = $_.Device; cdp = [bool]$_.ConnectedSwitchPort; lldp = [bool]$_.LldpInfo } })
    }
    catch { Set-VsatFact -Asset $Asset -Name 'neighbors' -Status (Get-VsatErrorClass $_) -Value $null -ErrorMessage $_.Exception.Message }

    foreach ($vs in $net.Vswitch) {
        $sid = "${hid}/vss/" + $vs.Name
        $sa = Add-VsatAsset -Evidence $Evidence -Id $sid -Type 'vss' -Name ("{0} {1}" -f $Asset.name, $vs.Name) -Endpoint $ep -Props ([ordered]@{ mtu = $vs.Mtu; uplinks = @($vs.Pnic | Where-Object { $null -ne $_ } | ForEach-Object { $pnicIds[$_] }) })
        Set-VsatFact -Asset $sa -Name 'policy' -Value ([ordered]@{ security = (ConvertTo-VsatSecurityPolicy $vs.Spec.Policy.Security); teaming = $(if ($vs.Spec.Policy.NicTeaming -and $vs.Spec.Policy.NicTeaming.NicOrder) { [ordered]@{ active = @($vs.Spec.Policy.NicTeaming.NicOrder.ActiveNic); standby = @($vs.Spec.Policy.NicTeaming.NicOrder.StandbyNic) } } else { $null }) })
        Add-VsatRelationship -Evidence $Evidence -Source $hid -Target $sid -Type contains -Provenance 'vsphere.hosts'
        foreach ($pk in $vs.Pnic) { if ($pnicIds[$pk]) { Add-VsatRelationship -Evidence $Evidence -Source $sid -Target $pnicIds[$pk] -Type uplink -Provenance 'vsphere.hosts' } }
    }
    foreach ($pg in $net.Portgroup) {
        $spec = $pg.Spec
        $gid = "${hid}/pg/" + $spec.Name
        # Effective policy = portgroup override merged over the parent vSwitch policy.
        $vs = $net.Vswitch | Where-Object { $_.Name -eq $spec.VswitchName } | Select-Object -First 1
        $parent = if ($vs) { ConvertTo-VsatSecurityPolicy $vs.Spec.Policy.Security } else { $null }
        $own = ConvertTo-VsatSecurityPolicy $spec.Policy.Security
        $eff = [ordered]@{}
        foreach ($k in 'allowPromiscuous', 'macChanges', 'forgedTransmits') {
            $ov = if ($own) { $own[$k] } else { $null }
            $eff[$k] = if ($null -ne $ov) { $ov } elseif ($parent) { $parent[$k] } else { $null }
        }
        $ga = Add-VsatAsset -Evidence $Evidence -Id $gid -Type 'portgroup' -Name ("{0} {1}" -f $Asset.name, $spec.Name) -Endpoint $ep -Props ([ordered]@{ portgroup = $spec.Name; vlan = $spec.VlanId; vswitch = $spec.VswitchName })
        Set-VsatFact -Asset $ga -Name 'policy' -Value ([ordered]@{ security = $eff; overridden = [bool]($own -and (@($own.Values | Where-Object { $null -ne $_ }).Count)) })
        Add-VsatRelationship -Evidence $Evidence -Source "${hid}/vss/$($spec.VswitchName)" -Target $gid -Type contains -Provenance 'vsphere.hosts'
        $NetIndex['net:' + $spec.Name] = $gid   # host-local: last host wins for name-based VSS backings (marked inferred on use)
    }
    $vmk = foreach ($v in $net.Vnic) {
        [ordered]@{ device = $v.Device; portgroup = $v.Portgroup; ip = $v.Spec.Ip.IpAddress; netstack = $v.Spec.NetStackInstanceKey; dvPortgroup = $(if ($v.Spec.DistributedVirtualPort) { $v.Spec.DistributedVirtualPort.PortgroupKey } else { $null }) }
    }
    try {
        $vnm = Get-View -Server $Server -Id $HostView.ConfigManager.VirtualNicManager -Property Info -ErrorAction Stop
        $svc = @{}
        foreach ($c in $vnm.Info.NetConfig) { foreach ($sel in $c.SelectedVnic) { $dev = ($sel -split '-')[-1]; if (-not $svc[$dev]) { $svc[$dev] = @() }; $svc[$dev] += $c.NicType } }
        foreach ($m in $vmk) { $m.services = @($svc[$m.device]) }
    }
    catch { }
    Set-VsatFact -Asset $Asset -Name 'vmkernel' -Value @($vmk)
}

#endregion vSphere collector

# ---- src/50-CollectNsx.ps1 ----
#region NSX collector
# Read-only NSX (NSX-T 3.2 / NSX 4.x / 9.x Policy + Manager API) collection.
# Every API call goes through Invoke-VsatRest, which enforces the read-only allowlist.

function Connect-VsatNsx {
    param([Parameter(Mandatory)][string]$Address, [Parameter(Mandatory)][pscredential]$Credential)
    $s = New-VsatRestSession -Address $Address -Kind nsx
    $user = $Credential.UserName
    $pass = $Credential.GetNetworkCredential().Password
    Register-VsatSecret $pass
    try {
        $body = 'j_username=' + [uri]::EscapeDataString($user) + '&j_password=' + [uri]::EscapeDataString($pass)
        $r = Invoke-VsatRest -Session $s -Method POST -Path '/api/session/create' -Body $body -ContentType 'application/x-www-form-urlencoded' -Raw
        $xsrf = $null
        $vals = $null
        if ($r.headers.TryGetValues('X-XSRF-TOKEN', [ref]$vals)) { $xsrf = @($vals)[0] }
        if (-not $xsrf) { throw "NSX Manager $Address did not return a session token; check the account and that the Policy API is available." }
        Register-VsatSecret $xsrf
        $s.headers['X-XSRF-TOKEN'] = $xsrf
    }
    catch {
        Close-VsatRestSession $s
        throw
    }
    finally { $pass = $null; $body = $null }
    return $s
}

function Invoke-VsatNsxGet {
    # Records a fact on an asset from one NSX GET; returns the value or $null.
    param($Session, $Asset, [string]$Fact, [string]$Path, [switch]$Paged)
    try {
        if ($Paged) {
            $r = Get-VsatNsxPaged -Session $Session -Path $Path
            if ($r.truncated) {
                Set-VsatFact -Asset $Asset -Name $Fact -Status error -Value $r.items -ErrorMessage "Result truncated: received $($r.items.Count) of $($r.expected)"
                return $r.items
            }
            Set-VsatFact -Asset $Asset -Name $Fact -Status ok -Value $r.items
            return $r.items
        }
        $v = Invoke-VsatRest -Session $Session -Path $Path
        Set-VsatFact -Asset $Asset -Name $Fact -Status $(if ($null -eq $v) { 'absent' } else { 'ok' }) -Value $v
        return $v
    }
    catch {
        $cls = Get-VsatErrorClass $_
        Set-VsatFact -Asset $Asset -Name $Fact -Status $cls -Value $null -ErrorMessage $_.Exception.Message
        return $null
    }
}

function ConvertTo-VsatNsxRef {
    # Normalizes NSX group/service references: "ANY" stays ANY, paths are kept verbatim.
    param($Values)
    $list = @($Values | Where-Object { $null -ne $_ } | Where-Object { $null -ne $_ } | ForEach-Object { [string]$_ })
    if ($list.Count -eq 0 -or $list -contains 'ANY') { return @('ANY') }
    return $list
}

function Invoke-VsatNsxCollection {
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)]$Endpoint, [Parameter(Mandatory)]$Session)
    $ep = $Endpoint.id
    $mgrId = "${ep}:manager"
    $mgr = Add-VsatAsset -Evidence $Evidence -Id $mgrId -Type 'nsx-manager' -Name $Endpoint.address -Endpoint $ep

    Invoke-VsatCollector -Evidence $Evidence -Name 'nsx.manager' -Endpoint $ep -Affects @('NSX-MGR-*') -Script {
        $ver = Invoke-VsatNsxGet $Session $mgr 'version' '/api/v1/node/version'
        if ($ver) {
            $mgr.version = [string](Get-VsatProp $ver 'product_version' (Get-VsatProp $ver 'node_version'))
            $Endpoint.product = 'NSX'; $Endpoint.version = $mgr.version
            $Endpoint.build = [string](Get-VsatProp $ver 'node_version')
        }
        [void](Invoke-VsatNsxGet $Session $mgr 'clusterStatus' '/api/v1/cluster/status')
        [void](Invoke-VsatNsxGet $Session $mgr 'backupConfig' '/api/v1/cluster/backups/config')
        [void](Invoke-VsatNsxGet $Session $mgr 'syslogExporters' '/api/v1/node/services/syslog/exporters')
        [void](Invoke-VsatNsxGet $Session $mgr 'authPolicy' '/api/v1/node/aaa/auth-policy')
        [void](Invoke-VsatNsxGet $Session $mgr 'ntp' '/api/v1/node/services/ntp')
        [void](Invoke-VsatNsxGet $Session $mgr 'certificatesRaw' '/api/v1/trust-management/certificates' -Paged)
        $raw = $mgr.facts.certificatesRaw
        $mgr.facts.Remove('certificatesRaw')
        if ($raw.status -notin @('ok', 'absent')) { Set-VsatFact -Asset $mgr -Name 'certificates' -Status $raw.status -Value $null -ErrorMessage (Get-VsatProp $raw 'error') }
        else {
            $parsed = foreach ($c in @($raw.value | Where-Object { $null -ne $_ })) {
                $info = [ordered]@{ id = Get-VsatProp $c 'id'; name = Get-VsatProp $c 'display_name'; usedBy = @(Get-VsatProp $c 'used_by' @() | Where-Object { $null -ne $_ } | ForEach-Object { Get-VsatProp $_ 'service_types' }); notAfter = $null; selfSigned = $null; subject = $null }
                try {
                    $pem = [string](Get-VsatProp $c 'pem_encoded')
                    $b64 = ($pem -split '-----END CERTIFICATE-----')[0] -replace '-----BEGIN CERTIFICATE-----', '' -replace '\s', ''
                    $x = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 (, [Convert]::FromBase64String($b64))
                    $info.notAfter = $x.NotAfter.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
                    $info.selfSigned = ($x.Subject -eq $x.Issuer)
                    $info.subject = $x.Subject
                }
                catch { }
                $info
            }
            Set-VsatFact -Asset $mgr -Name 'certificates' -Status $(if (@($parsed).Count) { 'ok' } else { 'absent' }) -Value @($parsed)
        }
        $cms = Invoke-VsatNsxGet $Session $mgr 'computeManagers' '/api/v1/fabric/compute-managers' -Paged
        [void](Invoke-VsatNsxGet $Session $mgr 'transportNodeStates' '/api/v1/transport-nodes/state' -Paged)
        [void](Invoke-VsatNsxGet $Session $mgr 'dfwSettings' '/policy/api/v1/infra/settings/firewall/security')
        [void](Invoke-VsatNsxGet $Session $mgr 'excludeList' '/policy/api/v1/infra/settings/firewall/security/exclude-list')
        [void](Invoke-VsatNsxGet $Session $mgr 'idsClusters' '/policy/api/v1/infra/settings/firewall/security/intrusion-services/cluster-configs' -Paged)
        [void](Invoke-VsatNsxGet $Session $mgr 'federation' '/policy/api/v1/infra/federation-config')
        if ($cms) {
            foreach ($cm in $cms) { Add-VsatRelationship -Evidence $Evidence -Source $mgrId -Target ("vcenter:" + [string](Get-VsatProp $cm 'server')) -Type manages -Provenance 'nsx.compute-managers' -Props ([ordered]@{ server = Get-VsatProp $cm 'server'; name = Get-VsatProp $cm 'display_name' }) }
        }
        1
    }

    Invoke-VsatCollector -Evidence $Evidence -Name 'nsx.fabric' -Endpoint $ep -Affects @('NSX-TN-*') -Script {
        $tns = Get-VsatNsxPaged -Session $Session -Path '/api/v1/transport-nodes'
        foreach ($tn in $tns.items) {
            $id = "${ep}:tn/" + (Get-VsatProp $tn 'node_id' (Get-VsatProp $tn 'id'))
            $info = Get-VsatProp $tn 'node_deployment_info'
            $a = Add-VsatAsset -Evidence $Evidence -Id $id -Type 'nsx-transport-node' -Name (Get-VsatProp $tn 'display_name') -Endpoint $ep -Props ([ordered]@{ resourceType = Get-VsatProp $info 'resource_type'; externalId = Get-VsatProp $info 'external_id'; fqdn = Get-VsatProp $info 'fqdn' })
            Add-VsatRelationship -Evidence $Evidence -Source $mgrId -Target $id -Type manages -Provenance 'nsx.fabric'
        }
        $ecs = Get-VsatNsxPaged -Session $Session -Path '/api/v1/edge-clusters'
        foreach ($ec in $ecs.items) {
            $id = "${ep}:edge-cluster/" + (Get-VsatProp $ec 'id')
            $members = @(Get-VsatProp $ec 'members' @())
            $a = Add-VsatAsset -Evidence $Evidence -Id $id -Type 'nsx-edge-cluster' -Name (Get-VsatProp $ec 'display_name') -Endpoint $ep -Props ([ordered]@{ memberCount = $members.Count })
            foreach ($m in $members) {
                $tnId = "${ep}:tn/" + (Get-VsatProp $m 'transport_node_id')
                Add-VsatRelationship -Evidence $Evidence -Source $id -Target $tnId -Type contains -Provenance 'nsx.fabric'
            }
        }
        $(if ($tns.truncated -or $ecs.truncated) { @{ count = $tns.items.Count; status = 'partial'; error = 'Truncated transport node or edge cluster listing' } } else { $tns.items.Count + $ecs.items.Count })
    }

    Invoke-VsatCollector -Evidence $Evidence -Name 'nsx.networking' -Endpoint $ep -Affects @('NSX-NET-*') -Script {
        $count = 0
        $t0s = Get-VsatNsxPaged -Session $Session -Path '/policy/api/v1/infra/tier-0s'
        foreach ($g in $t0s.items) {
            $path = [string](Get-VsatProp $g 'path'); $id = "${ep}:$path"
            $a = Add-VsatAsset -Evidence $Evidence -Id $id -Type 'nsx-t0' -Name (Get-VsatProp $g 'display_name') -Endpoint $ep -Props ([ordered]@{ path = $path; haMode = Get-VsatProp $g 'ha_mode'; failoverMode = Get-VsatProp $g 'failover_mode' })
            Add-VsatNsxLocaleServices -Evidence $Evidence -Session $Session -Asset $a -Path $path -Endpoint $ep
            $count++
        }
        $t1s = Get-VsatNsxPaged -Session $Session -Path '/policy/api/v1/infra/tier-1s'
        foreach ($g in $t1s.items) {
            $path = [string](Get-VsatProp $g 'path'); $id = "${ep}:$path"
            $t0 = Get-VsatProp $g 'tier0_path'
            $a = Add-VsatAsset -Evidence $Evidence -Id $id -Type 'nsx-t1' -Name (Get-VsatProp $g 'display_name') -Endpoint $ep -Props ([ordered]@{ path = $path; tier0Path = $t0; routeAdvertisement = @(Get-VsatProp $g 'route_advertisement_types' @()) })
            if ($t0) { Add-VsatRelationship -Evidence $Evidence -Source $id -Target "${ep}:$t0" -Type routes -Provenance 'nsx.networking' }
            Add-VsatNsxLocaleServices -Evidence $Evidence -Session $Session -Asset $a -Path $path -Endpoint $ep
            try {
                $nat = Get-VsatNsxPaged -Session $Session -Path "/policy/api/v1$path/nat/USER/nat-rules"
                Set-VsatFact -Asset $a -Name 'natRules' -Value @($nat.items | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ id = Get-VsatProp $_ 'id'; action = Get-VsatProp $_ 'action'; source = Get-VsatProp $_ 'source_network'; destination = Get-VsatProp $_ 'destination_network'; translated = Get-VsatProp $_ 'translated_network'; enabled = [bool](Get-VsatProp $_ "enabled" $true); firewallMatch = Get-VsatProp $_ 'firewall_match' } })
            }
            catch { Set-VsatFact -Asset $a -Name 'natRules' -Status (Get-VsatErrorClass $_) -Value $null -ErrorMessage $_.Exception.Message }
            $count++
        }
        $segs = Get-VsatNsxPaged -Session $Session -Path '/policy/api/v1/infra/segments'
        foreach ($s in $segs.items) {
            $path = [string](Get-VsatProp $s 'path'); $id = "${ep}:$path"
            $subnets = @(Get-VsatProp $s 'subnets' @() | Where-Object { $null -ne $_ } | ForEach-Object { Get-VsatProp $_ 'gateway_address' })
            $conn = Get-VsatProp $s 'connectivity_path'
            $a = Add-VsatAsset -Evidence $Evidence -Id $id -Type 'nsx-segment' -Name (Get-VsatProp $s 'display_name') -Endpoint $ep -Props ([ordered]@{ path = $path; uniqueId = Get-VsatProp $s 'unique_id'; vlanIds = @(Get-VsatProp $s 'vlan_ids' @()); transportZone = Get-VsatProp $s 'transport_zone_path'; connectivityPath = $conn; subnets = $subnets; adminState = Get-VsatProp $s 'admin_state'; type = $(if (@(Get-VsatProp $s 'vlan_ids' @()).Count -gt 0) { 'vlan' } else { 'overlay' }) })
            if ($conn) { Add-VsatRelationship -Evidence $Evidence -Source $id -Target "${ep}:$conn" -Type routes -Provenance 'nsx.networking' }
            $count++
        }
        $(if ($t0s.truncated -or $t1s.truncated -or $segs.truncated) { @{ count = $count; status = 'partial'; error = 'Truncated gateway or segment listing' } } else { $count })
    }

    Invoke-VsatCollector -Evidence $Evidence -Name 'nsx.groups' -Endpoint $ep -Affects @('NSX-DFW-*', 'NSX-EFF-*') -Script {
        $groups = Get-VsatNsxPaged -Session $Session -Path '/policy/api/v1/infra/domains/default/groups'
        $n = 0
        foreach ($g in $groups.items) {
            $path = [string](Get-VsatProp $g 'path'); $id = "${ep}:$path"
            $a = Add-VsatAsset -Evidence $Evidence -Id $id -Type 'nsx-group' -Name (Get-VsatProp $g 'display_name') -Endpoint $ep -Props ([ordered]@{ path = $path; expressionCount = @(Get-VsatProp $g 'expression' @()).Count; tags = @(Get-VsatProp $g 'tags' @() | Where-Object { $null -ne $_ } | ForEach-Object { "$(Get-VsatProp $_ 'scope')=$(Get-VsatProp $_ 'tag')" }) })
            if (Test-VsatCancel) { break }
            # Effective (realized) membership; configured expressions alone are insufficient.
            try {
                $vms = Get-VsatNsxPaged -Session $Session -Path "/policy/api/v1$path/members/virtual-machines" -PageSize 1000
                $ips = Get-VsatNsxPaged -Session $Session -Path "/policy/api/v1$path/members/ip-addresses" -PageSize 1000
                $st = if ($vms.truncated -or $ips.truncated) { 'error' } else { 'ok' }
                Set-VsatFact -Asset $a -Name 'members' -Status $st -Value ([ordered]@{
                        vms = @($vms.items | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ externalId = Get-VsatProp $_ 'external_id'; name = Get-VsatProp $_ 'display_name' } })
                        ips = @($ips.items | Where-Object { $null -ne $_ } | ForEach-Object { [string]$_ })
                    })
            }
            catch { Set-VsatFact -Asset $a -Name 'members' -Status (Get-VsatErrorClass $_) -Value $null -ErrorMessage $_.Exception.Message }
            $n++
        }
        $(if ($groups.truncated) { @{ count = $n; status = 'partial'; error = 'Truncated group listing' } } else { $n })
    }

    Invoke-VsatCollector -Evidence $Evidence -Name 'nsx.dfw' -Endpoint $ep -Affects @('NSX-DFW-*', 'NSX-EFF-*') -Script {
        Add-VsatNsxPolicies -Evidence $Evidence -Session $Session -Endpoint $ep -Kind 'security-policies' -ManagerId $mgrId
    }
    Invoke-VsatCollector -Evidence $Evidence -Name 'nsx.gfw' -Endpoint $ep -Affects @('NSX-GFW-*') -Script {
        Add-VsatNsxPolicies -Evidence $Evidence -Session $Session -Endpoint $ep -Kind 'gateway-policies' -ManagerId $mgrId
    }
    Invoke-VsatCollector -Evidence $Evidence -Name 'nsx.inventory' -Endpoint $ep -Affects @('NSX-EFF-*') -Script {
        $vms = Get-VsatNsxPaged -Session $Session -Path '/api/v1/fabric/virtual-machines'
        Set-VsatFact -Asset $mgr -Name 'fabricVms' -Status $(if ($vms.truncated) { 'error' } else { 'ok' }) -Value @($vms.items | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ externalId = Get-VsatProp $_ 'external_id'; name = Get-VsatProp $_ 'display_name'; sourceId = Get-VsatProp $_ 'source.target_id'; powerState = Get-VsatProp $_ 'power_state' } })
        $vms.items.Count
    }
}

function Add-VsatNsxLocaleServices {
    param($Evidence, $Session, $Asset, [string]$Path, [string]$Endpoint)
    try {
        $ls = Get-VsatNsxPaged -Session $Session -Path "/policy/api/v1$Path/locale-services"
        $bgp = @()
        foreach ($l in $ls.items) {
            $ec = Get-VsatProp $l 'edge_cluster_path'
            if ($ec) {
                $ecId = "${Endpoint}:edge-cluster/" + ($ec -split '/')[-1]
                Add-VsatRelationship -Evidence $Evidence -Source $Asset.id -Target $ecId -Type depends -Provenance 'nsx.networking'
            }
            if ($Asset.type -eq 'nsx-t0') {
                try {
                    $b = Invoke-VsatRest -Session $Session -Path ("/policy/api/v1$Path/locale-services/" + (Get-VsatProp $l 'id') + '/bgp')
                    $bgp += [ordered]@{ enabled = Get-VsatProp $b 'enabled'; localAs = Get-VsatProp $b 'local_as_num'; gracefulRestart = Get-VsatProp $b 'graceful_restart_config.mode' }
                }
                catch { }
            }
        }
        Set-VsatFact -Asset $Asset -Name 'localeServices' -Value @($ls.items | Where-Object { $null -ne $_ } | ForEach-Object { [ordered]@{ id = Get-VsatProp $_ 'id'; edgeClusterPath = Get-VsatProp $_ 'edge_cluster_path' } })
        if ($Asset.type -eq 'nsx-t0') { Set-VsatFact -Asset $Asset -Name 'bgp' -Value $bgp }
    }
    catch { Set-VsatFact -Asset $Asset -Name 'localeServices' -Status (Get-VsatErrorClass $_) -Value $null -ErrorMessage $_.Exception.Message }
}

function Add-VsatNsxPolicies {
    param($Evidence, $Session, [string]$Endpoint, [ValidateSet('security-policies', 'gateway-policies')][string]$Kind, [string]$ManagerId)
    $ep = $Endpoint
    $policies = Get-VsatNsxPaged -Session $Session -Path "/policy/api/v1/infra/domains/default/$Kind"
    $count = 0; $partial = $policies.truncated
    $ptype = if ($Kind -eq 'security-policies') { 'dfw' } else { 'gfw' }
    foreach ($p in $policies.items) {
        $path = [string](Get-VsatProp $p 'path'); $polId = "${ep}:$path"
        $pa = Add-VsatAsset -Evidence $Evidence -Id $polId -Type 'nsx-policy' -Name (Get-VsatProp $p 'display_name') -Endpoint $ep -Props ([ordered]@{
                path = $path; firewall = $ptype; category = Get-VsatProp $p 'category'; sequence = [long](Get-VsatProp $p 'sequence_number' 0)
                scope = @(ConvertTo-VsatNsxRef (Get-VsatProp $p 'scope')); stateful = Get-VsatProp $p 'stateful'; isDefault = [bool](Get-VsatProp $p 'is_default' $false)
            })
        try {
            $rules = Get-VsatNsxPaged -Session $Session -Path "/policy/api/v1$path/rules"
            if ($rules.truncated) { $partial = $true }
            foreach ($r in $rules.items) {
                $rpath = [string](Get-VsatProp $r 'path'); $rid = "${ep}:$rpath"
                $ra = Add-VsatAsset -Evidence $Evidence -Id $rid -Type 'nsx-rule' -Name (Get-VsatProp $r 'display_name') -Endpoint $ep -Props ([ordered]@{
                        path = $rpath; firewall = $ptype; policy = $polId; policyName = $pa.name; category = $pa.props.category
                        policySequence = $pa.props.sequence; sequence = [long](Get-VsatProp $r 'sequence_number' 0); ruleId = Get-VsatProp $r 'rule_id'
                        action = [string](Get-VsatProp $r 'action'); direction = Get-VsatProp $r 'direction' 'IN_OUT'; ipProtocol = Get-VsatProp $r 'ip_protocol' 'IPV4_IPV6'
                        sources = @(ConvertTo-VsatNsxRef (Get-VsatProp $r 'source_groups')); sourcesExcluded = [bool](Get-VsatProp $r 'sources_excluded' $false)
                        destinations = @(ConvertTo-VsatNsxRef (Get-VsatProp $r 'destination_groups')); destinationsExcluded = [bool](Get-VsatProp $r 'destinations_excluded' $false)
                        services = @(ConvertTo-VsatNsxRef (Get-VsatProp $r 'services')); profiles = @(ConvertTo-VsatNsxRef (Get-VsatProp $r 'profiles'))
                        appliedTo = @(ConvertTo-VsatNsxRef (Get-VsatProp $r 'scope')); policyAppliedTo = $pa.props.scope
                        disabled = [bool](Get-VsatProp $r 'disabled' $false); logged = [bool](Get-VsatProp $r 'logged' $false)
                        isDefault = ($pa.props.isDefault -or ([string](Get-VsatProp $r 'id') -match '^default-layer[23]-rule$'))
                    })
                Add-VsatRelationship -Evidence $Evidence -Source $polId -Target $rid -Type contains -Provenance "nsx.$ptype"
                foreach ($g in @($ra.props.appliedTo + $ra.props.policyAppliedTo | Where-Object { $_ -ne 'ANY' } | Select-Object -Unique)) {
                    Add-VsatRelationship -Evidence $Evidence -Source $rid -Target "${ep}:$g" -Type applies-to -Provenance "nsx.$ptype"
                }
                $count++
            }
        }
        catch {
            $partial = $true
            Set-VsatFact -Asset $pa -Name 'rules' -Status (Get-VsatErrorClass $_) -Value $null -ErrorMessage $_.Exception.Message
        }
    }
    if ($partial) { return @{ count = $count; status = 'partial'; error = 'One or more policy rule listings were truncated or failed' } }
    return $count
}

#endregion NSX collector

# ---- src/55-CollectHyperV.ps1 ----
#region Hyper-V collector
# Read-only Microsoft Hyper-V collection. One self-contained script runs on the host
# (via PowerShell remoting, locally, or exported for air-gapped hosts with
# -ExportCollector hyperv) and returns JSON facts in the VSAT evidence format.
# The script uses Get-* cmdlets and CIM reads only; see tests/ReadOnly.Tests.ps1.

$script:VsatHyperVCollector = @'
# VSAT Hyper-V collector (read-only). Compatible with Windows PowerShell 5.1 and PowerShell 7.
# Output: JSON document on stdout. It never changes configuration.
$ErrorActionPreference = 'Stop'
function F([scriptblock]$s) {
    try { $v = & $s; if ($null -eq $v) { return @{ status = 'absent'; value = $null } }; return @{ status = 'ok'; value = $v } }
    catch {
        $m = $_.Exception.Message
        $st = 'error'
        if ($m -match 'denied|not have permission|Unauthorized|privilege') { $st = 'denied' }
        elseif ($m -match 'not recognized|not supported|Invalid class|Invalid namespace|not found|cannot find') { $st = 'unsupported' }
        return @{ status = $st; value = $null; error = $m }
    }
}
$now = [DateTime]::UtcNow
$out = @{ collectorVersion = '1'; collectedUtc = $now.ToString('yyyy-MM-ddTHH:mm:ssZ'); host = @{}; vms = @(); switches = @() }
$os = Get-CimInstance -ClassName Win32_OperatingSystem
$cs = Get-CimInstance -ClassName Win32_ComputerSystem
$out.host.name = $cs.DNSHostName
$out.host.domain = $cs.Domain
$out.host.fqdn = if ($cs.PartOfDomain) { "$($cs.DNSHostName).$($cs.Domain)".ToLowerInvariant() } else { $cs.DNSHostName.ToLowerInvariant() }
$out.host.os = @{ caption = $os.Caption; version = $os.Version; build = [string]$os.BuildNumber; installationType = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue).InstallationType; ubr = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue).UBR }
$f = @{}
$f.vmhost = F { $h = Get-VMHost; @{ migrationEnabled = [bool]$h.VirtualMachineMigrationEnabled; migrationAuth = [string]$h.VirtualMachineMigrationAuthenticationType; anyNetworkForMigration = [bool]$h.UseAnyNetworkForMigration; enhancedSessionMode = [bool]$h.EnableEnhancedSessionMode; numaSpanning = [bool]$h.NumaSpanningEnabled; logicalProcessors = $h.LogicalProcessorCount; memoryGB = [math]::Round($h.MemoryCapacity / 1GB, 1) } }
$f.hotfix = F { $hf = @(Get-HotFix | Where-Object { $_.InstalledOn } | Sort-Object InstalledOn -Descending); if ($hf.Count -eq 0) { return $null }; @{ lastInstalledUtc = ([DateTime]$hf[0].InstalledOn).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ'); lastId = $hf[0].HotFixID; count = $hf.Count; ageDays = [int]($now - ([DateTime]$hf[0].InstalledOn).ToUniversalTime()).TotalDays } }
$f.deviceGuard = F { $d = Get-CimInstance -Namespace root\Microsoft\Windows\DeviceGuard -ClassName Win32_DeviceGuard; @{ vbsStatus = [int]$d.VirtualizationBasedSecurityStatus; servicesRunning = @($d.SecurityServicesRunning | ForEach-Object { [int]$_ }); servicesConfigured = @($d.SecurityServicesConfigured | ForEach-Object { [int]$_ }) } }
$f.secureBoot = F { [bool](Confirm-SecureBootUEFI) }
$f.tpm = F { $t = Get-Tpm; @{ present = [bool]$t.TpmPresent; ready = [bool]$t.TpmReady } }
$f.firewall = F { @(Get-NetFirewallProfile | ForEach-Object { @{ name = [string]$_.Name; enabled = [string]$_.Enabled; defaultInbound = [string]$_.DefaultInboundAction } }) }
$f.smb = F { $s = Get-SmbServerConfiguration; @{ smb1 = [bool]$s.EnableSMB1Protocol; requireSigning = [bool]$s.RequireSecuritySignature; encryptData = [bool]$s.EncryptData } }
$f.services = F { @(Get-Service -Name Spooler, WinRM, RemoteRegistry, TermService, sshd -ErrorAction SilentlyContinue | ForEach-Object { @{ key = $_.Name; running = ($_.Status -eq 'Running'); policy = [string]$_.StartType } }) }
$f.rdp = F { $t = Get-CimInstance -Namespace root\cimv2\TerminalServices -ClassName Win32_TSGeneralSetting -Filter "TerminalName='RDP-tcp'"; @{ nla = [bool]$t.UserAuthenticationRequired; securityLayer = [int]$t.SecurityLayer } }
$f.replica = F { $r = Get-VMReplicationServer; @{ enabled = [bool]$r.ReplicationEnabled; auth = [string]$r.AllowedAuthenticationType; kerberosPort = $r.KerberosAuthenticationPort; certPort = $r.CertificateAuthenticationPort } }
$f.admins = F { @(Get-LocalGroupMember -Group Administrators | ForEach-Object { @{ name = [string]$_.Name; class = [string]$_.ObjectClass } }) }
$f.hvAdmins = F { @(Get-LocalGroupMember -SID 'S-1-5-32-578' | ForEach-Object { @{ name = [string]$_.Name; class = [string]$_.ObjectClass } }) }
$f.cluster = F { if (-not (Get-Command Get-Cluster -ErrorAction SilentlyContinue)) { return $null }; $c = Get-Cluster; @{ name = [string]$c.Name; nodes = @(Get-ClusterNode | ForEach-Object { [string]$_.Name }) } }
$out.host.facts = $f
foreach ($sw in @(Get-VMSwitch)) {
    $out.switches += @{ id = [string]$sw.Id; name = $sw.Name; type = [string]$sw.SwitchType; allowManagementOS = [bool]$sw.AllowManagementOS; embeddedTeaming = [bool]$sw.EmbeddedTeamingEnabled; iov = [bool]$sw.IovEnabled
        uplinks = @($sw.NetAdapterInterfaceDescriptions); extensions = @(Get-VMSwitchExtension -VMSwitch $sw -ErrorAction SilentlyContinue | Where-Object { $_.Enabled } | ForEach-Object { $_.Name }) }
}
foreach ($vm in @(Get-VM)) {
    $vf = @{}
    $vf.security = F { $s = Get-VMSecurity -VM $vm; @{ tpm = [bool]$s.TpmEnabled; shielded = [bool]$s.Shielded; encryptState = [bool]$s.EncryptStateAndVmMigrationTraffic } }
    $vf.firmware = F { if ($vm.Generation -ne 2) { return @{ generation = 1 } }; $fw = Get-VMFirmware -VM $vm; @{ generation = 2; secureBoot = [string]$fw.SecureBoot; template = [string]$fw.SecureBootTemplate } }
    $vf.adapters = F { @(Get-VMNetworkAdapter -VM $vm | ForEach-Object { $v = Get-VMNetworkAdapterVlan -VMNetworkAdapter $_; @{ name = $_.Name; switch = $_.SwitchName; switchId = [string]$_.SwitchId; mac = $_.MacAddress; macSpoofing = [string]$_.MacAddressSpoofing; dhcpGuard = [string]$_.DhcpGuard; routerGuard = [string]$_.RouterGuard; portMirroring = [string]$_.PortMirroringMode; vlanMode = [string]$v.OperationMode; accessVlan = $v.AccessVlanId; allowedVlans = [string]$v.AllowedVlanIdListString; ips = @($_.IPAddresses) } }) }
    $vf.integration = F { @(Get-VMIntegrationService -VM $vm | ForEach-Object { @{ name = $_.Name; enabled = [bool]$_.Enabled } }) }
    $vf.checkpoints = F { @(Get-VMSnapshot -VM $vm | ForEach-Object { @{ name = $_.Name; createdUtc = $_.CreationTime.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ'); ageDays = [int]($now - $_.CreationTime.ToUniversalTime()).TotalDays } }) }
    $vf.devices = F { @(@(Get-VMDvdDrive -VM $vm | ForEach-Object { @{ type = 'dvd'; path = $_.Path } }) + @(Get-VMComPort -VM $vm | ForEach-Object { @{ type = 'com'; path = $_.Path } }) + @(Get-VMAssignableDevice -VM $vm -ErrorAction SilentlyContinue | ForEach-Object { @{ type = 'dda'; path = $_.LocationPath } }) + @(Get-VMHardDiskDrive -VM $vm | ForEach-Object { @{ type = 'disk'; path = $_.Path; controller = [string]$_.ControllerType } })) }
    $out.vms += @{ id = [string]$vm.Id; name = $vm.Name; state = [string]$vm.State; generation = $vm.Generation; configVersion = [string]$vm.Version; clustered = [bool]$vm.IsClustered; automaticStart = [string]$vm.AutomaticStartAction; checkpointType = [string]$vm.CheckpointType; facts = $vf }
}
$out | ConvertTo-Json -Depth 10 -Compress
'@

function Export-VsatCollector {
    param([Parameter(Mandatory)][ValidateSet('hyperv', 'kvm')][string]$Platform, [Parameter(Mandatory)][string]$OutputDir)
    if (-not (Test-Path -LiteralPath $OutputDir)) { [void](New-Item -ItemType Directory -Path $OutputDir -Force) }
    if ($Platform -eq 'hyperv') {
        $p = Join-Path $OutputDir 'vsat-hyperv-collect.ps1'
        Write-VsatFile -Path $p -Content ("# Run on the Hyper-V host (elevated): powershell -NoProfile -File vsat-hyperv-collect.ps1 > hyperv-<host>.json`n# Then import with: vsat.ps1 -HyperVEvidence hyperv-<host>.json`n" + $script:VsatHyperVCollector)
    }
    else {
        $p = Join-Path $OutputDir 'vsat-kvm-collect.sh'
        Write-VsatFile -Path $p -Content $script:VsatKvmCollector
    }
    return $p
}

function Invoke-VsatHyperVRemote {
    # Runs the read-only collector on the host. "localhost" runs in-process; "https://host"
    # uses WinRM over HTTPS; otherwise WinRM with Kerberos/Negotiate (message encryption).
    param([Parameter(Mandatory)][string]$Address, [pscredential]$Credential)
    $sb = [scriptblock]::Create($script:VsatHyperVCollector)
    if ($Address -in @('localhost', '.', '127.0.0.1')) { return [string](& $sb) }
    $useSsl = $Address -like 'https://*'
    $target = $Address -replace '^https?://', ''
    $params = @{ ComputerName = $target; ScriptBlock = $sb; ErrorAction = 'Stop' }
    if ($Credential) { $params.Credential = $Credential }
    if ($useSsl) { $params.UseSSL = $true }
    return [string](Invoke-Command @params)
}

function Add-VsatHyperVEvidence {
    # Maps collector JSON into assets/relationships. Used for live and imported evidence.
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)]$Endpoint, [Parameter(Mandatory)]$Data)
    $ep = $Endpoint.id
    $h = $Data.host
    $os = $h.os
    $Endpoint.product = [string]$os.caption; $Endpoint.version = [string]$os.version; $Endpoint.build = "$($os.build).$($os.ubr)"
    $hid = "${ep}:host"
    $ha = Add-VsatAsset -Evidence $Evidence -Id $hid -Type 'hyperv-host' -Name $(if ($h.fqdn) { $h.fqdn } else { $Endpoint.address }) -Endpoint $ep -Version ([string]$os.version) -Build ([string]$os.build) -Props ([ordered]@{ product = $os.caption; installationType = $os.installationType; ubr = $os.ubr; domain = $h.domain })
    foreach ($k in @($h.facts.Keys)) { $ha.facts[$k] = $h.facts[$k] }
    $cl = Get-VsatProp $h.facts 'cluster.value'
    if ($cl -and $cl.name) {
        $cid = "hvcluster:" + ([string]$cl.name).ToLowerInvariant()
        [void](Add-VsatAsset -Evidence $Evidence -Id $cid -Type 'hyperv-cluster' -Name $cl.name -Endpoint $ep -Props ([ordered]@{ nodes = @($cl.nodes) }))
        Add-VsatRelationship -Evidence $Evidence -Source $cid -Target $hid -Type contains -Provenance 'hyperv.host'
    }
    foreach ($s in @($Data.switches | Where-Object { $_ })) {
        $sid = "${ep}:vswitch/" + $s.id
        $sa = Add-VsatAsset -Evidence $Evidence -Id $sid -Type 'hyperv-vswitch' -Name "$($ha.name) $($s.name)" -Endpoint $ep -Props ([ordered]@{ switchType = $s.type; allowManagementOS = [bool]$s.allowManagementOS; embeddedTeaming = [bool]$s.embeddedTeaming; iov = [bool]$s.iov; uplinks = @($s.uplinks); extensions = @($s.extensions) })
        Add-VsatRelationship -Evidence $Evidence -Source $hid -Target $sid -Type contains -Provenance 'hyperv.network'
    }
    foreach ($v in @($Data.vms | Where-Object { $_ })) {
        $vid = "${ep}:vm/" + $v.id
        $ips = @($v.facts.adapters.value | Where-Object { $_ } | ForEach-Object { @($_.ips) } | Where-Object { $_ })
        $va = Add-VsatAsset -Evidence $Evidence -Id $vid -Type 'hyperv-vm' -Name $v.name -Endpoint $ep -Props ([ordered]@{ vmId = $v.id; state = $v.state; generation = $v.generation; configVersion = $v.configVersion; clustered = [bool]$v.clustered; automaticStart = $v.automaticStart; checkpointType = $v.checkpointType; ipAddresses = $ips })
        foreach ($k in @($v.facts.Keys)) { $va.facts[$k] = $v.facts[$k] }
        Add-VsatRelationship -Evidence $Evidence -Source $vid -Target $hid -Type runs-on -Provenance 'hyperv.vms'
        foreach ($ad in @($v.facts.adapters.value | Where-Object { $_ -and $_.switchId })) {
            Add-VsatRelationship -Evidence $Evidence -Source $vid -Target ("${ep}:vswitch/" + $ad.switchId) -Type connects -Provenance 'hyperv.vms' -Props ([ordered]@{ nic = $ad.name; vlanMode = $ad.vlanMode; vlan = $ad.accessVlan })
        }
    }
}

function Invoke-VsatHyperVCollection {
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)]$Endpoint, [pscredential]$Credential, [string]$ImportedJson)
    $vsatHvEndpoint = $Endpoint
    $json = $ImportedJson
    Invoke-VsatCollector -Evidence $Evidence -Name 'hyperv.host' -Endpoint $Endpoint.id -Affects @('HV-*') -Script {
        if (-not $json) { $json = Invoke-VsatHyperVRemote -Address $vsatHvEndpoint.address -Credential $Credential }
        $script:VsatHvData = ConvertFrom-VsatJson $json
        Add-VsatHyperVEvidence -Evidence $Evidence -Endpoint $vsatHvEndpoint -Data $script:VsatHvData
        1
    }
    $ok = @($Evidence.collection.collectors | Where-Object { $_.name -eq 'hyperv.host' -and $_.endpoint -eq $Endpoint.id })[-1].status -eq 'ok'
    foreach ($n in 'hyperv.vms', 'hyperv.network') {
        $cnt = if ($ok) { if ($n -eq 'hyperv.vms') { @($script:VsatHvData.vms).Count } else { @($script:VsatHvData.switches).Count } } else { 0 }
        $Evidence.collection.collectors.Add([ordered]@{ name = $n; endpoint = $Endpoint.id; status = $(if ($ok) { 'ok' } else { 'skipped' }); startedUtc = (Get-VsatUtcNow); endedUtc = (Get-VsatUtcNow); objectCount = $cnt; error = $(if ($ok) { $null } else { 'Host collection failed' }); affects = @() })
    }
    $Endpoint.status = if ($ok) { 'collected' } else { 'failed' }
}

#endregion Hyper-V collector

# ---- src/60-RuleEngine.ps1 ----
#region Rule engine
# Rules are data (rules/*.json, embedded at build time). Each canonical check runs once
# per applicable asset and may map to several framework controls. Only facts with
# status ok/absent can produce PASS/FAIL; anything else becomes UNKNOWN or ERROR.

$script:VsatRuleCache = $null
$script:VsatAdvisoryCache = $null

function Get-VsatRulePack {
    if ($script:VsatRuleCache) { return $script:VsatRuleCache }
    $rules = [System.Collections.Generic.List[object]]::new()
    $meta = $null
    foreach ($name in (Get-VsatEmbeddedNames 'rules/')) {
        $pack = ConvertFrom-VsatJson (Get-VsatEmbeddedText $name)
        if ($name -eq 'rules/pack.json') { $meta = $pack; continue }
        foreach ($r in @($pack.rules)) { $rules.Add($r) }
    }
    $ids = @{}
    $wps = @{}; foreach ($w in @($meta.workPackages)) { $wps[$w.id] = $w }
    foreach ($r in $rules) {
        if ($ids.ContainsKey($r.id)) { throw "Duplicate rule id $($r.id)" }
        $ids[$r.id] = $true
        # Expand compact framework references into explicit, honestly-labelled mappings.
        $fw = [System.Collections.Generic.List[object]]::new()
        if ($r.Contains('cis')) { $fw.Add([ordered]@{ framework = 'CIS VMware ESXi Benchmark'; edition = 'VSAT 1.x legacy mapping (ESXi 7.0 edition not recorded)'; control = [string]$r.cis; mappingStatus = 'unverified' }) }
        if ($r.Contains('scg')) { $fw.Add([ordered]@{ framework = 'Broadcom vSphere/NSX Security Configuration Guide'; edition = 'edition to be confirmed'; control = [string]$r.scg; mappingStatus = 'unverified' }) }
        if ($r.Contains('vsat') -or $fw.Count -eq 0) { $fw.Add([ordered]@{ framework = 'VSAT'; edition = $meta.version; control = $r.id; mappingStatus = 'verified' }) }
        $r.frameworks = @($fw)
        $m = if ($r.Contains('mitigation')) { $r.mitigation } else { [ordered]@{} }
        $wp = $wps[[string](Get-VsatProp $m 'workPackage' '')]
        if ($wp) {
            foreach ($k in 'validation', 'rollback', 'impact', 'maintenanceWindow') { if (-not $m.Contains($k)) { $m[$k] = $wp[$k] } }
        }
        $r.mitigation = $m
    }
    $script:VsatRuleCache = [ordered]@{ version = $meta.version; schemaVersion = $meta.schemaVersion; rules = $rules.ToArray(); meta = $meta }
    return $script:VsatRuleCache
}

function Get-VsatRulePackMeta { return (Get-VsatRulePack).meta }

function Get-VsatAdvisoryData {
    if ($script:VsatAdvisoryCache) { return $script:VsatAdvisoryCache }
    $script:VsatAdvisoryCache = ConvertFrom-VsatJson (Get-VsatEmbeddedText 'data/advisories.json')
    return $script:VsatAdvisoryCache
}

function Resolve-VsatFactValue {
    # Returns @{ state = ok|absent|missing-key|denied|error|unsupported|no-fact; value; error }
    param($Asset, [string]$Fact, [string]$Key, [string]$Path)
    if ($Fact -eq 'props') {
        $v = if ($Path) { Get-VsatProp $Asset.props $Path } else { $Asset.props }
        return @{ state = $(if ($null -eq $v) { 'missing-key' } else { 'ok' }); value = $v }
    }
    if (-not $Asset.facts.Contains($Fact)) { return @{ state = 'no-fact'; value = $null; error = "Fact '$Fact' was not collected" } }
    $f = $Asset.facts[$Fact]
    $st = [string]$f.status
    if ($st -ne 'ok' -and $st -ne 'absent') { return @{ state = $st; value = $null; error = (Get-VsatProp $f 'error') } }
    if ($st -eq 'absent') { return @{ state = 'absent'; value = $null } }
    $v = $f.value
    if ($Key) {
        if ($v -is [System.Collections.IDictionary]) {
            $hit = $null
            foreach ($k in $v.Keys) { if ([string]$k -eq $Key) { $hit = $k; break } }
            if ($null -eq $hit) { foreach ($k in $v.Keys) { if ([string]::Equals([string]$k, $Key, 'OrdinalIgnoreCase')) { $hit = $k; break } } }
            if ($null -eq $hit) { return @{ state = 'missing-key'; value = $null } }
            $v = $v[$hit]
        }
        else { return @{ state = 'missing-key'; value = $null } }
    }
    if ($Path) {
        $v = Get-VsatProp $v $Path
        if ($null -eq $v) { return @{ state = 'missing-key'; value = $null } }
    }
    return @{ state = 'ok'; value = $v }
}

function ConvertTo-VsatComparable {
    param($Value)
    if ($null -eq $Value) { return $null }
    if ($Value -is [bool]) { return $Value }
    $s = [string]$Value
    if ($s -match '^(?i:true|false)$') { return [bool]::Parse($s) }
    $d = 0.0
    if ([double]::TryParse($s, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d)) { return $d }
    return $s
}

function Test-VsatOperator {
    param($Actual, [string]$Op, $Expected)
    $a = ConvertTo-VsatComparable $Actual
    switch ($Op) {
        'eq' { $e = ConvertTo-VsatComparable $Expected; if ($a -is [string] -or $e -is [string]) { return [string]::Equals([string]$a, [string]$e, 'OrdinalIgnoreCase') }; return ($a -eq $e) }
        'ne' { return -not (Test-VsatOperator $Actual 'eq' $Expected) }
        'le' { if ($a -isnot [double]) { return $false }; return ($a -le [double]$Expected) }
        'ge' { if ($a -isnot [double]) { return $false }; return ($a -ge [double]$Expected) }
        'lt' { if ($a -isnot [double]) { return $false }; return ($a -lt [double]$Expected) }
        'gt' { if ($a -isnot [double]) { return $false }; return ($a -gt [double]$Expected) }
        'range' { if ($a -isnot [double]) { return $false }; return ($a -ge [double]$Expected[0] -and $a -le [double]$Expected[1]) }
        'in' { foreach ($e in @($Expected)) { if (Test-VsatOperator $Actual 'eq' $e) { return $true } }; return $false }
        'notin' { return -not (Test-VsatOperator $Actual 'in' $Expected) }
        'empty' { return ($null -eq $Actual -or [string]$Actual -eq '' -or ($Actual -is [array] -and $Actual.Count -eq 0)) }
        'notempty' { return -not (Test-VsatOperator $Actual 'empty' $null) }
        'match' { return ((Format-VsatValue $Actual) -match [string]$Expected) }
        'notmatch' { return -not ((Format-VsatValue $Actual) -match [string]$Expected) }
        default { throw "Unknown operator $Op" }
    }
}

function Format-VsatValue {
    param($Value)
    if ($null -eq $Value) { return '(not set)' }
    if ($Value -is [System.Collections.IDictionary]) { return ((@($Value.Keys | ForEach-Object { "$_=$(Format-VsatValue $Value[$_])" })) -join ', ') }
    if ($Value -is [array]) { if ($Value.Count -eq 0) { return '(none)' }; return ((@($Value | ForEach-Object { Format-VsatValue $_ })) -join '; ') }
    return [string]$Value
}

function Format-VsatExpectation {
    param([string]$Op, $Expected)
    switch ($Op) {
        'eq' { return "= $(Format-VsatValue $Expected)" }
        'ne' { return "!= $(Format-VsatValue $Expected)" }
        'le' { return "<= $Expected" }
        'ge' { return ">= $Expected" }
        'lt' { return "< $Expected" }
        'gt' { return "> $Expected" }
        'range' { return "between $($Expected[0]) and $($Expected[1])" }
        'in' { return "one of: $(Format-VsatValue $Expected)" }
        'notin' { return "not one of: $(Format-VsatValue $Expected)" }
        'empty' { return 'empty / not set' }
        'notempty' { return 'configured (non-empty)' }
        'match' { return "matches /$Expected/" }
        'notmatch' { return "does not match /$Expected/" }
    }
}

function Get-VsatRuleCheck {
    # Applies profile overrides on top of the base check definition.
    param($Rule, [string]$ProfileName)
    $check = [ordered]@{}
    foreach ($k in $Rule.check.Keys) { $check[$k] = $Rule.check[$k] }
    $prof = Get-VsatProp $Rule "profiles.$ProfileName"
    if ($prof) { foreach ($k in $prof.Keys) { $check[$k] = $prof[$k] } }
    return $check
}

function Test-VsatApplies {
    # Returns $null when applicable, otherwise a reason string (NOT_APPLICABLE).
    param($Rule, $Asset, $Context)
    $ap = Get-VsatProp $Rule 'applies'
    if (-not $ap) { return $null }
    $minV = Get-VsatProp $ap 'minVersion'; $maxV = Get-VsatProp $ap 'maxVersion'
    $ver = if ($Asset.version) { $Asset.version } else { $null }
    if (($minV -or $maxV) -and -not $ver) { return $null }  # version unknown: evaluate, facts decide
    if ($minV -and (Compare-VsatVersion $ver $minV) -lt 0) { return "Requires version $minV or later (observed $ver)" }
    if ($maxV -and (Compare-VsatVersion $ver $maxV) -gt 0) { return "Applies up to version $maxV (observed $ver)" }
    foreach ($c in @(Get-VsatProp $ap 'props' @())) {
        $v = Get-VsatProp $Asset.props $c.path
        if (-not (Test-VsatOperator $v $c.op (Get-VsatProp $c 'value'))) { return "Not applicable: $($c.path) is $(Format-VsatValue $v)" }
    }
    return $null
}

function New-VsatFinding {
    param($Rule, $Asset, [string]$Result, [string]$Observed, [string]$Expected, [string]$Note, [string[]]$Facts = @(), [string]$Confidence = 'observed', $Severity)
    $sev = if ($Severity) { $Severity } else { $Rule.severity }
    $f = [ordered]@{
        id = $null
        key = "$($Rule.id)|$($Asset.id)"
        ruleId = $Rule.id; ruleVersion = [int](Get-VsatProp $Rule 'version' 1)
        title = $Rule.title; domain = $Rule.domain
        assetId = $Asset.id; assetName = $Asset.name; assetType = $Asset.type
        result = $Result; severity = $sev
        priority = $null
        rationale = $(if ($Note) { "$($Rule.rationale) $Note".Trim() } else { $Rule.rationale })
        observed = $Observed; expected = $Expected
        evidence = @($Facts | ForEach-Object {
                $fs = if ($_ -eq 'props') { 'ok' } elseif ($Asset.facts.Contains($_)) { $Asset.facts[$_].status } else { 'not-collected' }
                [ordered]@{ fact = $_; status = $fs; endpoint = $Asset.endpoint; observedUtc = $Asset.observedUtc }
            })
        frameworks = @(Get-VsatProp $Rule 'frameworks' @())
        mitigation = (Get-VsatProp $Rule 'mitigation' ([ordered]@{}))
        limitations = (Get-VsatProp $Rule 'limitations' '')
        confidence = $Confidence
        exception = $null
    }
    return $f
}

function Invoke-VsatRuleOnAsset {
    param($Rule, $Asset, $Context)
    $na = Test-VsatApplies -Rule $Rule -Asset $Asset -Context $Context
    if ($na) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result 'NOT_APPLICABLE' -Observed $na -Expected '' ) }
    $check = Get-VsatRuleCheck -Rule $Rule -ProfileName $Context.profile
    try {
        switch ($check.type) {
            'setting' { return (Invoke-VsatSettingCheck -Rule $Rule -Asset $Asset -Check $check) }
            'service' { return (Invoke-VsatServiceCheck -Rule $Rule -Asset $Asset -Check $check) }
            'manual' {
                $obs = ''
                if ($check.Contains('fact')) {
                    $r = Resolve-VsatFactValue -Asset $Asset -Fact $check.fact -Key (Get-VsatProp $check 'key') -Path (Get-VsatProp $check 'path')
                    $obs = if ($r.state -eq 'ok') { Format-VsatValue $r.value } else { "evidence: $($r.state)" }
                }
                return (New-VsatFinding -Rule $Rule -Asset $Asset -Result 'MANUAL' -Observed $obs -Expected (Get-VsatProp $check 'guidance' 'Operator review required') -Facts @(Get-VsatProp $check 'fact' @()))
            }
            'script' {
                $fn = "Invoke-VsatCheck$($check.name)"
                if (-not (Get-Command $fn -ErrorAction SilentlyContinue)) { throw "Evaluator $fn not found" }
                $out = & $fn -Rule $Rule -Asset $Asset -Check $check -Context $Context
                return $out
            }
            default { throw "Unknown check type '$($check.type)'" }
        }
    }
    catch {
        return (New-VsatFinding -Rule $Rule -Asset $Asset -Result 'ERROR' -Observed ("Evaluator error: " + (Protect-VsatText $_.Exception.Message)) -Expected '')
    }
}

function Get-VsatEvidenceGapResult {
    param([string]$State)
    switch ($State) {
        'denied' { return 'UNKNOWN' }
        'unsupported' { return 'UNKNOWN' }
        'no-fact' { return 'UNKNOWN' }
        'error' { return 'ERROR' }
        default { return 'UNKNOWN' }
    }
}

function Get-VsatGapText {
    param($Resolved, [string]$Fact)
    switch ($Resolved.state) {
        'denied' { return "Cannot read $Fact (permission denied); this check is incomplete." }
        'unsupported' { return "$Fact is not exposed by this product version or API." }
        'no-fact' { return "$Fact was not collected (collector skipped or failed)." }
        'error' { return "Collection of $Fact failed: $($Resolved.error)" }
        default { return "$Fact unavailable ($($Resolved.state))." }
    }
}

function Invoke-VsatSettingCheck {
    param($Rule, $Asset, $Check)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact $Check.fact -Key (Get-VsatProp $Check 'key') -Path (Get-VsatProp $Check 'path')
    $label = if ($Check.Contains('key')) { $Check.key } elseif ($Check.Contains('path')) { "$($Check.fact).$($Check.path)" } else { $Check.fact }
    $expText = "$label " + (Format-VsatExpectation $Check.op (Get-VsatProp $Check 'value'))
    $conf = 'observed'
    $value = $r.value
    if ($r.state -eq 'missing-key' -or $r.state -eq 'absent') {
        $absent = Get-VsatProp $Check 'absent' 'fail'
        switch ($absent) {
            'default' { $value = $Check.default; $conf = 'inferred' }
            'pass' { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result 'PASS' -Observed "$label not set" -Expected $expText -Facts @($Check.fact) -Confidence inferred) }
            'na' { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result 'NOT_APPLICABLE' -Observed "$label not present" -Expected $expText -Facts @($Check.fact)) }
            'unknown' { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result 'UNKNOWN' -Observed "$label not reported" -Expected $expText -Facts @($Check.fact)) }
            default { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result 'FAIL' -Observed "$label not set" -Expected $expText -Facts @($Check.fact)) }
        }
    }
    elseif ($r.state -ne 'ok') {
        return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r $Check.fact) -Expected $expText -Facts @($Check.fact))
    }
    $ok = Test-VsatOperator $value $Check.op (Get-VsatProp $Check 'value')
    $obs = "$label = $(Format-VsatValue $value)"
    if ($conf -eq 'inferred') { $obs += ' (not set; product default assumed)' }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($ok) { 'PASS' } else { 'FAIL' }) -Observed $obs -Expected $expText -Facts @($Check.fact) -Confidence $conf)
}

function Invoke-VsatServiceCheck {
    param($Rule, $Asset, $Check)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'services'
    $exp = "running=$($Check.running), policy=$($Check.policy)"
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'services') -Expected $exp -Facts @('services')) }
    $svc = @($r.value | Where-Object { $_.key -eq $Check.key }) | Select-Object -First 1
    if (-not $svc) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result 'NOT_APPLICABLE' -Observed "Service $($Check.key) not present on this host" -Expected $exp -Facts @('services')) }
    $ok = ([bool]$svc.running -eq [bool]$Check.running) -and ([string]$svc.policy -eq [string]$Check.policy -or ($Check.policy -eq 'off' -and [string]$svc.policy -eq 'off'))
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($ok) { 'PASS' } else { 'FAIL' }) -Observed "running=$([bool]$svc.running), policy=$($svc.policy)" -Expected $exp -Facts @('services'))
}

function Test-VsatAssetExcluded {
    param($Asset, $Scope)
    foreach ($ex in @(Get-VsatProp $Scope 'exclusions' @())) {
        $pat = [string](Get-VsatProp $ex 'pattern')
        if ($pat -match '^(\w[\w-]*):(.*)$') {
            if ($Asset.type -like $Matches[1] -and ($Asset.name -like $Matches[2] -or $Asset.id -like $Matches[2])) { return $true }
        }
        elseif ($Asset.name -like $pat -or $Asset.id -like $pat) { return $true }
    }
    return $false
}

function Invoke-VsatRules {
    param([Parameter(Mandatory)]$Evidence, [string]$ProfileName = 'standard')
    $pack = Get-VsatRulePack
    $ctx = New-VsatRuleContext -Evidence $Evidence -ProfileName $ProfileName
    $findings = [System.Collections.Generic.List[object]]::new()
    $byType = @{}
    foreach ($a in $Evidence.assets) {
        if (-not $byType.ContainsKey($a.type)) { $byType[$a.type] = [System.Collections.Generic.List[object]]::new() }
        $byType[$a.type].Add($a)
    }
    $excluded = 0
    foreach ($rule in $pack.rules) {
        $profiles = @(Get-VsatProp $rule 'profilesEnabled' @('standard', 'strict'))
        if ($profiles -notcontains $ProfileName) { continue }
        foreach ($t in @($rule.assetType)) {
            if (-not $byType.ContainsKey($t)) { continue }
            foreach ($a in $byType[$t]) {
                if (Test-VsatAssetExcluded -Asset $a -Scope $Evidence.scope) { $excluded++; continue }
                foreach ($f in @(Invoke-VsatRuleOnAsset -Rule $rule -Asset $a -Context $ctx)) { if ($f) { $findings.Add($f) } }
            }
        }
    }
    $i = 0
    foreach ($f in $findings) { $i++; $f.id = 'F-{0:d6}' -f $i }
    return [ordered]@{ findings = $findings.ToArray(); rules = $pack.rules; rulePackVersion = $pack.version; excluded = $excluded; context = $ctx }
}

function New-VsatRuleContext {
    param($Evidence, [string]$ProfileName)
    $ctx = [ordered]@{ profile = $ProfileName; evidence = $Evidence; scope = $Evidence.scope; now = [DateTime]::UtcNow }
    # Indexes used by cross-asset evaluators.
    $ctx.assets = @{}; foreach ($a in $Evidence.assets) { $ctx.assets[$a.id] = $a }
    $ctx.out = @{}; $ctx.in = @{}
    foreach ($r in $Evidence.relationships) {
        if (-not $ctx.out.ContainsKey($r.source)) { $ctx.out[$r.source] = [System.Collections.Generic.List[object]]::new() }
        if (-not $ctx.in.ContainsKey($r.target)) { $ctx.in[$r.target] = [System.Collections.Generic.List[object]]::new() }
        $ctx.out[$r.source].Add($r); $ctx.in[$r.target].Add($r)
    }
    $ctx.nsxState = (Get-VsatNsxCoverage -Evidence $Evidence).state
    return $ctx
}

#endregion Rule engine

# ---- src/65-Evaluators.ps1 ----
#region Script evaluators
# Named evaluators referenced by rules with check.type = "script".
# Signature: -Rule -Asset -Check -Context ; return one finding.

function Get-VsatBranch {
    param([string]$Version, [int]$Parts = 2)
    if (-not $Version) { return $null }
    $p = $Version.Split('.')
    if ($p.Count -lt $Parts) { return $Version }
    return ($p[0..($Parts - 1)] -join '.')
}

function Get-VsatProductKey {
    param($Asset)
    switch ($Asset.type) {
        'host' { return 'esxi' }
        'vcenter' { return 'vcenter' }
        'nsx-manager' { return 'nsx' }
        default { return $Asset.type }
    }
}

function Invoke-VsatCheckAdvisory {
    param($Rule, $Asset, $Check, $Context)
    $data = Get-VsatAdvisoryData
    $product = Get-VsatProductKey $Asset
    $snap = "advisory snapshot $($data.snapshotDate)"
    $ver = [string]$Asset.version
    if (-not $ver) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed 'Product version not collected' -Expected "No applicable unpatched advisories ($snap)") }
    $branch = Get-VsatBranch $ver
    $build = 0L
    $byVersion = ($product -eq 'nsx')
    if (-not $byVersion -and -not [long]::TryParse([string]$Asset.build, [ref]$build)) {
        return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed "Build number not collected (version $ver)" -Expected "No applicable unpatched advisories ($snap)")
    }
    $exposed = [System.Collections.Generic.List[object]]::new()
    $hadData = $false
    foreach ($adv in @($data.advisories)) {
        $entries = @($adv.affected | Where-Object { $_.product -eq $product -and $_.branch -eq $branch })
        if ($entries.Count -eq 0) { continue }
        $hadData = $true
        # Select the fix line(s): greatest lower bound not above the observed build/version.
        if ($byVersion) {
            $cand = @($entries | Where-Object { -not $_.Contains('minVersion') -or (Compare-VsatVersion $ver $_.minVersion) -ge 0 })
            if ($cand.Count -eq 0) { continue }
            $best = ($cand | ForEach-Object { if ($_.Contains('minVersion')) { $_.minVersion } else { '0' } } | Sort-Object { [version](($_ + '.0.0.0').Split('.')[0..3] -join '.') } | Select-Object -Last 1)
            $sel = @($cand | Where-Object { ($(if ($_.Contains('minVersion')) { $_.minVersion } else { '0' })) -eq $best })
            foreach ($e in $sel) {
                if ($null -eq $e.fixedVersionNumber -or (Compare-VsatVersion $ver $e.fixedVersionNumber) -lt 0) { $exposed.Add([ordered]@{ id = $adv.id; severity = $adv.severity; kev = [bool]$adv.knownExploited; fix = $e.fixedVersion; cves = @($(if ($e.Contains('cves')) { $e.cves } else { $adv.cves })) }) }
            }
        }
        else {
            # Broadcom build numbers are not ordered across update lines (e.g. 8.0 U2d > 8.0 U3 GA),
            # so select the fix line by update level first and compare builds only within it.
            $hostUpd = $null
            $vp = $ver.Split('.')
            if ($vp.Count -ge 3) { $tmp = 0; if ([int]::TryParse($vp[2], [ref]$tmp)) { $hostUpd = $tmp } }
            $withUpd = @($entries | ForEach-Object { $u = $null; if ([string]$_.fixedVersion -match 'Update\s+(\d+)') { $u = [int]$Matches[1] } elseif ($_.fixedVersion) { $u = 0 }; @{ e = $_; u = $u } })
            $sel = @()
            if ($null -ne $hostUpd -and @($withUpd | Where-Object { $null -ne $_.u }).Count -eq $withUpd.Count) {
                $same = @($withUpd | Where-Object { $_.u -eq $hostUpd })
                if ($same.Count) { $sel = @($same | ForEach-Object { $_.e }) }
                else {
                    $higher = @($withUpd | Where-Object { $_.u -gt $hostUpd } | Sort-Object { $_.u })
                    if ($higher.Count) { $lowest = $higher[0].u; $sel = @($higher | Where-Object { $_.u -eq $lowest } | ForEach-Object { $_.e }) }
                    else { $top = ($withUpd | ForEach-Object { $_.u } | Measure-Object -Maximum).Maximum; $sel = @($withUpd | Where-Object { $_.u -eq $top } | ForEach-Object { $_.e }) }
                }
            }
            if ($sel.Count -eq 0) {
                $cand = @($entries | Where-Object { [long](Get-VsatProp $_ 'minBuild' 0) -le $build })
                if ($cand.Count -eq 0) { continue }
                $maxMin = ($cand | ForEach-Object { [long](Get-VsatProp $_ 'minBuild' 0) } | Measure-Object -Maximum).Maximum
                $sel = @($cand | Where-Object { [long](Get-VsatProp $_ 'minBuild' 0) -eq $maxMin })
            }
            foreach ($e in $sel) {
                $fb = Get-VsatProp $e 'fixedBuild'
                if ($null -eq $fb -or $build -lt [long]$fb) {
                    $exposed.Add([ordered]@{ id = $adv.id; severity = $adv.severity; kev = [bool]$adv.knownExploited; fix = $(if ($e.fixedVersion) { $e.fixedVersion } else { 'no public fix for this line' }); cves = @($(if ($e.Contains('cves')) { $e.cves } else { $adv.cves })) })
                }
            }
        }
    }
    $obsBase = "$product $ver" + $(if ($build) { " build $build" } else { '' })
    if (-not $hadData) {
        return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed "$obsBase; no advisory data for branch $branch in $snap" -Expected 'Build at or above fixed builds of applicable advisories' -Note 'Absence of advisory data is not evidence of safety.')
    }
    if ($exposed.Count -eq 0) {
        return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed "$obsBase; not below fixed builds of advisories in $snap" -Expected 'Build at or above fixed builds of applicable advisories' -Note 'Advisories published after the snapshot date are not evaluated.')
    }
    $uniq = @{}
    foreach ($x in $exposed) { $uniq[$x.id] = $x }
    $items = @($uniq.Values)
    $sev = 'medium'
    if (@($items | Where-Object { $_.severity -eq 'critical' -or $_.kev }).Count) { $sev = 'critical' }
    elseif (@($items | Where-Object { $_.severity -eq 'important' }).Count) { $sev = 'high' }
    $desc = ($items | Sort-Object { $_.id } | ForEach-Object { "$($_.id)$(if ($_.kev) { ' [known exploited]' }) -> $($_.fix)" }) -join '; '
    $f = New-VsatFinding -Rule $Rule -Asset $Asset -Result FAIL -Observed "$obsBase exposed: $desc" -Expected "Build at or above fixed builds ($snap)" -Severity $sev -Note 'Version exposure is not proof of exploitability; verify vendor workarounds and OEM images.'
    $f.advisories = $items
    return $f
}

function Invoke-VsatCheckLifecycle {
    param($Rule, $Asset, $Check, $Context)
    $data = Get-VsatAdvisoryData
    $product = Get-VsatProductKey $Asset
    $ver = [string]$Asset.version
    if (-not $ver) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed 'Version not collected' -Expected 'Supported release') }
    $branch = Get-VsatBranch $ver
    $major = $ver.Split('.')[0]
    $row = @($data.lifecycle | Where-Object { $_.product -eq $product -and ($_.branch -eq $branch -or $_.branch -eq "$major.x") }) | Select-Object -First 1
    if (-not $row) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed "$product $ver; no lifecycle data for $branch" -Expected 'Release within general support') }
    $now = $Context.now
    $eogs = Get-VsatProp $row 'endOfGeneralSupport'; $eotg = Get-VsatProp $row 'endOfTechnicalGuidance'
    if ($eogs -and [DateTime]::Parse($eogs, [Globalization.CultureInfo]::InvariantCulture) -lt $now) {
        return (New-VsatFinding -Rule $Rule -Asset $Asset -Result FAIL -Observed "$product $branch end of general support $eogs$(if ($eotg) { "; technical guidance ends $eotg" })" -Expected 'Release within general support' -Note 'Out-of-support releases no longer receive routine security fixes.')
    }
    if (-not $eogs) {
        return (New-VsatFinding -Rule $Rule -Asset $Asset -Result MANUAL -Observed "$product $branch end-of-general-support date not verified in data snapshot$(if ($eotg) { "; technical guidance ends $eotg" })" -Expected 'Confirm support status in the vendor lifecycle portal')
    }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed "$product $branch general support until $eogs" -Expected 'Release within general support')
}

function Invoke-VsatCheckPasswordQuality {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'advanced' -Key 'Security.PasswordQualityControl'
    $min = [int]$Check.minLength
    $exp = "Security.PasswordQualityControl enforces minimum length >= $min for every character-class count"
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($r.state -eq 'missing-key') { 'UNKNOWN' } else { Get-VsatEvidenceGapResult $r.state }) -Observed (Get-VsatGapText $r 'advanced') -Expected $exp -Facts @('advanced')) }
    $v = [string]$r.value
    if ($v -notmatch 'min=([^\s]+)') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result FAIL -Observed "Security.PasswordQualityControl = $v" -Expected $exp -Facts @('advanced')) }
    $parts = $Matches[1].Split(',')
    $numeric = @($parts | Where-Object { $_ -ne 'disabled' })
    $ok = ($parts.Count -eq 5 -and $numeric.Count -gt 0 -and @($numeric | Where-Object { [int]$_ -lt $min }).Count -eq 0)
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($ok) { 'PASS' } else { 'FAIL' }) -Observed "Security.PasswordQualityControl = $v" -Expected $exp -Facts @('advanced'))
}

function Invoke-VsatCheckNtp {
    param($Rule, $Asset, $Check, $Context)
    $n = Resolve-VsatFactValue -Asset $Asset -Fact 'ntp'
    $s = Resolve-VsatFactValue -Asset $Asset -Fact 'services'
    $minServers = [int](Get-VsatProp $Check 'minServers' 1)
    $exp = "At least $minServers time source(s) configured and the time service running"
    if ($n.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $n.state) -Observed (Get-VsatGapText $n 'ntp') -Expected $exp -Facts @('ntp')) }
    $servers = @($n.value.servers | Where-Object { $_ })
    $running = $null
    if ($s.state -eq 'ok') { $running = [bool](@($s.value | Where-Object { $_.key -in @('ntpd', 'ptpd') -and $_.running }).Count) }
    $ok = ($servers.Count -ge $minServers -and $running -ne $false)
    $obs = "servers: $(Format-VsatValue $servers); service running: $(if ($null -eq $running) { 'unknown' } else { $running })"
    $res = if ($ok -and $null -eq $running) { 'UNKNOWN' } elseif ($ok) { 'PASS' } else { 'FAIL' }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $res -Observed $obs -Expected $exp -Facts @('ntp', 'services'))
}

function Invoke-VsatCheckSyslogRemote {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'advanced' -Key 'Syslog.global.logHost'
    $exp = 'Syslog.global.logHost set to an authorized remote collector'
    if ($r.state -eq 'missing-key') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result FAIL -Observed 'Syslog.global.logHost not set' -Expected $exp -Facts @('advanced')) }
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'advanced') -Expected $exp -Facts @('advanced')) }
    $v = [string]$r.value
    if (-not $v.Trim()) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result FAIL -Observed 'Syslog.global.logHost is empty' -Expected $exp -Facts @('advanced')) }
    $auth = @($Context.scope.authorizedSyslogTargets)
    if ($auth.Count -gt 0) {
        $targets = @($v.Split(',') | ForEach-Object { $_.Trim() } | Where-Object { $_ })
        $bad = @($targets | Where-Object { $t = $_; -not @($auth | Where-Object { $t -like "*$_*" }).Count })
        if ($bad.Count) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result FAIL -Observed "Unauthorized syslog target(s): $($bad -join ', ')" -Expected $exp -Facts @('advanced')) }
        return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed "Syslog.global.logHost = $v" -Expected $exp -Facts @('advanced'))
    }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed "Syslog.global.logHost = $v" -Expected $exp -Facts @('advanced') -Note 'Authorized targets not supplied in scope; destination not validated.')
}

function Invoke-VsatCheckCoredump {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'coredump'
    $exp = 'Network core dump collector enabled'
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'coredump') -Expected $exp -Facts @('coredump')) }
    $ok = [bool]$r.value.networkEnabled
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($ok) { 'PASS' } else { 'FAIL' }) -Observed "network enabled: $($r.value.networkEnabled); server: $(Format-VsatValue $r.value.networkServer); active dump files: $($r.value.fileActive)" -Expected $exp -Facts @('coredump'))
}

function Invoke-VsatCheckFirewallAllIp {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'firewall'
    $exp = 'Enabled management rulesets restrict allowed source IPs'
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'firewall') -Expected $exp -Facts @('firewall')) }
    $mgmt = @($Check.rulesets)
    $open = @($r.value.rulesets | Where-Object { $_.enabled -and $_.allIp -and $mgmt -contains $_.key } | ForEach-Object { $_.key })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($open.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($open.Count) { "Open to all IPs: $($open -join ', ')" } else { 'No enabled management ruleset allows all IPs' }) -Expected $exp -Facts @('firewall'))
}

function Invoke-VsatCheckCertExpiry {
    param($Rule, $Asset, $Check, $Context)
    $fact = [string]$Check.fact
    $r = Resolve-VsatFactValue -Asset $Asset -Fact $fact
    $days = [int](Get-VsatProp $Check 'days' 30)
    $exp = "Certificates valid for more than $days days"
    if ($r.state -eq 'absent') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed 'No certificate reported' -Expected $exp -Facts @($fact)) }
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r $fact) -Expected $exp -Facts @($fact)) }
    $certs = @($r.value)
    $bad = @(); $unknown = 0
    foreach ($c in $certs) {
        if (-not $c.notAfter) { $unknown++; continue }
        $na = [DateTime]::Parse($c.notAfter, [Globalization.CultureInfo]::InvariantCulture).ToUniversalTime()
        if ($na -lt $Context.now.AddDays($days)) { $bad += "$(if ($c.Contains('name') -and $c.name) { $c.name } else { $c.subject }) expires $($c.notAfter)" }
    }
    if ($bad.Count) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result FAIL -Observed ($bad -join '; ') -Expected $exp -Facts @($fact)) }
    if ($unknown -eq $certs.Count) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed 'Certificate expiry could not be parsed' -Expected $exp -Facts @($fact)) }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed "$($certs.Count - $unknown) certificate(s) valid beyond $days days" -Expected $exp -Facts @($fact))
}

function Invoke-VsatCheckIscsiChap {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'iscsiAdapters'
    $exp = 'Every iSCSI adapter requires unidirectional and mutual CHAP'
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'iscsiAdapters') -Expected $exp -Facts @('iscsiAdapters')) }
    $ads = @($r.value)
    if ($ads.Count -eq 0) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'No iSCSI adapters' -Expected $exp -Facts @('iscsiAdapters')) }
    $bad = @($ads | Where-Object { $_.chapLevel -ne 'required' -or $_.mutualChapLevel -ne 'required' } | ForEach-Object { "$($_.adapter) chap=$(Format-VsatValue $_.chapLevel) mutual=$(Format-VsatValue $_.mutualChapLevel)" })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($bad.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($bad.Count) { $bad -join '; ' } else { "$($ads.Count) adapter(s) require mutual CHAP" }) -Expected $exp -Facts @('iscsiAdapters'))
}

function Invoke-VsatCheckVmkSeparation {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'vmkernel'
    $exp = 'Management, vMotion and storage traffic on separate VMkernel adapters'
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'vmkernel') -Expected $exp -Facts @('vmkernel')) }
    $shared = @($r.value | Where-Object { $s = @($_.services); ($s -contains 'management') -and (($s -contains 'vmotion') -or ($s -contains 'vsan') -or ($s -contains 'vSphereProvisioning')) } | ForEach-Object { "$($_.device): $(@($_.services) -join ',')" })
    $noSvc = @($r.value | Where-Object { -not $_.Contains('services') }).Count
    if ($noSvc -eq @($r.value).Count -and $noSvc -gt 0) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed 'VMkernel service tags not readable' -Expected $exp -Facts @('vmkernel')) }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($shared.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($shared.Count) { "Shared: $($shared -join '; ')" } else { "$(@($r.value).Count) VMkernel adapter(s), no management sharing" }) -Expected $exp -Facts @('vmkernel') -Note 'VLAN separation is not proof of firewall isolation.')
}

function Invoke-VsatCheckVmDevices {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'devices'
    $types = @($Check.deviceTypes)
    $connectedOnly = [bool](Get-VsatProp $Check 'connectedOnly' $false)
    $exp = if ($connectedOnly) { "No connected $($types -join '/') devices" } else { "No $($types -join '/') devices present" }
    if ($r.state -eq 'absent') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed 'No devices reported' -Expected $exp -Facts @('devices')) }
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'devices') -Expected $exp -Facts @('devices')) }
    $hits = @($r.value | Where-Object { $types -contains $_.type -and (-not $connectedOnly -or $_.connected -or $_.startConnected) })
    if ($Check.Contains('diskMode')) { $hits = @($r.value | Where-Object { $_.type -eq 'VirtualDisk' -and @($Check.diskMode) -contains $_.mode }) }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($hits.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($hits.Count) { ($hits | ForEach-Object { "$($_.label)$(if ($_.connected) { ' (connected)' })" }) -join '; ' } else { 'None' }) -Expected $exp -Facts @('devices'))
}

function Invoke-VsatCheckSnapshotAge {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'snapshots'
    $max = [int]$Check.maxDays
    $exp = "No snapshots older than $max days"
    if ($r.state -eq 'absent') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed 'No snapshots' -Expected $exp -Facts @('snapshots')) }
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'snapshots') -Expected $exp -Facts @('snapshots')) }
    $old = @($r.value | Where-Object { [int]$_.ageDays -gt $max })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($old.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($old.Count) { ($old | ForEach-Object { "'$($_.name)' $($_.ageDays)d" }) -join '; ' } else { "$(@($r.value).Count) snapshot(s), none older than $max days" }) -Expected $exp -Facts @('snapshots') -Note 'A snapshot is not a backup.')
}

function Invoke-VsatCheckVmTools {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'security'
    $exp = 'VMware Tools current or supported'
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'security') -Expected $exp -Facts @('security')) }
    $st = [string]$r.value.toolsStatus
    if ($Asset.props.powerState -ne 'poweredOn') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed "VM is $($Asset.props.powerState); Tools status not evaluated" -Expected $exp -Facts @('security')) }
    $res = switch -Regex ($st) { '^guestTools(Current|Supported|Unmanaged)$' { 'PASS' } '^guestTools(NeedUpgrade|TooOld|Blacklisted|TooNew|NotInstalled)$' { 'FAIL' } default { 'UNKNOWN' } }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $res -Observed "toolsVersionStatus2 = $(Format-VsatValue $st)" -Expected $exp -Facts @('security'))
}

function Invoke-VsatCheckNativeVlan {
    param($Rule, $Asset, $Check, $Context)
    $vlan = $Asset.props.vlan
    $exp = 'Port group VLAN differs from the upstream native VLAN'
    $scoped = @($Context.scope.nativeVlans | Where-Object { $_.switch -eq '*' -or $Asset.name -like "*$($_.switch)*" -or [string]$Asset.props.vswitch -eq $_.switch })
    $native = $null; $source = $null
    if ($scoped.Count) { $native = [int]$scoped[0].vlan; $source = 'operator scope' }
    else {
        # CDP reports the upstream native VLAN for the uplink; LLDP may report the port VLAN ID.
        $hostId = ($Asset.id -split '/pg/')[0]
        $vals = @()
        foreach ($rel in @($Context.out[$hostId])) {
            if ($rel.type -ne 'contains') { continue }
            foreach ($n in @($Context.out[$rel.target])) { if ($n.type -eq 'neighbor' -and $n.props.nativeVlan) { $vals += [int]$n.props.nativeVlan } }
        }
        $vals = @($vals | Select-Object -Unique)
        if ($vals.Count -eq 1) { $native = $vals[0]; $source = 'CDP/LLDP neighbor evidence' }
    }
    if ($null -eq $native) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed "VLAN $vlan; upstream native VLAN not known (supply nativeVlans in the scope file or enable CDP/LLDP)" -Expected $exp -Facts @('props')) }
    $ok = ([int]$vlan -ne $native)
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($ok) { 'PASS' } else { 'FAIL' }) -Observed "VLAN $vlan; native VLAN $native ($source)" -Expected $exp -Facts @('props') -Confidence $(if ($source -eq 'operator scope') { 'observed' } else { 'inferred' }))
}

function Invoke-VsatCheckReservedVlan {
    param($Rule, $Asset, $Check, $Context)
    $vlans = @($Asset.props.vlan)
    $reserved = @($Check.reserved)
    $exp = "VLAN not in reserved range(s) $($reserved -join ', ')"
    $bad = @()
    foreach ($v in $vlans) {
        $n = 0
        if (-not [int]::TryParse([string]$v, [ref]$n)) { continue }
        foreach ($rg in $reserved) { $p = $rg.Split('-'); if ($n -ge [int]$p[0] -and $n -le [int]$p[-1]) { $bad += $n } }
    }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($bad.Count) { 'FAIL' } else { 'PASS' }) -Observed "VLAN $(Format-VsatValue $vlans)" -Expected $exp -Facts @('props'))
}

function Invoke-VsatCheckNetflowCollector {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'policy' -Path 'netflow'
    $exp = 'NetFlow/IPFIX exported only to authorized collectors'
    if ($r.state -eq 'missing-key') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'IPFIX not configured' -Expected $exp -Facts @('policy')) }
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'policy') -Expected $exp -Facts @('policy')) }
    $ip = [string]$r.value.collectorIp
    if (-not $ip) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'No IPFIX collector configured' -Expected $exp -Facts @('policy')) }
    $auth = @($Context.scope.authorizedNetflowCollectors)
    if ($auth.Count -eq 0) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result MANUAL -Observed "Collector $ip (authorized list not supplied)" -Expected $exp -Facts @('policy')) }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($auth -contains $ip) { 'PASS' } else { 'FAIL' }) -Observed "Collector $ip" -Expected $exp -Facts @('policy'))
}

function Invoke-VsatCheckHealthCheck {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'policy' -Path 'healthCheck'
    $exp = 'VDS health check disabled'
    if ($r.state -eq 'missing-key') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed 'No health check configuration reported' -Expected $exp -Facts @('policy') -Confidence inferred) }
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'policy') -Expected $exp -Facts @('policy')) }
    $on = @($r.value | Where-Object { $_.enabled } | ForEach-Object { $_.type })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($on.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($on.Count) { "Enabled: $($on -join ', ')" } else { 'Disabled' }) -Expected $exp -Facts @('policy'))
}

function Invoke-VsatCheckPortOverrides {
    param($Rule, $Asset, $Check, $Context)
    $exp = 'No individual ports override the portgroup security policy to accept'
    if (-not $Asset.facts.Contains('portOverrides')) {
        $allowed = Get-VsatProp $Asset.facts 'policy.value.overrides.security'
        if ($allowed -eq $false) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed 'Security policy override not allowed' -Expected $exp -Facts @('policy')) }
        return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed 'Per-port settings not collected' -Expected $exp -Facts @('policy'))
    }
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'portOverrides'
    if ($r.state -eq 'absent') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed 'No permissive port overrides' -Expected $exp -Facts @('portOverrides')) }
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'portOverrides') -Expected $exp -Facts @('portOverrides')) }
    $bad = @($r.value)
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($bad.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($bad.Count) { ($bad | ForEach-Object { "port $($_.port): $(Format-VsatValue $_.security)" }) -join '; ' } else { 'No permissive port overrides' }) -Expected $exp -Facts @('portOverrides'))
}

function Invoke-VsatCheckUplinkRedundancy {
    param($Rule, $Asset, $Check, $Context)
    $up = @($Asset.props.uplinks | Where-Object { $_ })
    $exp = 'At least two physical uplinks'
    if ($Asset.type -eq 'vds') { $up = @(Get-VsatProp $Asset.facts 'policy.value.uplinks' @()) }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($up.Count -ge 2) { 'PASS' } else { 'FAIL' }) -Observed "$($up.Count) uplink(s)" -Expected $exp -Facts @('props'))
}

function Invoke-VsatCheckVcAdminUsers {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'permissions'
    $exp = 'Administrator role granted to groups, not individual users (break-glass account excepted)'
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'permissions') -Expected $exp -Facts @('permissions')) }
    $users = @($r.value | Where-Object { $_.role -eq 'Admin' -and -not $_.isGroup -and $_.principal -notmatch '^(VSPHERE\.LOCAL\\Administrator|administrator@vsphere\.local)$' -and $_.principal -notmatch '(?i)vpxd-extension|vsphere-webclient|vpxd-|machine-' } | ForEach-Object { "$($_.principal) on $($_.entity)" })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($users.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($users.Count) { $users -join '; ' } else { 'Only groups or the SSO administrator hold Admin' }) -Expected $exp -Facts @('permissions'))
}

# ---- NSX evaluators --------------------------------------------------------

function Get-VsatNsxRules {
    param($Context, [string]$Endpoint, [string]$Firewall = 'dfw')
    return @($Context.evidence.assets | Where-Object { $_.type -eq 'nsx-rule' -and $_.endpoint -eq $Endpoint -and $_.props.firewall -eq $Firewall } |
            Sort-Object { Get-VsatCategoryOrder $_.props.category }, { [long]$_.props.policySequence }, { [long]$_.props.sequence })
}

function Get-VsatCategoryOrder {
    param([string]$Category)
    $order = @('Ethernet', 'Emergency', 'Infrastructure', 'Environment', 'Application', 'SystemRules', 'SharedPreRules', 'LocalGatewayRules', 'AutoServiceRules', 'Default')
    $i = [array]::IndexOf($order, $Category)
    if ($i -lt 0) { return 50 }
    return $i
}

function Invoke-VsatCheckNsxDefaultRule {
    param($Rule, $Asset, $Check, $Context)
    $rules = @(Get-VsatNsxRules $Context $Asset.endpoint 'dfw')
    $def = @($rules | Where-Object { $_.props.isDefault -and $_.props.category -eq 'Application' -and $_.props.path -match 'layer3' }) | Select-Object -Last 1
    if (-not $def) { $def = @($rules | Where-Object { $_.props.isDefault }) | Select-Object -Last 1 }
    $mode = [string](Get-VsatProp $Check 'mode' 'action')
    $exp = if ($mode -eq 'log') { 'Default layer-3 rule logs matched traffic' } else { 'Default layer-3 DFW rule action is DROP or REJECT' }
    if (-not $def) {
        $coll = @($Context.evidence.collection.collectors | Where-Object { $_.name -eq 'nsx.dfw' -and $_.endpoint -eq $Asset.endpoint }) | Select-Object -First 1
        return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($coll -and $coll.status -eq 'ok') { 'UNKNOWN' } else { 'UNKNOWN' }) -Observed "Default layer-3 rule not found in collected policy (collector: $(if ($coll) { $coll.status } else { 'not run' }))" -Expected $exp)
    }
    if ($mode -eq 'log') {
        return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($def.props.logged) { 'PASS' } else { 'FAIL' }) -Observed "$($def.name): logged=$($def.props.logged)" -Expected $exp)
    }
    $ok = @('DROP', 'REJECT') -contains ([string]$def.props.action).ToUpperInvariant()
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($ok) { 'PASS' } else { 'FAIL' }) -Observed "$($def.name): action=$($def.props.action)" -Expected $exp)
}

function Invoke-VsatCheckNsxRuleBroad {
    param($Rule, $Asset, $Check, $Context)
    $p = $Asset.props
    $mode = [string]$Check.mode
    if ($p.isDefault) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'Default rule (evaluated separately)' -Expected '' -Facts @('props')) }
    if ($p.disabled) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'Rule disabled' -Expected '' -Facts @('props')) }
    if (([string]$p.action).ToUpperInvariant() -ne 'ALLOW') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed "action=$($p.action)" -Expected 'Not a broad allow' -Facts @('props')) }
    $anySrc = (@($p.sources) -contains 'ANY') -and -not $p.sourcesExcluded
    $anyDst = (@($p.destinations) -contains 'ANY') -and -not $p.destinationsExcluded
    $anySvc = (@($p.services) -contains 'ANY')
    $anyScope = (@($p.appliedTo) -contains 'ANY') -and (@($p.policyAppliedTo) -contains 'ANY')
    $obs = "sources=$(Format-VsatValue $p.sources); destinations=$(Format-VsatValue $p.destinations); services=$(Format-VsatValue $p.services); appliedTo=$(Format-VsatValue $p.appliedTo)"
    switch ($mode) {
        'anyany' { $bad = ($anySrc -and $anyDst -and $anySvc); $exp = 'No enabled ALLOW rule with source, destination and service all ANY' }
        'anyservice' { $bad = (-not ($anySrc -and $anyDst)) -and $anySvc -and ($anySrc -or $anyDst); $exp = 'ALLOW rules with ANY source or destination restrict services' }
        'appliedto' { $bad = $anyScope; $exp = 'ALLOW rules scope Applied-To to relevant groups instead of DFW-wide' }
        default { throw "Unknown mode $mode" }
    }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($bad) { 'FAIL' } else { 'PASS' }) -Observed $obs -Expected $exp -Facts @('props'))
}

function Invoke-VsatCheckNsxRuleHygiene {
    param($Rule, $Asset, $Check, $Context)
    $p = $Asset.props
    switch ([string]$Check.mode) {
        'disabled' { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($p.disabled) { 'FAIL' } else { 'PASS' }) -Observed "disabled=$($p.disabled)" -Expected 'No stale disabled rules' -Facts @('props')) }
        'logging' {
            if ($p.disabled -or $p.isDefault) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'Disabled or default rule' -Expected '' -Facts @('props')) }
            $deny = @('DROP', 'REJECT') -contains ([string]$p.action).ToUpperInvariant()
            if (-not $deny) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed "action=$($p.action)" -Expected '' -Facts @('props')) }
            return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($p.logged) { 'PASS' } else { 'FAIL' }) -Observed "action=$($p.action) logged=$($p.logged)" -Expected 'Deny rules log matched traffic' -Facts @('props'))
        }
    }
}

function Invoke-VsatCheckNsxEmptyGroups {
    param($Rule, $Asset, $Check, $Context)
    $p = $Asset.props
    $exp = 'Every group referenced by the rule has realized effective members'
    if ($p.disabled) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'Rule disabled' -Expected $exp -Facts @('props')) }
    $refs = @(@($p.sources) + @($p.destinations) + @($p.appliedTo) | Where-Object { $_ -ne 'ANY' -and $_ -like '*/groups/*' } | Select-Object -Unique)
    if ($refs.Count -eq 0) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'Rule references no groups' -Expected $exp -Facts @('props')) }
    $empty = @(); $unknown = @()
    foreach ($g in $refs) {
        $ga = $Context.assets["$($Asset.endpoint):$g"]
        if (-not $ga -or -not $ga.facts.Contains('members') -or $ga.facts.members.status -ne 'ok') { $unknown += $g; continue }
        $m = $ga.facts.members.value
        if (@($m.vms).Count -eq 0 -and @($m.ips).Count -eq 0) { $empty += $ga.name }
    }
    if ($empty.Count) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result FAIL -Observed "Groups with no effective members: $($empty -join ', ')" -Expected $exp -Facts @('props') -Note 'Configured policy without effective members may not enforce as intended (Broadcom KB 414765).') }
    if ($unknown.Count) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed "Effective membership unavailable for: $($unknown -join ', ')" -Expected $exp -Facts @('props')) }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed "$($refs.Count) referenced group(s) have effective members" -Expected $exp -Facts @('props'))
}

function Test-VsatNsxSetCovers {
    # $true when set A (earlier rule) covers set B (later rule) for the same dimension.
    param($A, $B)
    if (@($A) -contains 'ANY') { return $true }
    if (@($B) -contains 'ANY') { return $false }
    foreach ($x in @($B)) { if (@($A) -notcontains $x) { return $false } }
    return $true
}

function Invoke-VsatCheckNsxShadow {
    param($Rule, $Asset, $Check, $Context)
    $p = $Asset.props
    $exp = 'Rule is reachable (not fully covered by an earlier enabled rule)'
    if ($p.disabled -or $p.isDefault) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'Disabled or default rule' -Expected $exp -Facts @('props')) }
    if ($p.sourcesExcluded -or $p.destinationsExcluded -or (@($p.profiles) -notcontains 'ANY')) {
        return (New-VsatFinding -Rule $Rule -Asset $Asset -Result MANUAL -Observed 'Rule uses negation or context profiles; shadowing requires manual review' -Expected $exp -Facts @('props'))
    }
    $key = "shadow:$($Asset.endpoint):$($p.firewall)"
    if (-not $Context.Contains($key)) { $Context[$key] = @(Get-VsatNsxRules $Context $Asset.endpoint $p.firewall) }
    $ordered = $Context[$key]
    foreach ($e in $ordered) {
        if ($e.id -eq $Asset.id) { break }
        $q = $e.props
        if ($q.disabled -or $q.sourcesExcluded -or $q.destinationsExcluded -or (@($q.profiles) -notcontains 'ANY')) { continue }
        if (([string]$q.action).ToUpperInvariant() -eq 'JUMP_TO_APPLICATION') { continue }
        $dirOk = ($q.direction -eq 'IN_OUT' -or $q.direction -eq $p.direction)
        $protoOk = ($q.ipProtocol -eq 'IPV4_IPV6' -or $q.ipProtocol -eq $p.ipProtocol)
        $scopeA = if (@($q.appliedTo) -contains 'ANY') { $q.policyAppliedTo } else { $q.appliedTo }
        $scopeB = if (@($p.appliedTo) -contains 'ANY') { $p.policyAppliedTo } else { $p.appliedTo }
        if ($dirOk -and $protoOk -and (Test-VsatNsxSetCovers $q.sources $p.sources) -and (Test-VsatNsxSetCovers $q.destinations $p.destinations) -and (Test-VsatNsxSetCovers $q.services $p.services) -and (Test-VsatNsxSetCovers $scopeA $scopeB)) {
            $same = ([string]$q.action -eq [string]$p.action)
            return (New-VsatFinding -Rule $Rule -Asset $Asset -Result FAIL -Observed "Fully covered by earlier rule '$($e.name)' ($($q.category) / $($q.policyName)); earlier action $($q.action)$(if ($same) { ' (redundant)' } else { ' (conflicting - this rule never matches)' })" -Expected $exp -Facts @('props') -Confidence inferred -Severity $(if ($same) { 'low' } else { 'medium' }))
        }
    }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed 'No earlier rule fully covers this rule' -Expected $exp -Facts @('props') -Confidence inferred)
}

function Invoke-VsatCheckNsxExcludeList {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'excludeList'
    $exp = 'DFW exclusion list contains only system-required members'
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'excludeList') -Expected $exp -Facts @('excludeList')) }
    $members = @(Get-VsatProp $r.value 'members' @()) + @(Get-VsatProp $r.value 'member.members' @())
    $members = @($members | Where-Object { $_ -and [string]$_ -notmatch '(?i)system|nsx-manager|edge|service-vm|SVM' })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($members.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($members.Count) { "Excluded: $(Format-VsatValue $members)" } else { 'No user-defined exclusions' }) -Expected $exp -Facts @('excludeList') -Note 'Excluded workloads receive no distributed firewall enforcement.')
}

function Invoke-VsatCheckNsxGatewayDefault {
    param($Rule, $Asset, $Check, $Context)
    $rules = @(Get-VsatNsxRules $Context $Asset.endpoint 'gfw' | Where-Object { $_.props.isDefault -or $_.props.category -eq 'Default' })
    $exp = 'Gateway firewall default rules drop unmatched traffic on Tier-0/Tier-1 gateways'
    $coll = @($Context.evidence.collection.collectors | Where-Object { $_.name -eq 'nsx.gfw' -and $_.endpoint -eq $Asset.endpoint }) | Select-Object -First 1
    if (-not $coll -or $coll.status -notin @('ok', 'partial')) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed "Gateway policy not collected ($(if ($coll) { $coll.status } else { 'not run' }))" -Expected $exp) }
    if ($rules.Count -eq 0) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result MANUAL -Observed 'No default gateway rules returned; confirm per-gateway default action in the UI' -Expected $exp) }
    $allow = @($rules | Where-Object { ([string]$_.props.action).ToUpperInvariant() -eq 'ALLOW' -and -not $_.props.disabled } | ForEach-Object { "$($_.name) [$(Format-VsatValue $_.props.appliedTo)]" })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($allow.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($allow.Count) { "Default ALLOW: $($allow -join '; ')" } else { "$($rules.Count) default gateway rule(s) deny" }) -Expected $exp)
}

function Invoke-VsatCheckNsxIds {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'idsClusters'
    $exp = 'Distributed IDS/IPS enabled where licensed and required'
    if ($r.state -eq 'unsupported' -or $r.state -eq 'denied') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed "IDS/IPS API $($r.state) (feature may be unlicensed or unavailable in this release)" -Expected $exp -Facts @('idsClusters') -Note 'A missing license is a capability gap, not a benchmark violation.') }
    if ($r.state -ne 'ok' -and $r.state -ne 'absent') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'idsClusters') -Expected $exp -Facts @('idsClusters')) }
    $on = @(@($r.value) | Where-Object { Get-VsatProp $_ 'ids_enabled' $false })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($on.Count) { 'PASS' } else { 'FAIL' }) -Observed "IDS enabled on $($on.Count) of $(@($r.value).Count) cluster(s)" -Expected $exp -Facts @('idsClusters') -Note 'Detection capability gap; confirm licensing before treating as a violation.')
}

function Invoke-VsatCheckNsxTransportNodes {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'transportNodeStates'
    $exp = 'All transport nodes realized successfully'
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'transportNodeStates') -Expected $exp -Facts @('transportNodeStates')) }
    $bad = @(@($r.value) | Where-Object { [string](Get-VsatProp $_ 'state') -ne 'success' } | ForEach-Object { "$(Get-VsatProp $_ 'transport_node_id'): $(Get-VsatProp $_ 'state')" })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($bad.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($bad.Count) { $bad -join '; ' } else { "$(@($r.value).Count) node(s) in state success" }) -Expected $exp -Facts @('transportNodeStates') -Note 'Realization failures can leave configured policy unenforced.')
}

function Invoke-VsatCheckNsxBackup {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'backupConfig'
    $exp = 'Scheduled NSX backups enabled to a remote file server'
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'backupConfig') -Expected $exp -Facts @('backupConfig')) }
    $en = [bool](Get-VsatProp $r.value 'backup_enabled' $false)
    $sched = Get-VsatProp $r.value 'backup_schedule'
    $srv = Get-VsatProp $r.value 'remote_file_server.server'
    $ok = $en -and $sched -and $srv
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($ok) { 'PASS' } else { 'FAIL' }) -Observed "enabled=$en; schedule=$(if ($sched) { Get-VsatProp $sched 'resource_type' 'set' } else { 'none' }); server=$(Format-VsatValue $srv)" -Expected $exp -Facts @('backupConfig') -Note 'Successful backup jobs are not proof of a successful restore.')
}

function Invoke-VsatCheckNsxNatBypass {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'natRules'
    $exp = 'NAT rules do not bypass the gateway firewall'
    if ($r.state -eq 'absent') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'No NAT rules' -Expected $exp -Facts @('natRules')) }
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'natRules') -Expected $exp -Facts @('natRules')) }
    if (@($r.value).Count -eq 0) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'No NAT rules' -Expected $exp -Facts @('natRules')) }
    $bad = @(@($r.value) | Where-Object { $_.enabled -and [string]$_.firewallMatch -eq 'BYPASS' } | ForEach-Object { "$($_.id) ($($_.action))" })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($bad.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($bad.Count) { "Firewall bypass: $($bad -join ', ')" } else { "$(@($r.value).Count) NAT rule(s) use firewall matching" }) -Expected $exp -Facts @('natRules'))
}

function Invoke-VsatCheckNsxUnprotectedVm {
    param($Rule, $Asset, $Check, $Context)
    $exp = 'VM is a member of at least one group used by an enabled, non-default DFW rule'
    $st = $Context.nsxState
    if ($st -eq 'NOT_APPLICABLE') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'NSX not deployed in scope (evidence recorded in coverage)' -Expected $exp) }
    if ($Asset.props.template) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'Template' -Expected $exp) }
    if (-not $Context.Contains('nsxMembership')) { $Context.nsxMembership = Get-VsatNsxMembershipIndex $Context }
    $idx = $Context.nsxMembership
    if ($idx.managers -eq 0) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed "NSX policy not assessed (NSX coverage: $st)" -Expected $exp) }
    $uuid = [string]$Asset.props.instanceUuid
    if (-not $uuid) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed 'VM instance UUID not collected; cannot correlate with NSX' -Expected $exp) }
    if (-not $idx.fabric.ContainsKey($uuid)) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'VM not present in NSX inventory (not on an NSX-prepared host or different NSX domain)' -Expected $exp -Confidence inferred) }
    if ($idx.incomplete) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed 'Effective group membership incomplete; protection cannot be determined' -Expected $exp) }
    $groups = @($idx.vmGroups[$uuid])
    if ($groups.Count -gt 0) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed "Protected by groups: $((@($groups | Select-Object -First 5)) -join ', ')" -Expected $exp -Confidence inferred) }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result FAIL -Observed "Not in any group referenced by an enabled rule; default rule action: $($idx.defaultAction)" -Expected $exp -Confidence inferred -Severity $(if ($idx.defaultAction -eq 'ALLOW') { 'high' } else { 'low' }))
}

function Get-VsatNsxMembershipIndex {
    param($Context)
    $idx = @{ managers = 0; fabric = @{}; vmGroups = @{}; incomplete = $false; defaultAction = 'unknown' }
    $mgrs = @($Context.evidence.assets | Where-Object { $_.type -eq 'nsx-manager' })
    $idx.managers = $mgrs.Count
    foreach ($m in $mgrs) {
        if ($m.facts.Contains('fabricVms') -and $m.facts.fabricVms.status -eq 'ok') { foreach ($v in @($m.facts.fabricVms.value)) { $idx.fabric[[string]$v.externalId] = $true } }
        else { $idx.incomplete = $true }
    }
    $used = @{}
    foreach ($r in @($Context.evidence.assets | Where-Object { $_.type -eq 'nsx-rule' -and -not $_.props.disabled -and -not $_.props.isDefault -and $_.props.firewall -eq 'dfw' })) {
        foreach ($g in @(@($r.props.sources) + @($r.props.destinations) + @($r.props.appliedTo) + @($r.props.policyAppliedTo))) { if ($g -ne 'ANY') { $used["$($r.endpoint):$g"] = $true } }
        if ((@($r.props.appliedTo) -contains 'ANY') -and (@($r.props.policyAppliedTo) -contains 'ANY') -and ((@($r.props.sources) -contains 'ANY') -or (@($r.props.destinations) -contains 'ANY'))) { $used['*'] = $true }
    }
    foreach ($gid in $used.Keys) {
        if ($gid -eq '*') { continue }
        $ga = $Context.assets[$gid]
        if (-not $ga) { continue }
        if (-not $ga.facts.Contains('members') -or $ga.facts.members.status -ne 'ok') { $idx.incomplete = $true; continue }
        foreach ($v in @($ga.facts.members.value.vms)) {
            $u = [string]$v.externalId
            if (-not $idx.vmGroups.ContainsKey($u)) { $idx.vmGroups[$u] = [System.Collections.Generic.List[string]]::new() }
            $idx.vmGroups[$u].Add($ga.name)
        }
    }
    if ($used.ContainsKey('*')) { foreach ($u in @($idx.fabric.Keys)) { if (-not $idx.vmGroups.ContainsKey($u)) { $idx.vmGroups[$u] = [System.Collections.Generic.List[string]]::new() }; $idx.vmGroups[$u].Add('(DFW-wide rule with ANY)') } }
    $def = @($Context.evidence.assets | Where-Object { $_.type -eq 'nsx-rule' -and $_.props.isDefault -and $_.props.firewall -eq 'dfw' }) | Select-Object -Last 1
    if ($def) { $idx.defaultAction = ([string]$def.props.action).ToUpperInvariant() }
    return $idx
}

#endregion Script evaluators

# ---- src/67-EvaluatorsPlatform.ps1 ----
#region Platform evaluators (Hyper-V, KVM, shared host checks)

function Get-VsatOsLifecycleData {
    if ($script:VsatOsLifecycle) { return $script:VsatOsLifecycle }
    if ((Get-VsatEmbeddedNames 'data/') -contains 'data/os-lifecycle.json') { $script:VsatOsLifecycle = ConvertFrom-VsatJson (Get-VsatEmbeddedText 'data/os-lifecycle.json') }
    else { $script:VsatOsLifecycle = [ordered]@{ lifecycle = @() } }
    return $script:VsatOsLifecycle
}

function Invoke-VsatCheckPatchAge {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact $Check.fact
    $max = [int]$Check.maxDays
    $exp = "Updates installed within the last $max days"
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r $Check.fact) -Expected $exp -Facts @($Check.fact)) }
    $age = Get-VsatProp $r.value 'ageDays'
    if ($null -eq $age) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed 'Update age not available' -Expected $exp -Facts @($Check.fact)) }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ([int]$age -le $max) { 'PASS' } else { 'FAIL' }) -Observed "Last update $age day(s) ago$(if ($r.value.lastId) { " ($($r.value.lastId))" })" -Expected $exp -Facts @($Check.fact) -Confidence inferred)
}

function Invoke-VsatCheckOsLifecycle {
    param($Rule, $Asset, $Check, $Context)
    $data = Get-VsatOsLifecycleData
    if ($Asset.type -eq 'hyperv-host') { $product = 'windows-server'; $branch = [string]$Asset.build }
    else {
        $product = [string]$Asset.props.osId
        $v = [string]$Asset.version
        $branch = if ($product -in @('ubuntu')) { $v } else { ($v -split '\.')[0] }
    }
    $row = @($data.lifecycle | Where-Object { $_.product -eq $product -and [string]$_.branch -eq $branch }) | Select-Object -First 1
    $exp = 'Operating system release within vendor security support'
    if (-not $row) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result UNKNOWN -Observed "${product} ${branch}: no lifecycle data in snapshot" -Expected $exp -Note 'Absence of lifecycle data is not evidence of support.') }
    $eos = Get-VsatProp $row 'endOfSupport'
    if (-not $eos) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result MANUAL -Observed "$($row.name): end-of-support date not verified in snapshot" -Expected $exp) }
    $d = [DateTime]::Parse($eos, [Globalization.CultureInfo]::InvariantCulture)
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($d -lt $Context.now) { 'FAIL' } else { 'PASS' }) -Observed "$($row.name) security support ends $eos" -Expected $exp)
}

function Invoke-VsatCheckHvDeviceGuard {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'deviceGuard'
    $svc = [int]$Check.service
    $label = if ($svc -eq 1) { 'Credential Guard' } else { 'HVCI' }
    $exp = "$label running"
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'deviceGuard') -Expected $exp -Facts @('deviceGuard')) }
    $running = @($r.value.servicesRunning) -contains $svc
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($running) { 'PASS' } else { 'FAIL' }) -Observed "VBS status $($r.value.vbsStatus); services running: $(Format-VsatValue $r.value.servicesRunning)" -Expected $exp -Facts @('deviceGuard'))
}

function Invoke-VsatCheckHvFirewall {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'firewall'
    $exp = 'Domain, Private and Public profiles enabled with inbound Block'
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'firewall') -Expected $exp -Facts @('firewall')) }
    $bad = @(@($r.value) | Where-Object { [string]$_.enabled -ne 'True' -or [string]$_.defaultInbound -eq 'Allow' } | ForEach-Object { "$($_.name): enabled=$($_.enabled) inbound=$($_.defaultInbound)" })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($bad.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($bad.Count) { $bad -join '; ' } else { 'All profiles enabled; inbound not Allow' }) -Expected $exp -Facts @('firewall'))
}

function Invoke-VsatCheckHvMigration {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'vmhost'
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'vmhost') -Expected 'Live migration secured' -Facts @('vmhost')) }
    if (-not $r.value.migrationEnabled) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'Live migration disabled' -Expected '' -Facts @('vmhost')) }
    if ($Check.mode -eq 'auth') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($r.value.migrationAuth -eq 'Kerberos') { 'PASS' } else { 'FAIL' }) -Observed "Authentication: $($r.value.migrationAuth)" -Expected 'Kerberos' -Facts @('vmhost')) }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($r.value.anyNetworkForMigration) { 'FAIL' } else { 'PASS' }) -Observed "UseAnyNetworkForMigration = $($r.value.anyNetworkForMigration)" -Expected 'Dedicated migration networks only' -Facts @('vmhost'))
}

function Invoke-VsatCheckHvReplica {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'replica'
    $exp = 'Replica disabled, or certificate-based (HTTPS) authentication only'
    if ($r.state -eq 'unsupported') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'Hyper-V Replica not available' -Expected $exp -Facts @('replica')) }
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'replica') -Expected $exp -Facts @('replica')) }
    if (-not $r.value.enabled) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'Replication server disabled' -Expected $exp -Facts @('replica')) }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($r.value.auth -eq 'Certificate') { 'PASS' } else { 'FAIL' }) -Observed "Allowed authentication: $($r.value.auth)" -Expected $exp -Facts @('replica'))
}

function Invoke-VsatCheckHvAdapters {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'adapters'
    $field = [string]$Check.field; $badVals = @($Check.bad)
    $exp = "No adapter with $field in $($badVals -join '/')"
    if ($r.state -eq 'absent') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'No network adapters' -Expected $exp -Facts @('adapters')) }
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'adapters') -Expected $exp -Facts @('adapters')) }
    $ads = @($r.value)
    if ($ads.Count -eq 0) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed 'No network adapters' -Expected $exp -Facts @('adapters')) }
    $bad = @($ads | Where-Object { $badVals -contains [string]$_[$field] } | ForEach-Object { "$($_.name) ($($_.switch)): $field=$($_[$field])" })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($bad.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($bad.Count) { $bad -join '; ' } else { "$($ads.Count) adapter(s) compliant" }) -Expected $exp -Facts @('adapters'))
}

function Invoke-VsatCheckHvIntegration {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'integration'
    $exp = "$($Check.service) disabled"
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'integration') -Expected $exp -Facts @('integration')) }
    $svc = @(@($r.value) | Where-Object { $_.name -eq $Check.service })[0]
    if (-not $svc) { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result NOT_APPLICABLE -Observed "$($Check.service) not present" -Expected $exp -Facts @('integration')) }
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($svc.enabled) { 'FAIL' } else { 'PASS' }) -Observed "enabled=$($svc.enabled)" -Expected $exp -Facts @('integration'))
}

function Invoke-VsatCheckHvCheckpointAge {
    param($Rule, $Asset, $Check, $Context)
    $fact = if ($Check.Contains('fact')) { $Check.fact } else { 'checkpoints' }
    $r = Resolve-VsatFactValue -Asset $Asset -Fact $fact
    $max = [int]$Check.maxDays
    $exp = "No checkpoints/snapshots older than $max days"
    if ($r.state -eq 'absent') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed 'None' -Expected $exp -Facts @($fact)) }
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r $fact) -Expected $exp -Facts @($fact)) }
    $old = @(@($r.value) | Where-Object { $null -ne $_.ageDays -and [int]$_.ageDays -gt $max })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($old.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($old.Count) { ($old | ForEach-Object { "'$($_.name)' $($_.ageDays)d" }) -join '; ' } else { "$(@($r.value).Count) item(s), none older than $max days" }) -Expected $exp -Facts @($fact) -Note 'A checkpoint or snapshot is not a backup.')
}

function Invoke-VsatCheckHvDevices {
    param($Rule, $Asset, $Check, $Context)
    $r = Resolve-VsatFactValue -Asset $Asset -Fact 'devices'
    $types = @($Check.types)
    $exp = "No attached $($types -join '/') devices"
    if ($r.state -eq 'absent') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result PASS -Observed 'None' -Expected $exp -Facts @('devices')) }
    if ($r.state -ne 'ok') { return (New-VsatFinding -Rule $Rule -Asset $Asset -Result (Get-VsatEvidenceGapResult $r.state) -Observed (Get-VsatGapText $r 'devices') -Expected $exp -Facts @('devices')) }
    $hits = @(@($r.value) | Where-Object { $types -contains $_.type -and $_.path })
    return (New-VsatFinding -Rule $Rule -Asset $Asset -Result $(if ($hits.Count) { 'FAIL' } else { 'PASS' }) -Observed $(if ($hits.Count) { ($hits | ForEach-Object { "$($_.type): $($_.path)" }) -join '; ' } else { 'None' }) -Expected $exp -Facts @('devices'))
}

#endregion Platform evaluators

# ---- src/70-Coverage.ps1 ----
#region Coverage and status
# Coverage is computed per domain from collector outcomes and check results. UNKNOWN
# and ERROR results never improve coverage, and NSX is a mandatory domain whenever
# VMware infrastructure is in scope.

$script:VsatDomains = @(
    [ordered]@{ id = 'vcenter'; name = 'vCenter'; mandatory = $true; platform = 'vmware'; collectors = @('vsphere.vcenter'); assetTypes = @('vcenter') }
    [ordered]@{ id = 'esxi'; name = 'ESX/ESXi hosts'; mandatory = $true; platform = 'vmware'; collectors = @('vsphere.hosts'); assetTypes = @('host') }
    [ordered]@{ id = 'cluster'; name = 'Clusters'; mandatory = $true; platform = 'vmware'; collectors = @('vsphere.inventory'); assetTypes = @('cluster') }
    [ordered]@{ id = 'vm'; name = 'Virtual machines'; mandatory = $true; platform = 'vmware'; collectors = @('vsphere.vms'); assetTypes = @('vm') }
    [ordered]@{ id = 'network'; name = 'Virtual networking'; mandatory = $true; platform = 'vmware'; collectors = @('vsphere.hosts', 'vsphere.vds'); assetTypes = @('vss', 'vds', 'portgroup', 'dvportgroup') }
    [ordered]@{ id = 'nsx'; name = 'NSX'; mandatory = $true; platform = 'vmware'; collectors = @('nsx.manager', 'nsx.fabric', 'nsx.networking', 'nsx.groups', 'nsx.dfw', 'nsx.gfw', 'nsx.inventory'); assetTypes = @('nsx-manager') }
    [ordered]@{ id = 'storage'; name = 'Storage and recovery'; mandatory = $true; platform = 'vmware'; collectors = @('vsphere.datastores'); assetTypes = @('datastore') }
    [ordered]@{ id = 'hyperv-host'; name = 'Hyper-V hosts'; mandatory = $true; platform = 'hyperv'; collectors = @('hyperv.host'); assetTypes = @('hyperv-host') }
    [ordered]@{ id = 'hyperv-vm'; name = 'Hyper-V virtual machines'; mandatory = $true; platform = 'hyperv'; collectors = @('hyperv.vms'); assetTypes = @('hyperv-vm') }
    [ordered]@{ id = 'hyperv-network'; name = 'Hyper-V virtual switches'; mandatory = $true; platform = 'hyperv'; collectors = @('hyperv.network'); assetTypes = @('hyperv-vswitch') }
    [ordered]@{ id = 'kvm-host'; name = 'KVM/libvirt hosts'; mandatory = $true; platform = 'kvm'; collectors = @('kvm.host'); assetTypes = @('kvm-host') }
    [ordered]@{ id = 'kvm-vm'; name = 'KVM virtual machines'; mandatory = $true; platform = 'kvm'; collectors = @('kvm.vms'); assetTypes = @('kvm-vm') }
    [ordered]@{ id = 'kvm-network'; name = 'KVM virtual networks'; mandatory = $true; platform = 'kvm'; collectors = @('kvm.network'); assetTypes = @('kvm-network') }
)

function Update-VsatNsxDiscovery {
    # Determines whether NSX exists in the vSphere scope from vCenter evidence.
    param([Parameter(Mandatory)]$Evidence)
    $ev = [System.Collections.Generic.List[string]]::new()
    $mgrs = [System.Collections.Generic.List[string]]::new()
    $detected = $false; $unknown = $false; $checked = 0; $legacy = $false
    foreach ($vc in @($Evidence.assets | Where-Object { $_.type -eq 'vcenter' })) {
        $f = if ($vc.facts.Contains('extensions')) { $vc.facts.extensions } else { $null }
        if (-not $f -or ($f.status -ne 'ok' -and $f.status -ne 'absent')) {
            $unknown = $true
            $ev.Add("Cannot read extension list on $($vc.name) ($(if ($f) { $f.status } else { 'not collected' }))")
            continue
        }
        $checked++
        foreach ($x in @($f.value)) {
            if ([string]$x.key -match '(?i)^com\.vmware\.nsx') {
                $detected = $true
                $ev.Add("vCenter $($vc.name) has extension $($x.key) $($x.version)")
                foreach ($u in @($x.urls)) { try { $h = ([uri]$u).Host; if ($h -and -not $mgrs.Contains($h)) { $mgrs.Add($h) } } catch { } }
            }
            elseif ([string]$x.key -match '(?i)vShieldManager') {
                $detected = $true; $legacy = $true
                $ev.Add("vCenter $($vc.name) has NSX-V/vShield extension $($x.key) (legacy; modern adapters cannot assess it)")
            }
        }
        if (-not $detected) { $ev.Add("vCenter $($vc.name): extension list readable, no NSX extension registered") }
    }
    $nsxNets = @($Evidence.assets | Where-Object { $_.type -eq 'dvportgroup' -and ($_.props.backingType -eq 'nsx' -or $_.props.segmentId -or $_.props.logicalSwitchUuid) })
    if ($nsxNets.Count) { $detected = $true; $ev.Add("$($nsxNets.Count) NSX-backed distributed port group(s) found (e.g. $($nsxNets[0].name))") }
    $opaque = @($Evidence.relationships | Where-Object { $_.target -like 'opaque:*' })
    if ($opaque.Count) { $detected = $true; $ev.Add("$($opaque.Count) VM adapter(s) attached to NSX opaque networks") }
    $vsphereEps = @($Evidence.scope.endpoints | Where-Object { $_.type -in @('vcenter', 'esxi') })
    if (-not $detected -and $checked -eq 0) {
        $unknown = $true
        if ($vsphereEps.Count -and -not @($vsphereEps | Where-Object { $_.type -eq 'vcenter' }).Count) { $ev.Add('Only direct ESXi endpoints in scope; NSX registration cannot be determined without vCenter') }
    }
    $status = if ($detected) { 'detected' } elseif ($unknown) { 'unknown' } else { 'not-detected' }
    $Evidence.nsx.discovery = [ordered]@{ status = $status; evidence = @($ev); managersDiscovered = @($mgrs); legacyNsxV = $legacy }
    return $Evidence.nsx.discovery
}

function Get-VsatNsxCoverage {
    param([Parameter(Mandatory)]$Evidence)
    $d = $Evidence.nsx.discovery
    $nsxEps = @($Evidence.scope.endpoints | Where-Object { $_.type -eq 'nsx' })
    $vsEps = @($Evidence.scope.endpoints | Where-Object { $_.type -in @('vcenter', 'esxi') })
    $declared = [bool]$Evidence.scope.nsxDeclaredAbsent
    $evList = @($d.evidence)
    $missing = [System.Collections.Generic.List[string]]::new()
    if ($vsEps.Count -eq 0 -and $nsxEps.Count -eq 0) {
        return [ordered]@{ state = 'NOT_APPLICABLE'; label = 'NOT APPLICABLE: NO VMWARE ENDPOINTS IN SCOPE'; detail = 'NSX applies to VMware infrastructure; no vCenter, ESXi or NSX endpoints are in scope.'; evidence = @('Scope contains no VMware endpoints'); missing = @() }
    }
    if ($nsxEps.Count -gt 0) {
        $failed = @($nsxEps | Where-Object { $_.status -in @('failed', 'not-attempted') })
        $coll = @($Evidence.collection.collectors | Where-Object { $_.name -like 'nsx.*' })
        $bad = @($coll | Where-Object { $_.status -notin @('ok') })
        foreach ($f in $failed) { $missing.Add("NSX Manager $($f.address): $(if ($f.errors.Count) { $f.errors[0] } else { 'not assessed' })") }
        foreach ($b in $bad) { $missing.Add("$($b.name) on $($b.endpoint): $($b.status)$(if ($b.error) { " - $($b.error)" })") }
        $covered = @($nsxEps | ForEach-Object { $_.address.ToLowerInvariant() })
        $undisclosed = @($d.managersDiscovered | Where-Object { $covered -notcontains $_.ToLowerInvariant() })
        # Managers are often registered by VIP/FQDN while the operator used a node address; flag for review.
        foreach ($u in $undisclosed) { $missing.Add("NSX manager registered in vCenter but not in scope: $u (add it, or confirm it is the same cluster)") }
        if ($d.legacyNsxV) { $missing.Add('NSX-V detected: legacy platform requires manual assessment') }
        foreach ($cm in @(Get-VsatProp $Evidence.nsx 'unmatchedComputeManagers' @())) { $missing.Add("NSX compute manager $cm is not in the vCenter scope; its workloads and correlation are not assessed") }
        if ($failed.Count -eq $nsxEps.Count) {
            return [ordered]@{ state = 'INCOMPLETE'; label = 'INCOMPLETE: NSX NOT ASSESSED'; detail = 'NSX Manager endpoints were supplied but could not be assessed.'; evidence = $evList; missing = @($missing) }
        }
        if ($missing.Count) {
            return [ordered]@{ state = 'PARTIAL'; label = 'PARTIAL: NSX PARTLY ASSESSED'; detail = 'Some NSX evidence is missing or additional NSX domains exist; affected checks are UNKNOWN.'; evidence = $evList; missing = @($missing) }
        }
        return [ordered]@{ state = 'ASSESSED'; label = 'NSX ASSESSED'; detail = "$($nsxEps.Count) NSX Manager endpoint(s) assessed."; evidence = $evList; missing = @() }
    }
    if ($declared) {
        switch ($d.status) {
            'not-detected' { return [ordered]@{ state = 'NOT_APPLICABLE'; label = 'NOT APPLICABLE: NSX NOT DEPLOYED'; detail = 'Operator declared NSX absent and discovery evidence agrees. This is not an NSX security pass.'; evidence = @('Operator declaration recorded') + $evList; missing = @() } }
            'detected' { return [ordered]@{ state = 'INCOMPLETE'; label = 'INCOMPLETE: NSX NOT ASSESSED'; detail = 'Operator declared NSX absent, but discovery found NSX. Supply NSX Manager access.'; evidence = @('Operator declaration recorded (conflicts with discovery)') + $evList; missing = @('NSX Manager endpoint and credentials') } }
            default { return [ordered]@{ state = 'REVIEW'; label = 'REVIEW: NSX DECLARED ABSENT, NOT VERIFIED'; detail = 'Operator declared NSX absent; discovery could not confirm. Applicability requires review.'; evidence = @('Operator declaration recorded') + $evList; missing = @('vCenter extension read access (or NSX evidence) to confirm absence') } }
        }
    }
    switch ($d.status) {
        'detected' { return [ordered]@{ state = 'INCOMPLETE'; label = 'INCOMPLETE: NSX NOT ASSESSED'; detail = 'NSX was detected but no NSX Manager endpoint or credentials were supplied.'; evidence = $evList; missing = @('NSX Manager endpoint and credentials' + $(if ($d.managersDiscovered.Count) { " (discovered: $($d.managersDiscovered -join ', '))" } else { '' })) } }
        'not-detected' { return [ordered]@{ state = 'NOT_APPLICABLE'; label = 'NOT APPLICABLE: NSX NOT DEPLOYED'; detail = 'No NSX registration or NSX-backed networks found in the assessed vCenter scope. This is not an NSX security pass.'; evidence = $evList; missing = @() } }
        default { return [ordered]@{ state = 'UNKNOWN'; label = 'UNKNOWN: NSX COVERAGE NOT DETERMINED'; detail = 'NSX presence could not be determined. Supply an NSX Manager endpoint or declare absence with -NsxDeclaredAbsent.'; evidence = $evList; missing = @('NSX Manager endpoint, or vCenter extension read access') } }
    }
}

function Get-VsatCoverage {
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Findings)
    $domains = [System.Collections.Generic.List[object]]::new()
    $vsEps = @($Evidence.scope.endpoints | Where-Object { $_.type -in @('vcenter', 'esxi') })
    $hasVc = @($vsEps | Where-Object { $_.type -eq 'vcenter' }).Count -gt 0
    foreach ($def in (Get-VsatDomainDefinitions)) {
        $df = @($Findings | Where-Object { $_.domain -eq $def.id })
        $checks = [ordered]@{ total = $df.Count; PASS = 0; FAIL = 0; MANUAL = 0; UNKNOWN = 0; ERROR = 0; NOT_APPLICABLE = 0 }
        foreach ($f in $df) { $checks[$f.result] = [int]$checks[$f.result] + 1 }
        $d = [ordered]@{ id = $def.id; name = $def.name; mandatory = $def.mandatory; platform = $def.platform; state = 'ASSESSED'; label = ''; detail = ''; evidence = @(); missing = @(); checks = $checks }
        if ($def.id -eq 'nsx') {
            $c = Get-VsatNsxCoverage -Evidence $Evidence
            foreach ($k in 'state', 'label', 'detail', 'evidence', 'missing') { $d[$k] = $c[$k] }
            if ($d.state -eq 'ASSESSED' -and ($checks.UNKNOWN + $checks.ERROR) -gt 0) {
                $d.state = 'PARTIAL'; $d.label = 'PARTIAL: NSX PARTLY ASSESSED'
                $d.missing = @($d.missing) + "$($checks.UNKNOWN + $checks.ERROR) NSX check(s) lack evidence"
            }
            $domains.Add($d); continue
        }
        $platformEps = @(Get-VsatPlatformEndpoints -Evidence $Evidence -Platform $def.platform)
        if ($platformEps.Count -eq 0) {
            $d.state = 'NOT_APPLICABLE'; $d.label = "NOT APPLICABLE: NO $($def.platform.ToUpperInvariant()) ENDPOINTS"; $d.detail = "No $($def.platform) endpoints in scope."
            $d.mandatory = $false
            $domains.Add($d); continue
        }
        if ($def.id -eq 'vcenter' -and $def.platform -eq 'vmware' -and -not $hasVc) {
            $d.state = 'PARTIAL'; $d.label = 'PARTIAL: DIRECT ESXI ONLY'; $d.detail = 'Direct ESXi connections expose no vCenter-level configuration.'; $d.missing = @('vCenter endpoint for centralized configuration')
            $domains.Add($d); continue
        }
        $colls = @($Evidence.collection.collectors | Where-Object { $def.collectors -contains $_.name })
        $failed = @($colls | Where-Object { $_.status -in @('denied', 'error', 'unsupported') })
        $partial = @($colls | Where-Object { $_.status -eq 'partial' })
        $skipped = @($colls | Where-Object { $_.status -eq 'skipped' })
        $missing = [System.Collections.Generic.List[string]]::new()
        foreach ($c in $failed + $partial) { $missing.Add("$($c.name) on $($c.endpoint): $($c.status)$(if ($c.error) { " - $($c.error)" })") }
        foreach ($c in $skipped) { if ($c.error -ne 'Direct ESXi connection' -and $c.error -ne 'Distributed switches require vCenter') { $missing.Add("$($c.name) skipped: $($c.error)") } }
        if ($colls.Count -eq 0) { $missing.Add('No collector ran for this domain') }
        $gaps = $checks.UNKNOWN + $checks.ERROR
        if ($gaps) { $missing.Add("$gaps check(s) lack evidence (UNKNOWN/ERROR)") }
        $count = @($Evidence.assets | Where-Object { $def.assetTypes -contains $_.type }).Count
        if ($colls.Count -gt 0 -and $failed.Count -eq $colls.Count) { $d.state = 'INCOMPLETE'; $d.label = "INCOMPLETE: $($def.name.ToUpperInvariant()) NOT ASSESSED" }
        elseif ($missing.Count) { $d.state = 'PARTIAL'; $d.label = "PARTIAL: $($def.name.ToUpperInvariant())" }
        else { $d.state = 'ASSESSED'; $d.label = "$($def.name.ToUpperInvariant()) ASSESSED" }
        $d.detail = "$count object(s) in scope; $($checks.total) check result(s)."
        if ($count -eq 0 -and $d.state -eq 'ASSESSED') { $d.detail = 'Collector succeeded; no objects of this type exist in scope (empty scope, not a pass).' }
        $d.missing = @($missing)
        $domains.Add($d)
    }
    $known = @($Findings | Where-Object { $_.result -in @('PASS', 'FAIL', 'NOT_APPLICABLE') }).Count
    return [ordered]@{ domains = $domains.ToArray(); automated = [ordered]@{ known = $known; total = @($Findings | Where-Object { $_.result -ne 'MANUAL' }).Count } }
}

function Get-VsatDomainDefinitions {
    # Platform modules append their domains to $script:VsatDomains at load time.
    return $script:VsatDomains
}

function Get-VsatPlatformEndpoints {
    param($Evidence, [string]$Platform)
    $types = switch ($Platform) { 'vmware' { @('vcenter', 'esxi', 'nsx') } default { @($Platform) } }
    return @($Evidence.scope.endpoints | Where-Object { $types -contains $_.type })
}

function Get-VsatRunStatus {
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)]$Coverage, [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Findings)
    $reasons = [System.Collections.Generic.List[string]]::new()
    if ($Evidence.run.status -eq 'canceled') {
        return [ordered]@{ overall = 'canceled'; label = 'CANCELED: PARTIAL RESULTS PRESERVED'; exitCode = 4; reasons = @('The run was canceled; collected evidence was preserved.') }
    }
    $eps = @($Evidence.scope.endpoints)
    if ($Evidence.run.mode -eq 'live' -and ($eps.Count -eq 0 -or @($eps | Where-Object { $_.status -in @('collected', 'partial') }).Count -eq 0)) {
        foreach ($e in $eps) { $reasons.Add("$($e.type) $($e.address): $($e.status)$(if ($e.errors.Count) { " - $($e.errors[0])" })") }
        if ($eps.Count -eq 0) { $reasons.Add('No endpoints were supplied.') }
        return [ordered]@{ overall = 'failed'; label = 'FAILED: NO ENDPOINT COULD BE ASSESSED'; exitCode = 3; reasons = @($reasons) }
    }
    $incomplete = @($Coverage.domains | Where-Object { $_.mandatory -and $_.state -notin @('ASSESSED', 'NOT_APPLICABLE') })
    foreach ($d in $incomplete) {
        $reasons.Add("$($d.name): $($d.label)$(if (@($d.missing).Count) { ' - ' + (@($d.missing) | Select-Object -First 2) -join '; ' })")
    }
    $fails = @($Findings | Where-Object { $_.result -eq 'FAIL' }).Count
    $manual = @($Findings | Where-Object { $_.result -eq 'MANUAL' }).Count
    if ($incomplete.Count) {
        $nsx = @($incomplete | Where-Object { $_.id -eq 'nsx' -and $_.state -in @('INCOMPLETE', 'UNKNOWN', 'REVIEW') }) | Select-Object -First 1
        $label = if ($nsx) { $nsx.label } else { 'INCOMPLETE: ' + ((@($incomplete | ForEach-Object { $_.name })) -join ', ').ToUpperInvariant() + ' NOT FULLY ASSESSED' }
        if ($fails) { $reasons.Add("$fails failing automated control(s) found in the assessed scope.") }
        return [ordered]@{ overall = 'incomplete'; label = $label; exitCode = 2; reasons = @($reasons) }
    }
    if ($manual) { $reasons.Add("$manual control(s) require manual review; completion is not certification.") }
    if ($fails) { return [ordered]@{ overall = 'complete'; label = 'COMPLETE: FINDINGS PRESENT'; exitCode = 1; reasons = @("$fails failing automated control(s).") + @($reasons) } }
    return [ordered]@{ overall = 'complete'; label = 'COMPLETE: NO FAILING AUTOMATED CONTROLS'; exitCode = 0; reasons = @($reasons) }
}

#endregion Coverage and status

# ---- src/75-Analysis.ps1 ----
#region Correlation
function Invoke-VsatCorrelation {
    # Resolves cross-endpoint references by stable identifiers only (never by display name).
    param([Parameter(Mandatory)]$Evidence)
    $idx = @{}; foreach ($a in $Evidence.assets) { $idx[$a.id] = $a }
    $segByUnique = @{}; $segByPath = @{}
    foreach ($s in @($Evidence.assets | Where-Object { $_.type -eq 'nsx-segment' })) {
        if ($s.props.uniqueId) { $segByUnique[[string]$s.props.uniqueId] = $s.id }
        if (-not $segByPath.ContainsKey([string]$s.props.path)) { $segByPath[[string]$s.props.path] = [System.Collections.Generic.List[string]]::new() }
        $segByPath[[string]$s.props.path].Add($s.id)
    }
    $dvpgByKey = @{}
    foreach ($p in @($Evidence.assets | Where-Object { $_.type -eq 'dvportgroup' })) { $dvpgByKey["$($p.endpoint):dvpg-key:$($p.props.key)"] = $p.id }
    $vcByAddr = @{}
    foreach ($e in @($Evidence.scope.endpoints | Where-Object { $_.type -eq 'vcenter' })) { $vcByAddr[$e.address.ToLowerInvariant()] = "$($e.id):root" }
    $unmatchedCm = [System.Collections.Generic.List[string]]::new()
    $keep = [System.Collections.Generic.List[object]]::new()
    $dropped = 0
    foreach ($r in $Evidence.relationships) {
        $t = [string]$r.target
        if ($t -like 'opaque:*') {
            $id = $t.Substring(7)
            if ($segByUnique.ContainsKey($id)) { $r.target = $segByUnique[$id] } else { $dropped++; continue }
        }
        elseif ($t -like '*:dvpg-key:*') {
            if ($dvpgByKey.ContainsKey($t)) { $r.target = $dvpgByKey[$t]; $r.confidence = 'observed' } else { $dropped++; continue }
        }
        elseif ($t -like 'vcenter:*') {
            $addr = $t.Substring(8).ToLowerInvariant()
            if ($vcByAddr.ContainsKey($addr)) { $r.target = $vcByAddr[$addr] } else { $unmatchedCm.Add($t.Substring(8)); continue }
        }
        if (-not $idx.ContainsKey($r.source) -or -not $idx.ContainsKey($r.target)) { $dropped++; continue }
        $keep.Add($r)
    }
    # VDS-backed NSX segments: dvPortgroup.segmentId carries the NSX policy path.
    foreach ($p in @($Evidence.assets | Where-Object { $_.type -eq 'dvportgroup' -and $_.props.segmentId })) {
        $sid = [string]$p.props.segmentId
        if ($segByPath.ContainsKey($sid)) {
            foreach ($s in $segByPath[$sid]) { $keep.Add([ordered]@{ source = $p.id; target = $s; type = 'connects'; provenance = 'correlation.segmentId'; confidence = 'observed'; props = [ordered]@{} }) }
        }
    }
    $Evidence.relationships = $keep
    $Evidence.nsx.unmatchedComputeManagers = @($unmatchedCm | Select-Object -Unique)
    if ($dropped) { Write-VsatLog -Level debug -Source 'correlation' -Message "$dropped relationship(s) referenced objects outside the collected scope" }
}

function Set-VsatScopeAnnotations {
    # Applies operator-supplied criticality and zones; labels inferred values.
    param([Parameter(Mandatory)]$Evidence)
    foreach ($a in $Evidence.assets) {
        foreach ($c in @($Evidence.scope.criticalAssets)) {
            if (Test-VsatAssetMatch -Asset $a -Match ([string]$c.match)) { $a.criticality = [string]$c.criticality; $a.criticalitySource = 'operator' }
        }
        foreach ($z in @($Evidence.scope.zones)) {
            if (Test-VsatAssetMatch -Asset $a -Match ([string]$z.match)) { $a.zone = [string]$z.name }
        }
        if (-not $a.criticality) {
            if ($a.type -in @('vcenter', 'nsx-manager')) { $a.criticality = 'high'; $a.criticalitySource = 'inferred' }
            elseif ($a.type -eq 'vm' -and $a.name -match '(?i)(vcenter|vcsa|nsx-?(mgr|manager)|psc|kms|backup|veeam|domain.?controller|\bdc\d)') { $a.criticality = 'high'; $a.criticalitySource = 'inferred' }
        }
    }
}

function Test-VsatAssetMatch {
    param($Asset, [string]$Match)
    if (-not $Match) { return $false }
    if ($Match -match '^(name|type|tag|id|zone):(.*)$') {
        $k = $Matches[1]; $v = $Matches[2]
        switch ($k) {
            'name' { return ($Asset.name -like $v) }
            'type' { return ($Asset.type -like $v) }
            'id' { return ($Asset.id -like $v) }
            'zone' { return ([string]$Asset.zone -like $v) }
            'tag' { return [bool](@($Asset.tags) | Where-Object { $_ -like $v }) }
        }
    }
    return ($Asset.name -like $Match)
}
#endregion Correlation

#region Exceptions and priority
function Set-VsatExceptions {
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Findings)
    $now = [DateTime]::UtcNow
    foreach ($ex in @($Evidence.scope.exceptions)) {
        $exp = $null
        if ($ex.expires) { try { $exp = [DateTime]::Parse([string]$ex.expires, [Globalization.CultureInfo]::InvariantCulture) } catch { } }
        $active = ($null -eq $exp -or $exp.Date -ge $now.Date)
        foreach ($f in $Findings) {
            if ($f.ruleId -notlike [string]$ex.ruleId) { continue }
            $pat = if ($ex.asset) { [string]$ex.asset } else { '*' }
            if ($f.assetName -notlike $pat -and $f.assetId -notlike $pat) { continue }
            # Exceptions stay visible and never turn a FAIL into a PASS.
            $f.exception = [ordered]@{ owner = $ex.owner; rationale = $ex.rationale; expires = $ex.expires; active = $active }
        }
    }
}

function Set-VsatPriority {
    param([Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Findings, [Parameter(Mandatory)]$Context, $PathTargets)
    $base = @{ critical = 90; high = 70; medium = 45; low = 20; info = 5 }
    foreach ($f in $Findings) {
        if ($f.result -notin @('FAIL', 'UNKNOWN', 'ERROR')) { continue }
        $reasons = [System.Collections.Generic.List[string]]::new()
        $s = [int]$base[[string]$f.severity]
        $reasons.Add("$($f.severity) severity")
        if ($f.result -ne 'FAIL') { $s = [int]($s * 0.4); $reasons.Add('evidence missing (risk not confirmed)') }
        $a = $Context.assets[$f.assetId]
        if ($a -and $a.criticality -eq 'high') { $s += 15; $reasons.Add("asset criticality high ($($a.criticalitySource))") }
        elseif ($a -and $a.criticality -eq 'medium') { $s += 8; $reasons.Add("asset criticality medium ($($a.criticalitySource))") }
        if ($f.Contains('advisories') -and @($f.advisories | Where-Object { $_.kev }).Count) { $s += 15; $reasons.Add('known exploited vulnerability (CISA KEV)') }
        if ($a -and $a.type -in @('vcenter', 'nsx-manager')) { $s += 10; $reasons.Add('control-plane scope (affects all managed assets)') }
        if ($PathTargets -and $PathTargets.ContainsKey($f.assetId)) { $s += 10; $reasons.Add('reachable in a modeled attack path') }
        if ($f.exception -and $f.exception.active) { $s = [int]($s * 0.5); $reasons.Add('active exception recorded') }
        $f.priority = [ordered]@{ score = [Math]::Min(100, $s); reasons = @($reasons) }
    }
}
#endregion Exceptions and priority

#region Attack paths
function Get-VsatVmSegments {
    param($Context)
    $map = @{}
    foreach ($vm in @($Context.evidence.assets | Where-Object { $_.type -eq 'vm' })) {
        $segs = [System.Collections.Generic.List[string]]::new()
        foreach ($r in @($Context.out[$vm.id])) {
            if ($r.type -ne 'connects') { continue }
            $t = $Context.assets[$r.target]
            if (-not $t) { continue }
            if ($t.type -eq 'nsx-segment') { $segs.Add($t.id) }
            elseif ($t.type -eq 'dvportgroup') { foreach ($r2 in @($Context.out[$t.id])) { if ($r2.type -eq 'connects' -and $Context.assets[$r2.target] -and $Context.assets[$r2.target].type -eq 'nsx-segment') { $segs.Add($r2.target) } } }
        }
        $map[$vm.id] = @($segs | Select-Object -Unique)
    }
    return $map
}

function Get-VsatGroupIndex {
    param($Context)
    $g = @{}
    foreach ($ga in @($Context.evidence.assets | Where-Object { $_.type -eq 'nsx-group' })) {
        $path = [string]$ga.props.path
        $entry = @{ id = $ga.id; name = $ga.name; known = $false; vms = @{}; ips = @{} }
        if ($ga.facts.Contains('members') -and $ga.facts.members.status -eq 'ok') {
            $entry.known = $true
            foreach ($v in @($ga.facts.members.value.vms)) { $entry.vms[[string]$v.externalId] = $true }
            foreach ($ip in @($ga.facts.members.value.ips)) { $entry.ips[[string]$ip] = $true }
        }
        $g["$($ga.endpoint):$path"] = $entry
    }
    return $g
}

function Test-VsatGroupRef {
    # Returns 'yes' | 'no' | 'unknown' for a VM against a rule's group list.
    param($Refs, $Vm, $Groups, [string]$Endpoint)
    if (@($Refs) -contains 'ANY') { return 'yes' }
    $unknown = $false
    foreach ($ref in @($Refs)) {
        $g = $Groups["${Endpoint}:$ref"]
        if (-not $g) {
            if ($ref -match '^\d{1,3}(\.\d{1,3}){3}(/\d+)?$') { if (@($Vm.props.ipAddresses) -contains ($ref -replace '/32$', '')) { return 'yes' }; continue }
            $unknown = $true; continue
        }
        if (-not $g.known) { $unknown = $true; continue }
        if ($g.vms.ContainsKey([string]$Vm.props.instanceUuid)) { return 'yes' }
        foreach ($ip in @($Vm.props.ipAddresses)) { if ($g.ips.ContainsKey([string]$ip)) { return 'yes' } }
    }
    if ($unknown) { return 'unknown' }
    return 'no'
}

function Get-VsatDfwDecision {
    # First-match evaluation of DFW policy for any traffic from Src to Dst (configuration-inferred).
    param($Src, $Dst, $Rules, $Groups, [string]$Endpoint)
    $allowed = [System.Collections.Generic.List[object]]::new()
    $uncertain = [System.Collections.Generic.List[string]]::new()
    foreach ($r in $Rules) {
        $p = $r.props
        if ($p.disabled) { continue }
        $act = ([string]$p.action).ToUpperInvariant()
        if ($act -eq 'JUMP_TO_APPLICATION') { continue }
        if ($p.sourcesExcluded -or $p.destinationsExcluded) { $uncertain.Add("rule '$($r.name)' uses negated groups (not evaluated)"); continue }
        $scope = if (@($p.appliedTo) -contains 'ANY') { $p.policyAppliedTo } else { $p.appliedTo }
        $sc = if (@($scope) -contains 'ANY') { 'yes' } else {
            $a1 = Test-VsatGroupRef $scope $Dst $Groups $Endpoint
            $a2 = Test-VsatGroupRef $scope $Src $Groups $Endpoint
            if ($a1 -eq 'yes' -or $a2 -eq 'yes') { 'yes' } elseif ($a1 -eq 'unknown' -or $a2 -eq 'unknown') { 'unknown' } else { 'no' }
        }
        $sm = Test-VsatGroupRef $p.sources $Src $Groups $Endpoint
        $dm = Test-VsatGroupRef $p.destinations $Dst $Groups $Endpoint
        if ($sc -eq 'no' -or $sm -eq 'no' -or $dm -eq 'no') { continue }
        $partial = ($sc -eq 'unknown' -or $sm -eq 'unknown' -or $dm -eq 'unknown')
        $anySvc = (@($p.services) -contains 'ANY') -and (@($p.profiles) -contains 'ANY')
        $ruleRef = [ordered]@{ ruleAssetId = $r.id; name = $r.name; action = $act; category = $p.category; services = @($p.services); reason = '' }
        if ($partial) { $uncertain.Add("rule '$($r.name)' references groups with unknown effective membership"); continue }
        if ($act -eq 'ALLOW') {
            $ruleRef.reason = "matches (sources $(Format-VsatValue $p.sources) -> destinations $(Format-VsatValue $p.destinations)); services $(Format-VsatValue $p.services)"
            $allowed.Add($ruleRef)
            if ($anySvc) { return @{ decision = 'allow'; rules = @($allowed); uncertainty = @($uncertain); final = $ruleRef } }
            continue
        }
        if ($anySvc) {
            $ruleRef.reason = "first full match denies all services"
            if ($allowed.Count) { return @{ decision = 'allow'; rules = @($allowed) + $ruleRef; uncertainty = @($uncertain) + 'Only the services listed on earlier ALLOW rules are reachable'; final = $ruleRef } }
            return @{ decision = $(if ($uncertain.Count) { 'unknown' } else { 'deny' }); rules = @($ruleRef); uncertainty = @($uncertain); final = $ruleRef }
        }
    }
    if ($allowed.Count) { return @{ decision = 'allow'; rules = @($allowed); uncertainty = @($uncertain) + 'Service-specific allows only' } }
    return @{ decision = 'unknown'; rules = @(); uncertainty = @($uncertain) + 'No matching rule or default rule found in collected policy' }
}

function Get-VsatAttackPaths {
    param([Parameter(Mandatory)]$Context, [int]$MaxSources = 40, [int]$MaxTargets = 40)
    $result = [ordered]@{ attackPaths = @(); chokepoints = @(); privilegePaths = @(); notes = @() }
    $ev = $Context.evidence
    $result.privilegePaths = @(Get-VsatPrivilegePaths -Context $Context)
    $mgrs = @($ev.assets | Where-Object { $_.type -eq 'nsx-manager' })
    if ($mgrs.Count -eq 0) { $result.notes = @('Network attack paths require assessed NSX policy; none available.'); return $result }
    $vmSeg = Get-VsatVmSegments $Context
    $groups = Get-VsatGroupIndex $Context
    $vms = @($ev.assets | Where-Object { $_.type -eq 'vm' -and -not $_.props.template -and @($vmSeg[$_.id]).Count })
    $targets = @($vms | Where-Object { $_.criticality -eq 'high' } | Select-Object -First $MaxTargets)
    if ($targets.Count -eq 0) { $result.notes = @('No critical workloads identified; mark critical assets in the scope file to model attack paths.'); return $result }
    # One representative source per zone/segment keeps the model bounded and explainable.
    $sources = [System.Collections.Generic.List[object]]::new()
    $seen = @{}
    foreach ($vm in $vms) {
        if ($vm.criticality -eq 'high') { continue }
        $key = if ($vm.zone) { "zone:$($vm.zone)" } else { "seg:" + (@($vmSeg[$vm.id]) -join ',') }
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true; $sources.Add($vm)
        if ($sources.Count -ge $MaxSources) { break }
    }
    $paths = [System.Collections.Generic.List[object]]::new()
    $choke = @{}
    $n = 0
    foreach ($t in $targets) {
        foreach ($s in $sources) {
            $sSeg = @($vmSeg[$s.id])[0]; $tSeg = @($vmSeg[$t.id])[0]
            $ep = ($sSeg -split ':')[0]
            if (($tSeg -split ':')[0] -ne $ep) { continue }   # different NSX domains are never merged
            if (-not $Context.Contains("dfw:$ep")) { $Context["dfw:$ep"] = @(Get-VsatNsxRules $Context $ep 'dfw') }
            $d = Get-VsatDfwDecision -Src $s -Dst $t -Rules $Context["dfw:$ep"] -Groups $groups -Endpoint $ep
            $hops = [System.Collections.Generic.List[object]]::new()
            $hops.Add([ordered]@{ asset = $s.id; via = 'source' })
            $hops.Add([ordered]@{ asset = $sSeg; via = 'connects' })
            if ($sSeg -ne $tSeg) {
                $gw = @($Context.out[$sSeg] | Where-Object { $_.type -eq 'routes' }) | Select-Object -First 1
                if ($gw) { $hops.Add([ordered]@{ asset = $gw.target; via = 'routes' }) }
                $hops.Add([ordered]@{ asset = $tSeg; via = 'routes' })
            }
            $hops.Add([ordered]@{ asset = $t.id; via = 'connects' })
            $n++
            $unc = @($d.uncertainty) + @('Guest OS firewalls and upstream physical ACLs are not assessed', 'Configuration-inferred: not proof of reachability or exploitability')
            if ($sSeg -ne $tSeg) { $unc += 'Gateway firewall between segments not modeled in this path' }
            $p = [ordered]@{
                id = ('AP-{0:d3}' -f $n); source = $s.id; sourceZone = $(if ($s.zone) { $s.zone } else { $Context.assets[$sSeg].name }); target = $t.id
                decision = $d.decision; confidence = 'configuration-inferred'; hops = @($hops); rules = @($d.rules)
                explanation = $(switch ($d.decision) { 'allow' { "Traffic from $($s.name) to $($t.name) is permitted by $(@($d.rules | Where-Object { $_.action -eq 'ALLOW' })[0].name)." } 'deny' { "Traffic from $($s.name) to $($t.name) is blocked by $($d.final.name)." } default { "Decision for $($s.name) to $($t.name) cannot be determined from collected evidence." } })
                prerequisites = @("Attacker controls $($s.name) (or a workload in the same segment/zone)")
                uncertainty = @($unc | Select-Object -Unique)
            }
            $paths.Add($p)
            if ($d.decision -eq 'allow') { foreach ($r in @($d.rules | Where-Object { $_.action -eq 'ALLOW' })) { $choke[$r.ruleAssetId] = @{ name = $r.name; n = [int](Get-VsatProp $choke[$r.ruleAssetId] 'n' 0) + 1 } } }
        }
    }
    $result.attackPaths = @($paths)
    $result.chokepoints = @($choke.Keys | ForEach-Object { [ordered]@{ ruleAssetId = $_; name = $choke[$_].name; pathsInterrupted = $choke[$_].n } } | Sort-Object { - $_.pathsInterrupted })
    return $result
}

function Get-VsatPrivilegePaths {
    param($Context)
    $out = [System.Collections.Generic.List[object]]::new()
    foreach ($vc in @($Context.evidence.assets | Where-Object { $_.type -eq 'vcenter' })) {
        if (-not $vc.facts.Contains('permissions') -or $vc.facts.permissions.status -ne 'ok') { continue }
        foreach ($p in @($vc.facts.permissions.value)) {
            if ($p.role -in @('ReadOnly', 'NoAccess', 'Anonymous', 'View')) { continue }
            $mo = ([string]$p.entityId -replace '^[A-Za-z]+-', '')
            $obj = "$($vc.endpoint):$mo"
            if (-not $Context.assets.ContainsKey($obj)) { $obj = $vc.id }
            $out.Add([ordered]@{ principal = $p.principal; role = $p.role; object = $obj; objectName = $p.entity; propagate = [bool]$p.propagate; isGroup = [bool]$p.isGroup })
        }
    }
    return @($out)
}
#endregion Attack paths

#region Failure impact
function Get-VsatImpact {
    param([Parameter(Mandatory)]$Context, [int]$MaxAffected = 500)
    $ev = $Context.evidence
    $list = [System.Collections.Generic.List[object]]::new()
    $vmsOnHost = @{}; $vmsOnDs = @{}; $vmsOnNet = @{}
    foreach ($r in $ev.relationships) {
        switch ($r.type) {
            'runs-on' { if (-not $vmsOnHost[$r.target]) { $vmsOnHost[$r.target] = [System.Collections.Generic.List[string]]::new() }; $vmsOnHost[$r.target].Add($r.source) }
            'stores' { if (-not $vmsOnDs[$r.target]) { $vmsOnDs[$r.target] = [System.Collections.Generic.List[string]]::new() }; $vmsOnDs[$r.target].Add($r.source) }
            'connects' { if ($Context.assets[$r.source] -and $Context.assets[$r.source].type -eq 'vm') { if (-not $vmsOnNet[$r.target]) { $vmsOnNet[$r.target] = [System.Collections.Generic.List[string]]::new() }; $vmsOnNet[$r.target].Add($r.source) } }
        }
    }
    foreach ($h in @($ev.assets | Where-Object { $_.type -in @('host', 'hyperv-host', 'kvm-host') })) {
        $cl = @($Context.in[$h.id] | Where-Object { $_.type -eq 'contains' -and $Context.assets[$_.source] -and $Context.assets[$_.source].type -in @('cluster', 'hyperv-cluster') }) | Select-Object -First 1
        $ha = $false; $peers = 0
        if ($cl) {
            $c = $Context.assets[$cl.source]
            $ha = if ($c.type -eq 'hyperv-cluster') { $true } else { [bool](Get-VsatProp $c.facts 'ha.value.enabled' $false) }
            $peers = if ($c.type -eq 'hyperv-cluster') { @($c.props.nodes).Count - 1 } else { @($Context.out[$c.id] | Where-Object { $_.type -eq 'contains' }).Count - 1 }
        }
        $aff = @($vmsOnHost[$h.id] | Select-Object -First $MaxAffected | ForEach-Object {
                $vmA = $Context.assets[$_]
                # Hyper-V: only clustered VMs fail over; KVM: no libvirt-level HA is assumed.
                $vmHa = $ha -and $peers -gt 0 -and ($h.type -ne 'hyperv-host' -or [bool](Get-VsatProp $vmA 'props.clustered' $false))
                $effect = if ($vmHa) { 'restart-expected' } else { 'outage' }
                [ordered]@{ asset = $_; effect = $effect; reason = $(if ($vmHa) { "HA/failover clustering with $peers other node(s); restart depends on capacity" } else { 'No HA restart target known' }) } })
        $effect = if (@($aff | Where-Object { $_.effect -eq 'restart-expected' }).Count -eq $aff.Count -and $aff.Count) { 'restart-expected' } else { 'outage' }
        if ($aff.Count) { $list.Add([ordered]@{ component = $h.id; componentType = $h.type; affected = $aff; redundancy = $(if ($effect -eq 'restart-expected') { 'redundant' } else { 'none' }); notes = @('HA capacity is not verified; this is not proof of successful failover') }) }
    }
    foreach ($d in @($ev.assets | Where-Object { $_.type -eq 'datastore' })) {
        $isVsan = ($d.props.type -eq 'vsan')
        $effect = if ($isVsan) { 'degraded' } else { 'outage' }
        $aff = @($vmsOnDs[$d.id] | Select-Object -Unique -First $MaxAffected | ForEach-Object { [ordered]@{ asset = $_; effect = $effect; reason = $(if ($isVsan) { 'vSAN storage policy determines tolerance (not evaluated)' } else { 'VM files stored on this datastore' }) } })
        if ($aff.Count) { $list.Add([ordered]@{ component = $d.id; componentType = 'datastore'; affected = $aff; redundancy = $(if ($isVsan) { 'unknown' } else { 'none' }); notes = @('Array-level redundancy and replication are not assessed') }) }
    }
    foreach ($sw in @($ev.assets | Where-Object { $_.type -eq 'vss' })) {
        $ups = @($Context.out[$sw.id] | Where-Object { $_.type -eq 'uplink' } | ForEach-Object { $_.target })
        $pgs = @($Context.out[$sw.id] | Where-Object { $_.type -eq 'contains' } | ForEach-Object { $_.target })
        $vms = @($pgs | ForEach-Object { $vmsOnNet[$_] } | Where-Object { $_ } | Select-Object -Unique)
        foreach ($u in $ups) {
            $effect = if ($ups.Count -ge 2) { 'degraded' } else { 'outage' }
            $aff = @($vms | Select-Object -First $MaxAffected | ForEach-Object { [ordered]@{ asset = $_; effect = $effect; reason = $(if ($effect -eq 'degraded') { "$($ups.Count) uplinks on $($sw.name)" } else { "single uplink on $($sw.name)" }) } })
            if ($aff.Count) { $list.Add([ordered]@{ component = $u; componentType = 'pnic'; affected = $aff; redundancy = $(if ($ups.Count -ge 2) { 'redundant' } else { 'none' }); notes = @('Upstream physical redundancy is unknown unless LLDP/CDP shows distinct neighbors') }) }
        }
    }
    foreach ($ec in @($ev.assets | Where-Object { $_.type -eq 'nsx-edge-cluster' })) {
        $gws = @($Context.in[$ec.id] | Where-Object { $_.type -eq 'depends' } | ForEach-Object { $_.source })
        $segs = [System.Collections.Generic.List[string]]::new()
        foreach ($g in $gws) {
            foreach ($r in @($Context.in[$g])) { if ($r.type -eq 'routes') { $segs.Add($r.source); foreach ($r2 in @($Context.in[$r.source])) { if ($r2.type -eq 'routes') { $segs.Add($r2.source) } } } }
        }
        $segIds = @($segs | Where-Object { $Context.assets[$_] -and $Context.assets[$_].type -eq 'nsx-segment' } | Select-Object -Unique)
        $vms = [System.Collections.Generic.List[string]]::new()
        foreach ($s in $segIds) {
            foreach ($x in @($vmsOnNet[$s])) { $vms.Add($x) }
            foreach ($r in @($Context.in[$s] | Where-Object { $_.type -eq 'connects' })) { foreach ($x in @($vmsOnNet[$r.source])) { $vms.Add($x) } }
        }
        $members = [int]$ec.props.memberCount
        $effect = if ($members -ge 2) { 'degraded' } else { 'outage' }
        $aff = @($vms | Select-Object -Unique -First $MaxAffected | ForEach-Object { [ordered]@{ asset = $_; effect = $effect; reason = "North-south and gateway services via $($ec.name) ($members edge node(s))" } })
        $list.Add([ordered]@{ component = $ec.id; componentType = 'nsx-edge-cluster'; affected = $aff; redundancy = $(if ($members -ge 2) { 'redundant' } else { 'none' }); notes = @('East-west distributed routing continues without edges', 'Physical uplink redundancy of edge nodes is unknown') })
    }
    foreach ($nb in @($ev.assets | Where-Object { $_.type -eq 'physical-neighbor' })) {
        $pn = @($Context.in[$nb.id] | Where-Object { $_.type -eq 'neighbor' } | ForEach-Object { $_.source })
        $hosts = @($pn | ForEach-Object { ($_ -split '/pnic/')[0] } | Select-Object -Unique)
        $aff = [System.Collections.Generic.List[object]]::new()
        foreach ($h in $hosts) {
            $allNb = @($Context.out[$h] | Where-Object { $_.type -eq 'contains' -and $Context.assets[$_.target] -and $Context.assets[$_.target].type -eq 'pnic' } | ForEach-Object { @($Context.out[$_.target] | Where-Object { $_.type -eq 'neighbor' } | ForEach-Object { $_.target }) } | Select-Object -Unique)
            $eff = if ($allNb.Count -le 1) { 'outage' } else { 'degraded' }
            foreach ($v in @($vmsOnHost[$h])) { $aff.Add([ordered]@{ asset = $v; effect = $eff; reason = $(if ($eff -eq 'outage') { "all observed uplinks of $($Context.assets[$h].name) connect to this switch" } else { "$($Context.assets[$h].name) has uplinks to other switches" }) }) }
        }
        if ($aff.Count) { $list.Add([ordered]@{ component = $nb.id; componentType = 'physical-neighbor'; affected = @($aff | Select-Object -First $MaxAffected); redundancy = 'unknown'; notes = @('Based on LLDP/CDP immediate-neighbor evidence only; the physical fabric is not fully visible') }) }
    }
    return @($list)
}
#endregion Failure impact

#region Work packages
function Get-VsatWorkPackages {
    param([Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Findings)
    $pack = Get-VsatRulePackMeta
    $defs = @{}; foreach ($w in @($pack.workPackages)) { $defs[$w.id] = $w }
    $groups = [ordered]@{}
    $sevRank = @{ critical = 5; high = 4; medium = 3; low = 2; info = 1 }
    foreach ($f in $Findings) {
        if ($f.result -notin @('FAIL', 'MANUAL')) { continue }
        if ($f.exception -and $f.exception.active) { continue }   # expired exceptions return to the worklist
        $wp = if ($f.result -eq 'MANUAL') { 'WP-MANUAL' } else { [string](Get-VsatProp $f.mitigation 'workPackage' 'WP-MANUAL') }
        if (-not $groups.Contains($wp)) { $groups[$wp] = [System.Collections.Generic.List[object]]::new() }
        $groups[$wp].Add($f)
    }
    $out = [System.Collections.Generic.List[object]]::new()
    foreach ($k in $groups.Keys) {
        $fs = $groups[$k]
        $d = if ($defs.ContainsKey($k)) { $defs[$k] } else { [ordered]@{ id = $k; title = $k; team = 'Unassigned' } }
        $steps = [System.Collections.Generic.List[string]]::new()
        foreach ($f in $fs) { $s = [string](Get-VsatProp $f.mitigation 'summary'); if ($s -and -not $steps.Contains($s)) { $steps.Add($s) } }
        $max = ($fs | Sort-Object { - [int]$sevRank[[string]$_.severity] } | Select-Object -First 1).severity
        $out.Add([ordered]@{
                id = $k; title = $d.title; team = $d.team; findingIds = @($fs | ForEach-Object { $_.id }); assetIds = @($fs | ForEach-Object { $_.assetId } | Select-Object -Unique)
                outcome = Get-VsatProp $d 'outcome' ''; prerequisites = @(Get-VsatProp $d 'prerequisites' @()); impact = Get-VsatProp $d 'impact' ''
                maintenanceWindow = [bool](Get-VsatProp $d 'maintenanceWindow' $false); rollback = Get-VsatProp $d 'rollback' ''; validation = Get-VsatProp $d 'validation' ''
                steps = @($steps); maxSeverity = $max; findingCount = $fs.Count
            })
    }
    return @($out | Sort-Object { - [int]$sevRank[[string]$_.maxSeverity] }, { - $_.findingCount })
}
#endregion Work packages

#region Drift
function Get-VsatDrift {
    param([Parameter(Mandatory)]$Current, [Parameter(Mandatory)]$Baseline)
    # Baseline findings were re-evaluated with the current rule pack so rule-version
    # changes do not masquerade as drift. Disappeared evidence is never "resolved".
    $cur = @{}; foreach ($f in $Current.findings) { $cur[$f.key] = $f }
    $old = @{}; foreach ($f in $Baseline.findings) { $old[$f.key] = $f }
    $items = [System.Collections.Generic.List[object]]::new()
    $counts = [ordered]@{ new = 0; resolved = 0; changed = 0; unassessed = 0; unchanged = 0 }
    $known = @('PASS', 'FAIL', 'NOT_APPLICABLE')
    foreach ($k in $cur.Keys) {
        $c = $cur[$k]; $o = $old[$k]
        $change = $null
        if (-not $o) { if ($c.result -eq 'FAIL') { $change = 'new' } }
        elseif ($o.result -eq $c.result) { $counts.unchanged++; continue }
        elseif ($c.result -eq 'FAIL') { $change = 'new' }
        elseif ($o.result -eq 'FAIL' -and $c.result -in @('PASS', 'NOT_APPLICABLE')) { $change = 'resolved' }
        elseif ($o.result -in $known -and $c.result -in @('UNKNOWN', 'ERROR')) { $change = 'unassessed' }
        else { $change = 'changed' }
        if (-not $change) { continue }
        $counts[$change]++
        $items.Add([ordered]@{ key = $k; ruleId = $c.ruleId; assetId = $c.assetId; assetName = $c.assetName; change = $change; before = $(if ($o) { $o.result } else { $null }); after = $c.result; title = $c.title })
    }
    foreach ($k in $old.Keys) {
        if ($cur.ContainsKey($k)) { continue }
        $o = $old[$k]
        if ($o.result -notin $known) { continue }
        $counts.unassessed++
        $items.Add([ordered]@{ key = $k; ruleId = $o.ruleId; assetId = $o.assetId; assetName = $o.assetName; change = 'unassessed'; before = $o.result; after = $null; title = $o.title })
    }
    $ca = @{}; foreach ($a in $Current.assets) { $ca[$a.id] = $a }
    $oa = @{}; foreach ($a in $Baseline.assets) { $oa[$a.id] = $a }
    $added = @($ca.Keys | Where-Object { -not $oa.ContainsKey($_) })
    $removed = @($oa.Keys | Where-Object { -not $ca.ContainsKey($_) })
    $nsxMod = 0
    foreach ($id in @($ca.Keys | Where-Object { $ca[$_].type -eq 'nsx-rule' -and $oa.ContainsKey($_) })) {
        if ((ConvertTo-VsatJson $ca[$id].props -Compress) -ne (ConvertTo-VsatJson $oa[$id].props -Compress)) { $nsxMod++ }
    }
    return [ordered]@{
        baselineRunId = $Baseline.run.id; baselineUtc = $Baseline.run.startedUtc; counts = $counts; items = @($items)
        assets = [ordered]@{ added = $added; removed = $removed }
        nsxRules = [ordered]@{ added = @($added | Where-Object { $ca[$_].type -eq 'nsx-rule' }).Count; removed = @($removed | Where-Object { $oa[$_].type -eq 'nsx-rule' }).Count; modified = $nsxMod }
    }
}
#endregion Drift

# ---- src/80-Results.ps1 ----
#region Results pipeline

function Invoke-VsatAnalysisPipeline {
    # Evidence -> findings, coverage, status, analysis. Pure function of evidence + rule pack,
    # which is what makes collect-once/replay possible.
    param([Parameter(Mandatory)]$Evidence, [string]$ProfileName = 'standard', $BaselineEvidence)
    Update-VsatProgress -Phase 'analyzing' -Message 'Correlating inventory'
    if (-not $script:VsatAssetIndex -or $script:VsatAssetIndex.Count -ne @($Evidence.assets).Count) {
        $script:VsatAssetIndex = @{}; foreach ($a in $Evidence.assets) { $script:VsatAssetIndex[$a.id] = $a }
    }
    if (-not (Get-VsatProp $Evidence.nsx 'correlated' $false)) {
        [void](Update-VsatNsxDiscovery -Evidence $Evidence)
        Invoke-VsatCorrelation -Evidence $Evidence
        $Evidence.nsx.correlated = $true
    }
    Set-VsatScopeAnnotations -Evidence $Evidence
    Update-VsatProgress -Message 'Evaluating rules'
    $eval = Invoke-VsatRules -Evidence $Evidence -ProfileName $ProfileName
    $findings = $eval.findings
    Set-VsatExceptions -Evidence $Evidence -Findings $findings
    $coverage = Get-VsatCoverage -Evidence $Evidence -Findings $findings
    $status = Get-VsatRunStatus -Evidence $Evidence -Coverage $coverage -Findings $findings
    Update-VsatProgress -Message 'Modeling attack paths and failure impact'
    $paths = Get-VsatAttackPaths -Context $eval.context
    $pathTargets = @{}
    foreach ($p in @($paths.attackPaths | Where-Object { $_.decision -eq 'allow' })) { $pathTargets[$p.target] = $true }
    Set-VsatPriority -Findings $findings -Context $eval.context -PathTargets $pathTargets
    $impact = Get-VsatImpact -Context $eval.context
    $wps = Get-VsatWorkPackages -Findings $findings
    $results = New-VsatResultsObject -Evidence $Evidence -Eval $eval -Coverage $coverage -Status $status -ProfileName $ProfileName
    $results.analysis = [ordered]@{ attackPaths = @($paths.attackPaths); privilegePaths = @($paths.privilegePaths); chokepoints = @($paths.chokepoints); pathNotes = @($paths.notes); impact = @($impact); workPackages = @($wps); drift = $null }
    if ($BaselineEvidence) {
        Update-VsatProgress -Message 'Comparing with baseline'
        $saveIdx = $script:VsatAssetIndex
        $b = Invoke-VsatBaselineResults -Evidence $BaselineEvidence -ProfileName $ProfileName
        $script:VsatAssetIndex = $saveIdx
        $results.analysis.drift = Get-VsatDrift -Current $results -Baseline $b
    }
    return $results
}

function Invoke-VsatBaselineResults {
    param($Evidence, [string]$ProfileName)
    $script:VsatAssetIndex = @{}; foreach ($a in $Evidence.assets) { $script:VsatAssetIndex[$a.id] = $a }
    if (-not (Get-VsatProp $Evidence.nsx 'correlated' $false)) { [void](Update-VsatNsxDiscovery -Evidence $Evidence); Invoke-VsatCorrelation -Evidence $Evidence; $Evidence.nsx.correlated = $true }
    $eval = Invoke-VsatRules -Evidence $Evidence -ProfileName $ProfileName
    return [ordered]@{ run = $Evidence.run; findings = $eval.findings; assets = @($Evidence.assets) }
}

function New-VsatResultsObject {
    param($Evidence, $Eval, $Coverage, $Status, [string]$ProfileName)
    $findings = $Eval.findings
    $sum = [ordered]@{ PASS = 0; FAIL = 0; MANUAL = 0; UNKNOWN = 0; ERROR = 0; NOT_APPLICABLE = 0 }
    $sev = [ordered]@{ critical = 0; high = 0; medium = 0; low = 0; info = 0 }
    $conf = [ordered]@{ observed = 0; inferred = 0 }
    foreach ($f in $findings) {
        $sum[$f.result] = [int]$sum[$f.result] + 1
        if ($f.result -eq 'FAIL') { $sev[[string]$f.severity] = [int]$sev[[string]$f.severity] + 1 }
        if ($f.result -in @('PASS', 'FAIL')) { $conf[[string]$f.confidence] = [int]$conf[[string]$f.confidence] + 1 }
    }
    $byAsset = @{}
    $rank = @{ critical = 5; high = 4; medium = 3; low = 2; info = 1 }
    foreach ($f in $findings) {
        if (-not $byAsset.ContainsKey($f.assetId)) { $byAsset[$f.assetId] = @{ counts = [ordered]@{}; worst = $null } }
        $e = $byAsset[$f.assetId]
        $e.counts[$f.result] = [int]$e.counts[$f.result] + 1
        if ($f.result -eq 'FAIL' -and ($null -eq $e.worst -or $rank[[string]$f.severity] -gt $rank[[string]$e.worst])) { $e.worst = $f.severity }
    }
    $assetTypes = [ordered]@{}
    $assets = foreach ($a in $Evidence.assets) {
        $assetTypes[$a.type] = [int]$assetTypes[$a.type] + 1
        $o = [ordered]@{}
        foreach ($k in $a.Keys) { if ($k -ne 'facts') { $o[$k] = $a[$k] } }
        $o.factStatus = [ordered]@{}; foreach ($k in $a.facts.Keys) { $o.factStatus[$k] = $a.facts[$k].status }
        $o.findingCounts = $(if ($byAsset.ContainsKey($a.id)) { $byAsset[$a.id].counts } else { [ordered]@{} })
        $o.worstSeverity = $(if ($byAsset.ContainsKey($a.id)) { $byAsset[$a.id].worst } else { $null })
        $o
    }
    $adv = Get-VsatAdvisoryData
    $age = [int]([DateTime]::UtcNow - [DateTime]::Parse($adv.snapshotDate, [Globalization.CultureInfo]::InvariantCulture)).TotalDays
    return [ordered]@{
        schemaVersion = $script:VsatSchemaVersion
        tool = [ordered]@{ name = 'VSAT'; version = $script:VsatVersion }
        run = $Evidence.run
        generatedUtc = (Get-VsatUtcNow)
        rulePack = [ordered]@{ version = $Eval.rulePackVersion; profile = $ProfileName; ruleCount = @($Eval.rules).Count; excludedAssets = $Eval.excluded }
        advisory = [ordered]@{ snapshotDate = $adv.snapshotDate; ageDays = $age }
        status = $Status
        coverage = $Coverage
        summary = [ordered]@{ results = $sum; severity = $sev; confidence = $conf; assets = $assetTypes }
        findings = @($findings)
        assets = @($assets)
        relationships = @($Evidence.relationships)
        analysis = $null
        rules = @($Eval.rules | ForEach-Object { [ordered]@{ id = $_.id; title = $_.title; domain = $_.domain; severity = $_.severity; assetType = $_.assetType; rationale = $_.rationale; mitigation = $_.mitigation; frameworks = $_.frameworks; limitations = (Get-VsatProp $_ 'limitations' ''); automated = ($_.check.type -ne 'manual'); profiles = @(Get-VsatProp $_ 'profilesEnabled' @('standard', 'strict')) } })
        scope = $Evidence.scope
        collection = [ordered]@{ collectors = @($Evidence.collection.collectors); log = @($Evidence.collection.log | Select-Object -Last 500) }
        nsx = $Evidence.nsx
    }
}

#endregion Results pipeline

#region Report rendering

function ConvertTo-VsatScriptJson {
    # JSON safe to embed inside <script type="application/json">: no '<', '>', '&', U+2028/9.
    param([Parameter(Mandatory)]$Object)
    $json = ConvertTo-VsatJson $Object -Compress
    $bs = [string][char]92
    return $json.Replace('<', $bs + 'u003c').Replace('>', $bs + 'u003e').Replace('&', $bs + 'u0026').Replace([string][char]0x2028, $bs + 'u2028').Replace([string][char]0x2029, $bs + 'u2029')
}

function Get-VsatReportData {
    # Compact PASS/NOT_APPLICABLE findings; full detail stays in results.json.
    param([Parameter(Mandatory)]$Results)
    $data = [ordered]@{}
    foreach ($k in $Results.Keys) { $data[$k] = $Results[$k] }
    $data.findings = @(foreach ($f in $Results.findings) {
            if ($f.result -in @('PASS', 'NOT_APPLICABLE')) {
                [ordered]@{ id = $f.id; key = $f.key; ruleId = $f.ruleId; title = $f.title; domain = $f.domain; assetId = $f.assetId; assetName = $f.assetName; assetType = $f.assetType; result = $f.result; severity = $f.severity; observed = $f.observed; expected = $f.expected; confidence = $f.confidence; exception = $f.exception }
            }
            else { $f }
        })
    $data.scope = [ordered]@{ endpoints = @($Results.scope.endpoints | ForEach-Object { [ordered]@{ id = $_.id; type = $_.type; address = $_.address; status = $_.status; product = $_.product; version = $_.version; build = $_.build } }); nsxDeclaredAbsent = $Results.scope.nsxDeclaredAbsent }
    return $data
}

function New-VsatHtmlDocument {
    param([Parameter(Mandatory)][string]$Template, [Parameter(Mandatory)][string]$Css, [Parameter(Mandatory)][string]$Js, $DataJson = $null, [string]$Title = 'VSAT Report', [string]$ExtraCsp = '')
    $cssHash = Get-VsatSha256Base64 $Css
    $jsHash = Get-VsatSha256Base64 $Js
    $csp = "default-src 'none'; script-src 'sha256-$jsHash'; style-src 'sha256-$cssHash'; img-src data: blob:; font-src 'none'; base-uri 'none'; form-action 'none'$ExtraCsp"
    $safeTitle = [System.Net.WebUtility]::HtmlEncode($Title)
    # Replace tokens with literal (non-regex) substitution; data first so no token inside data is expanded.
    $parts = $Template
    $parts = $parts.Replace('__VSAT_TITLE__', $safeTitle).Replace('__VSAT_CSP__', $csp)
    $parts = $parts.Replace('__VSAT_CSS__', $Css)
    if ($null -ne $DataJson) { $idx = $parts.IndexOf('__VSAT_DATA__'); if ($idx -ge 0) { $parts = $parts.Substring(0, $idx) + '__VSAT_DATA_SLOT__' + $parts.Substring($idx + 13) } }
    $idx = $parts.IndexOf('__VSAT_JS__')
    if ($idx -ge 0) { $parts = $parts.Substring(0, $idx) + $Js + $parts.Substring($idx + 11) }
    if ($null -ne $DataJson) { $idx = $parts.IndexOf('__VSAT_DATA_SLOT__'); $parts = $parts.Substring(0, $idx) + $DataJson + $parts.Substring($idx + 18) }
    return $parts
}

function New-VsatReportHtml {
    param([Parameter(Mandatory)]$Results, [string]$Title)
    if (-not $Title) { $Title = "VSAT Report - $($Results.status.label)" }
    $data = ConvertTo-VsatScriptJson (Get-VsatReportData $Results)
    return (New-VsatHtmlDocument -Template (Get-VsatEmbeddedText 'assets/report/report.html') -Css (Get-VsatEmbeddedText 'assets/report/report.css') -Js (Get-VsatEmbeddedText 'assets/report/report.js') -DataJson $data -Title $Title)
}

#endregion Report rendering

#region Output files and evidence package

function Get-VsatFindingRows {
    param([object[]]$Findings)
    foreach ($f in $Findings) {
        [ordered]@{
            id = $f.id; result = $f.result; severity = $f.severity; priority = (Get-VsatProp $f 'priority.score'); ruleId = $f.ruleId; title = $f.title; domain = $f.domain
            assetType = $f.assetType; assetName = $f.assetName; assetId = $f.assetId; observed = $f.observed; expected = $f.expected; confidence = $f.confidence
            mitigation = (Get-VsatProp $f 'mitigation.summary'); workPackage = (Get-VsatProp $f 'mitigation.workPackage')
            frameworks = (@($f.frameworks | ForEach-Object { "$($_.framework) $($_.control) [$($_.mappingStatus)]" }) -join '; ')
            exception = $(if ($f.exception) { "$($f.exception.owner) until $($f.exception.expires) ($(if ($f.exception.active) { 'active' } else { 'EXPIRED' }))" } else { '' })
        }
    }
}

function Write-VsatOutputs {
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)]$Results, [Parameter(Mandatory)][string]$OutputDir, [switch]$Redact)
    if (-not (Test-Path -LiteralPath $OutputDir)) { [void](New-Item -ItemType Directory -Path $OutputDir -Force) }
    [void](Protect-VsatDirectory -Path $OutputDir)
    $Evidence.collection.log = @($script:VsatLog)
    $files = [ordered]@{}
    $files['evidence.json'] = ConvertTo-VsatJson $Evidence
    $files['results.json'] = ConvertTo-VsatJson $Results
    $files['report.html'] = New-VsatReportHtml -Results $Results
    foreach ($name in $files.Keys) { Write-VsatFile -Path (Join-Path $OutputDir $name) -Content $files[$name] }
    $rows = @(Get-VsatFindingRows $Results.findings)
    Export-VsatCsv -Rows $rows -Columns @('id', 'result', 'severity', 'priority', 'ruleId', 'title', 'domain', 'assetType', 'assetName', 'assetId', 'observed', 'expected', 'confidence', 'mitigation', 'workPackage', 'frameworks', 'exception') -Path (Join-Path $OutputDir 'findings.csv')
    $wl = foreach ($wp in @($Results.analysis.workPackages)) {
        foreach ($fid in $wp.findingIds) {
            $f = @($Results.findings | Where-Object { $_.id -eq $fid })[0]
            [ordered]@{ workPackage = $wp.id; title = $wp.title; team = $wp.team; maintenanceWindow = $wp.maintenanceWindow; findingId = $fid; severity = $f.severity; ruleId = $f.ruleId; asset = $f.assetName; action = (Get-VsatProp $f 'mitigation.summary'); validation = $wp.validation; rollback = $wp.rollback }
        }
    }
    Export-VsatCsv -Rows @($wl) -Columns @('workPackage', 'title', 'team', 'maintenanceWindow', 'findingId', 'severity', 'ruleId', 'asset', 'action', 'validation', 'rollback') -Path (Join-Path $OutputDir 'worklist.csv')
    $logText = ($script:VsatLog | ForEach-Object { "{0} [{1}] {2}: {3}" -f $_.t, $_.level, $_.source, $_.message }) -join [Environment]::NewLine
    Write-VsatFile -Path (Join-Path $OutputDir 'collection.log') -Content $logText
    $manifest = New-VsatManifest -Results $Results -OutputDir $OutputDir -Names @('evidence.json', 'results.json', 'report.html', 'findings.csv', 'worklist.csv', 'collection.log')
    Write-VsatFile -Path (Join-Path $OutputDir 'manifest.json') -Content (ConvertTo-VsatJson $manifest)
    $zip = Join-Path $OutputDir 'assessment.vsat.zip'
    New-VsatPackage -Path $zip -SourceDir $OutputDir -Names @('evidence.json', 'results.json', 'report.html', 'findings.csv', 'worklist.csv', 'collection.log', 'manifest.json')
    $out = @('report.html', 'results.json', 'evidence.json', 'findings.csv', 'worklist.csv', 'collection.log', 'manifest.json', 'assessment.vsat.zip')
    if ($Redact) {
        $red = Get-VsatRedactedCopy -Evidence $Evidence -Results $Results
        $rdir = Join-Path $OutputDir 'redacted'
        [void](New-Item -ItemType Directory -Path $rdir -Force)
        Write-VsatFile -Path (Join-Path $rdir 'evidence.json') -Content (ConvertTo-VsatJson $red.evidence)
        Write-VsatFile -Path (Join-Path $rdir 'results.json') -Content (ConvertTo-VsatJson $red.results)
        Write-VsatFile -Path (Join-Path $rdir 'report.html') -Content (New-VsatReportHtml -Results $red.results -Title "VSAT Report (redacted) - $($red.results.status.label)")
        Export-VsatCsv -Rows @(Get-VsatFindingRows $red.results.findings) -Columns @('id', 'result', 'severity', 'priority', 'ruleId', 'title', 'domain', 'assetType', 'assetName', 'assetId', 'observed', 'expected', 'confidence', 'mitigation', 'workPackage', 'frameworks', 'exception') -Path (Join-Path $rdir 'findings.csv')
        $rm = New-VsatManifest -Results $red.results -OutputDir $rdir -Names @('evidence.json', 'results.json', 'report.html', 'findings.csv')
        $rm.redacted = $true
        Write-VsatFile -Path (Join-Path $rdir 'manifest.json') -Content (ConvertTo-VsatJson $rm)
        New-VsatPackage -Path (Join-Path $OutputDir 'assessment.redacted.vsat.zip') -SourceDir $rdir -Names @('evidence.json', 'results.json', 'report.html', 'findings.csv', 'manifest.json')
        Copy-Item -LiteralPath (Join-Path $rdir 'report.html') -Destination (Join-Path $OutputDir 'report.redacted.html') -Force
        $out += @('report.redacted.html', 'assessment.redacted.vsat.zip')
    }
    return $out
}

function New-VsatManifest {
    param($Results, [string]$OutputDir, [string[]]$Names)
    $pcli = $null
    try { $m = Get-Module VMware.VimAutomation.Core -ErrorAction SilentlyContinue | Select-Object -First 1; if ($m) { $pcli = [string]$m.Version } } catch { }
    return [ordered]@{
        schemaVersion = $script:VsatSchemaVersion
        tool = [ordered]@{ name = 'VSAT'; version = $script:VsatVersion; buildCommit = $script:VsatBuildCommit }
        rulePack = $Results.rulePack.version; advisorySnapshot = $Results.advisory.snapshotDate
        runId = $Results.run.id; startedUtc = $Results.run.startedUtc; endedUtc = $Results.run.endedUtc; mode = $Results.run.mode
        status = $Results.status.overall; statusLabel = $Results.status.label; exitCode = $Results.status.exitCode
        coverage = @($Results.coverage.domains | ForEach-Object { [ordered]@{ domain = $_.id; state = $_.state } })
        dependencies = [ordered]@{ powershell = [string]$PSVersionTable.PSVersion; edition = [string]$PSVersionTable.PSEdition; os = [string][Environment]::OSVersion.VersionString; powercli = $pcli }
        files = @($Names | ForEach-Object { $p = Join-Path $OutputDir $_; [ordered]@{ name = $_; sha256 = (Get-VsatSha256 -Path $p); bytes = (Get-Item -LiteralPath $p).Length } })
        note = 'SHA-256 hashes provide integrity checking of this package, not proof that source systems reported truthfully. Contains sensitive infrastructure data.'
    }
}

function New-VsatPackage {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][string]$SourceDir, [Parameter(Mandatory)][string[]]$Names)
    Add-Type -AssemblyName System.IO.Compression, System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
    if (Test-Path -LiteralPath $Path) { Remove-Item -LiteralPath $Path -Force }
    $fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::CreateNew)
    try {
        $zip = New-Object System.IO.Compression.ZipArchive($fs, [System.IO.Compression.ZipArchiveMode]::Create)
        try {
            foreach ($n in $Names) {
                $e = $zip.CreateEntry($n, [System.IO.Compression.CompressionLevel]::Optimal)
                $e.LastWriteTime = [DateTimeOffset]::new(2000, 1, 1, 0, 0, 0, [TimeSpan]::Zero)
                $s = $e.Open()
                try { $b = [System.IO.File]::ReadAllBytes((Join-Path $SourceDir $n)); $s.Write($b, 0, $b.Length) } finally { $s.Dispose() }
            }
        }
        finally { $zip.Dispose() }
    }
    finally { $fs.Dispose() }
}

$script:VsatZipLimits = @{ MaxEntries = 64; MaxEntryBytes = 512MB; MaxTotalBytes = 1GB; MaxRatio = 200 }

function Read-VsatPackage {
    # Reads an evidence package without extracting to disk: fixed entry names only,
    # path validation, entry/size/ratio limits (zip-slip and decompression-bomb safe).
    param([Parameter(Mandatory)][string]$Path)
    Add-Type -AssemblyName System.IO.Compression, System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
    $full = (Resolve-Path -LiteralPath $Path).ProviderPath
    if ($full -match '\.json$') {
        $txt = [System.IO.File]::ReadAllText($full)
        return [ordered]@{ evidence = (ConvertFrom-VsatJson $txt); integrity = 'not-verified (plain evidence.json)'; manifest = $null }
    }
    $zip = [System.IO.Compression.ZipFile]::OpenRead($full)
    try {
        if ($zip.Entries.Count -gt $script:VsatZipLimits.MaxEntries) { throw "Package has too many entries ($($zip.Entries.Count))." }
        $total = 0L
        $wanted = @{}
        foreach ($e in $zip.Entries) {
            $n = $e.FullName
            if ($n -match '(^|[\\/])\.\.([\\/]|$)' -or $n.StartsWith('/') -or $n.StartsWith('\') -or $n -match '^[A-Za-z]:' -or $n.Contains('\')) { throw "Package entry has an unsafe path: $n" }
            if ($e.Length -gt $script:VsatZipLimits.MaxEntryBytes) { throw "Package entry $n exceeds the size limit." }
            if ($e.CompressedLength -gt 0 -and ($e.Length / [double]$e.CompressedLength) -gt $script:VsatZipLimits.MaxRatio) { throw "Package entry $n exceeds the compression ratio limit." }
            $total += $e.Length
            if ($total -gt $script:VsatZipLimits.MaxTotalBytes) { throw 'Package exceeds the total size limit.' }
            if ($n -in @('evidence.json', 'manifest.json')) { $wanted[$n] = $e }
        }
        if (-not $wanted.ContainsKey('evidence.json')) { throw 'Package does not contain evidence.json.' }
        $read = {
            param($entry)
            $s = $entry.Open(); $ms = New-Object System.IO.MemoryStream
            try {
                $buf = New-Object byte[] 65536; $sum = 0L
                while (($r = $s.Read($buf, 0, $buf.Length)) -gt 0) { $sum += $r; if ($sum -gt $script:VsatZipLimits.MaxEntryBytes) { throw 'Entry exceeded size limit while reading.' }; $ms.Write($buf, 0, $r) }
                return , $ms.ToArray()
            }
            finally { $s.Dispose(); $ms.Dispose() }
        }
        $evBytes = & $read $wanted['evidence.json']
        $integrity = 'no-manifest'
        $manifest = $null
        if ($wanted.ContainsKey('manifest.json')) {
            $manifest = ConvertFrom-VsatJson ([System.Text.Encoding]::UTF8.GetString((& $read $wanted['manifest.json'])))
            $expected = @($manifest.files | Where-Object { $_.name -eq 'evidence.json' })[0].sha256
            $actual = Get-VsatSha256 -Bytes $evBytes
            if ($expected -and $expected -ne $actual) { throw 'Evidence package integrity check failed: evidence.json does not match manifest.json.' }
            $integrity = 'verified (manifest SHA-256)'
        }
        $text = [System.Text.Encoding]::UTF8.GetString($evBytes)
        if ($text.Length -gt 0 -and $text[0] -eq [char]0xFEFF) { $text = $text.Substring(1) }
        $ev = ConvertFrom-VsatJson $text
        if ([string]$ev.schemaVersion -notmatch '^2\.') { throw "Unsupported evidence schema version '$($ev.schemaVersion)'." }
        return [ordered]@{ evidence = $ev; integrity = $integrity; manifest = $manifest }
    }
    finally { $zip.Dispose() }
}

function ConvertTo-VsatLiveEvidence {
    # Replayed JSON arrays become fixed-size; restore the mutable lists the pipeline expects.
    param([Parameter(Mandatory)]$Evidence)
    $Evidence.assets = New-VsatList $Evidence.assets
    $Evidence.relationships = New-VsatList $Evidence.relationships
    $Evidence.collection.collectors = New-VsatList $Evidence.collection.collectors
    $Evidence.scope = New-VsatScope $Evidence.scope
    foreach ($a in $Evidence.assets) {
        if (-not $a.Contains('facts') -or $null -eq $a.facts) { $a.facts = [ordered]@{} }
        if (-not $a.Contains('props') -or $null -eq $a.props) { $a.props = [ordered]@{} }
    }
    foreach ($e in $Evidence.scope.endpoints) { if (-not $e.Contains('errors') -or $null -eq $e.errors) { $e.errors = @() } }
    if (-not $Evidence.Contains('nsx') -or $null -eq $Evidence.nsx) { $Evidence.nsx = [ordered]@{ discovery = [ordered]@{ status = 'unknown'; evidence = @(); managersDiscovered = @() } } }
    $script:VsatAssetIndex = @{}; foreach ($a in $Evidence.assets) { $script:VsatAssetIndex[$a.id] = $a }
    return $Evidence
}

#endregion Output files and evidence package

#region Redaction

function Get-VsatRedactedCopy {
    # Consistent pseudonyms preserve graph relationships; original evidence is untouched.
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)]$Results)
    $map = @{}
    $counters = @{}
    $add = {
        param([string]$Value, [string]$Kind)
        if (-not $Value -or $Value.Length -lt 3 -or $map.ContainsKey($Value)) { return }
        $counters[$Kind] = [int]$counters[$Kind] + 1
        $map[$Value] = '{0}-{1:d4}' -f $Kind, $counters[$Kind]
    }
    foreach ($e in $Evidence.scope.endpoints) { & $add $e.address $e.type }
    foreach ($a in $Evidence.assets) {
        & $add $a.name $a.type
        if ($a.props.Contains('path') -and $a.props.path) { foreach ($seg in ([string]$a.props.path).Split('/')) { if ($seg -and $seg -notin @('infra', 'domains', 'default', 'segments', 'groups', 'security-policies', 'gateway-policies', 'rules', 'tier-0s', 'tier-1s', 'locale-services', 'nat', 'USER')) { & $add $seg 'obj' } } }
        foreach ($t in @($a.tags)) { & $add ([string]$t) 'tag' }
        if ($a.props.Contains('portgroup')) { & $add ([string]$a.props.portgroup) 'portgroup' }
        if ($a.props.Contains('vswitch')) { & $add ([string]$a.props.vswitch) 'vswitch' }
        if ($a.props.Contains('fqdn')) { & $add ([string]$a.props.fqdn) 'fqdn' }
        if ($a.facts.Contains('permissions') -and $a.facts.permissions.value) { foreach ($p in @($a.facts.permissions.value)) { & $add ([string]$p.principal) 'principal' } }
    }
    foreach ($m in @($Evidence.nsx.discovery.managersDiscovered)) { & $add $m 'nsx' }
    $keys = @($map.Keys | Sort-Object { - $_.Length })
    $ipMap = @{}
    # One compiled alternation keeps redaction linear in the size of each string.
    $nameRx = if ($keys.Count) { [regex]::new('(?<![A-Za-z0-9_.-])(?:' + (($keys | ForEach-Object { [regex]::Escape($_) }) -join '|') + ')(?![A-Za-z0-9_-])') } else { $null }
    $ipRx = [regex]::new('\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b')
    $macRx = [regex]::new('(?i)\b([0-9a-f]{2}[:-]){5}[0-9a-f]{2}\b')
    $uuidRx = [regex]::new('(?i)\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b')
    $ctx = @{ map = $map; ipMap = $ipMap; nameRx = $nameRx; ipRx = $ipRx; macRx = $macRx; uuidRx = $uuidRx }
    $ev = Invoke-VsatRedactValue -Value $Evidence -Ctx $ctx
    $res = Invoke-VsatRedactValue -Value $Results -Ctx $ctx
    $res.redacted = [ordered]@{ pseudonyms = $map.Count; ipAddresses = $ctx.ipMap.Count; note = 'Names, addresses, UUIDs and principals replaced with consistent pseudonyms. Review before sharing.' }
    return [ordered]@{ evidence = $ev; results = $res }
}

function Invoke-VsatRedactValue {
    # Walks the object graph and rewrites string values only (never JSON text), so
    # escaping stays intact and dictionary keys (setting names) are preserved.
    param($Value, $Ctx)
    if ($null -eq $Value) { return $null }
    if ($Value -is [string]) { return (Protect-VsatRedactString -Text $Value -Ctx $Ctx) }
    if ($Value -is [System.Collections.IDictionary]) {
        $o = [ordered]@{}
        foreach ($k in $Value.Keys) { $o[$k] = Invoke-VsatRedactValue -Value $Value[$k] -Ctx $Ctx }
        return $o
    }
    if ($Value -is [System.Collections.IEnumerable]) {
        $l = [System.Collections.Generic.List[object]]::new()
        foreach ($i in $Value) { $l.Add((Invoke-VsatRedactValue -Value $i -Ctx $Ctx)) }
        return , $l.ToArray()
    }
    return $Value
}

function Protect-VsatRedactString {
    param([string]$Text, $Ctx)
    if (-not $Text) { return $Text }
    $t = $Text
    if ($Ctx.nameRx) { $t = $Ctx.nameRx.Replace($t, [System.Text.RegularExpressions.MatchEvaluator] { param($m) $Ctx.map[$m.Value] }) }
    $t = $Ctx.ipRx.Replace($t, [System.Text.RegularExpressions.MatchEvaluator] {
            param($m)
            if (-not $Ctx.ipMap.ContainsKey($m.Value)) { $n = $Ctx.ipMap.Count + 1; $Ctx.ipMap[$m.Value] = '198.18.{0}.{1}' -f [int][Math]::Floor($n / 250), (($n % 250) + 1) }
            $Ctx.ipMap[$m.Value]
        })
    $t = $Ctx.macRx.Replace($t, '00:00:5e:00:53:00')
    $t = $Ctx.uuidRx.Replace($t, [System.Text.RegularExpressions.MatchEvaluator] { param($m) '00000000-0000-4000-8000-' + (Get-VsatSha256 -Text $m.Value.ToLowerInvariant()).Substring(0, 12) })
    return $t
}

#endregion Redaction

# ---- src/90-Server.ps1 ----
#region Local UI server
# Loopback-only HTTP server for the guided UI. Loopback is not an authentication
# boundary, so every API call requires a per-run random token (delivered in the URL
# fragment, never sent in requests' URLs or logged), Host/Origin validation defeats
# DNS rebinding and cross-site requests, and no CORS headers are ever emitted.
# Implemented on TcpListener: no admin-only URL reservation (http.sys) is needed.

function New-VsatToken {
    $b = New-Object byte[] 32
    $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    try { $rng.GetBytes($b) } finally { $rng.Dispose() }
    return ([Convert]::ToBase64String($b) -replace '[+/=]', '')
}

function Start-VsatServer {
    param([Parameter(Mandatory)][hashtable]$State, [int]$Port = 0)
    $listener = $null
    try {
        $listener = New-Object System.Net.Sockets.TcpListener([System.Net.IPAddress]::Loopback, $Port)
        $listener.ExclusiveAddressUse = $true
        $listener.Start()
    }
    catch {
        if ($Port -ne 0) {
            Write-VsatLog -Level warn -Source 'ui' -Message "Port $Port on 127.0.0.1 is not available ($($_.Exception.Message)); selecting a free loopback port."
            $listener = New-Object System.Net.Sockets.TcpListener([System.Net.IPAddress]::Loopback, 0)
            $listener.Start()
        }
        else { throw }
    }
    $State.port = ([System.Net.IPEndPoint]$listener.LocalEndpoint).Port
    $State.listener = $listener
    $rs = [runspacefactory]::CreateRunspace()
    $rs.ApartmentState = 'MTA'
    $rs.Open()
    $rs.SessionStateProxy.SetVariable('State', $State)
    $ps = [powershell]::Create()
    $ps.Runspace = $rs
    [void]$ps.AddScript($script:VsatServerScript)
    $handle = $ps.BeginInvoke()
    return @{ ps = $ps; rs = $rs; handle = $handle; listener = $listener }
}

function Stop-VsatServer {
    param($Server)
    if (-not $Server) { return }
    try { $Server.listener.Stop() } catch { }
    try { $Server.ps.Stop(); $Server.ps.Dispose() } catch { }
    try { $Server.rs.Close(); $Server.rs.Dispose() } catch { }
}

$script:VsatServerScript = {
    $ErrorActionPreference = 'Stop'
    $enc = New-Object System.Text.UTF8Encoding($false)

    function Test-Eq([string]$a, [string]$b) {
        # Constant-time comparison for tokens.
        if ($null -eq $a -or $null -eq $b) { return $false }
        $x = $enc.GetBytes($a); $y = $enc.GetBytes($b)
        $diff = $x.Length -bxor $y.Length
        for ($i = 0; $i -lt [Math]::Min($x.Length, $y.Length); $i++) { $diff = $diff -bor ($x[$i] -bxor $y[$i]) }
        return ($diff -eq 0)
    }

    function Send-Response($stream, [int]$code, [string]$ctype, [byte[]]$body, [hashtable]$extra) {
        $reason = @{ 200 = 'OK'; 202 = 'Accepted'; 400 = 'Bad Request'; 401 = 'Unauthorized'; 403 = 'Forbidden'; 404 = 'Not Found'; 405 = 'Method Not Allowed'; 409 = 'Conflict'; 413 = 'Payload Too Large'; 421 = 'Misdirected Request'; 500 = 'Internal Server Error' }[$code]
        $h = New-Object System.Text.StringBuilder
        [void]$h.Append("HTTP/1.1 $code $reason`r`n")
        [void]$h.Append("Content-Type: $ctype`r`nContent-Length: $($body.Length)`r`nConnection: close`r`n")
        [void]$h.Append("Cache-Control: no-store`r`nPragma: no-cache`r`nX-Content-Type-Options: nosniff`r`nX-Frame-Options: DENY`r`nReferrer-Policy: no-referrer`r`n")
        [void]$h.Append("Cross-Origin-Opener-Policy: same-origin`r`nCross-Origin-Resource-Policy: same-origin`r`nPermissions-Policy: camera=(), microphone=(), geolocation=()`r`n")
        if ($extra) { foreach ($k in $extra.Keys) { [void]$h.Append("${k}: $($extra[$k])`r`n") } }
        [void]$h.Append("`r`n")
        $hb = $enc.GetBytes($h.ToString())
        $stream.Write($hb, 0, $hb.Length)
        if ($body.Length) { $stream.Write($body, 0, $body.Length) }
        $stream.Flush()
    }

    function Send-Json($stream, [int]$code, $obj) {
        $json = ConvertTo-Json -InputObject $obj -Depth 12 -Compress
        Send-Response $stream $code 'application/json; charset=utf-8' ($enc.GetBytes($json)) $null
    }

    function Read-Request($client) {
        $client.ReceiveTimeout = 5000; $client.SendTimeout = 5000
        $stream = $client.GetStream()
        $buf = New-Object byte[] 1
        $head = [System.Collections.Generic.List[byte]]::new()
        while ($true) {
            $n = $stream.Read($buf, 0, 1)
            if ($n -le 0) { return $null }
            $head.Add($buf[0])
            if ($head.Count -gt 16384) { throw 'header-too-large' }
            $c = $head.Count
            if ($c -ge 4 -and $head[$c - 4] -eq 13 -and $head[$c - 3] -eq 10 -and $head[$c - 2] -eq 13 -and $head[$c - 1] -eq 10) { break }
        }
        $text = [System.Text.Encoding]::ASCII.GetString($head.ToArray())
        $lines = $text -split "`r`n"
        $rl = $lines[0] -split ' '
        if ($rl.Count -ne 3 -or $rl[2] -notmatch '^HTTP/1\.[01]$') { throw 'bad-request-line' }
        $headers = @{}
        foreach ($l in $lines[1..($lines.Count - 1)]) {
            if (-not $l) { continue }
            $i = $l.IndexOf(':')
            if ($i -lt 1) { throw 'bad-header' }
            $k = $l.Substring(0, $i).Trim().ToLowerInvariant()
            if ($headers.ContainsKey($k)) { throw 'duplicate-header' }
            $headers[$k] = $l.Substring($i + 1).Trim()
        }
        $body = ''
        if ($headers.ContainsKey('content-length')) {
            $len = 0
            if (-not [int]::TryParse($headers['content-length'], [ref]$len) -or $len -lt 0) { throw 'bad-length' }
            if ($len -gt 65536) { throw 'too-large' }
            $bb = New-Object byte[] $len; $off = 0
            while ($off -lt $len) { $r = $stream.Read($bb, $off, $len - $off); if ($r -le 0) { break }; $off += $r }
            $body = $enc.GetString($bb, 0, $off)
        }
        if ($headers.ContainsKey('transfer-encoding')) { throw 'chunked-not-supported' }
        return @{ method = $rl[0]; target = $rl[1]; headers = $headers; body = $body; stream = $stream }
    }

    function Get-PublicState {
        $p = $State.progress
        return [ordered]@{
            version = $State.version; mode = $State.mode; profile = $State.profile; phase = $State.phase
            doctor = $State.doctor; endpoints = @($State.endpoints); nsx = $State.nsx
            progress = [ordered]@{ phase = $p.phase; message = $p.message; step = $p.step; totalSteps = $p.totalSteps; counts = $p.counts; log = @($p.log | Select-Object -Last 50) }
            result = $State.result
        }
    }

    function Test-Str($v, [int]$max, [string]$pattern) {
        if ($v -isnot [string] -or $v.Length -gt $max) { return $false }
        if ($pattern -and $v -notmatch $pattern) { return $false }
        return $true
    }

    $listener = $State.listener
    $allowedHosts = @("127.0.0.1:$($State.port)", "localhost:$($State.port)")
    $allowedOrigins = @("http://127.0.0.1:$($State.port)", "http://localhost:$($State.port)")
    while (-not $State.shutdown) {
        $client = $null
        try { $client = $listener.AcceptTcpClient() } catch { break }
        try {
            $req = $null
            try { $req = Read-Request $client } catch { try { Send-Response $client.GetStream() 400 'text/plain' ($enc.GetBytes('Bad request')) $null } catch { }; continue }
            if (-not $req) { continue }
            $s = $req.stream; $h = $req.headers
            # DNS-rebinding defense: the Host header must be the literal loopback authority.
            if (-not $h.ContainsKey('host') -or $allowedHosts -notcontains $h['host'].ToLowerInvariant()) { Send-Response $s 421 'text/plain' ($enc.GetBytes('Invalid Host')) $null; continue }
            if ($h.ContainsKey('origin') -and $allowedOrigins -notcontains $h['origin'].ToLowerInvariant()) { Send-Response $s 403 'text/plain' ($enc.GetBytes('Cross-origin request rejected')) $null; continue }
            if ($h.ContainsKey('sec-fetch-site') -and $h['sec-fetch-site'] -eq 'cross-site') { Send-Response $s 403 'text/plain' ($enc.GetBytes('Cross-site request rejected')) $null; continue }
            $path = ($req.target -split '\?')[0]
            $method = $req.method
            if ($method -eq 'GET' -and $path -eq '/') {
                Send-Response $s 200 'text/html; charset=utf-8' ($enc.GetBytes($State.appHtml)) @{ 'Content-Security-Policy' = $State.appCsp }
                continue
            }
            if ($method -eq 'GET' -and $path -eq '/favicon.ico') { Send-Response $s 404 'text/plain' ($enc.GetBytes('')) $null; continue }
            $cookieOk = $false
            if ($h.ContainsKey('cookie')) { foreach ($c in $h['cookie'].Split(';')) { $kv = $c.Trim().Split('=', 2); if ($kv.Count -eq 2 -and $kv[0] -eq 'vsat_s' -and (Test-Eq $kv[1] $State.cookieToken)) { $cookieOk = $true } } }
            if ($method -eq 'GET' -and $path -eq '/report') {
                if (-not $cookieOk) { Send-Response $s 401 'text/plain' ($enc.GetBytes('Open the report from the VSAT window.')) $null; continue }
                if (-not $State.reportHtml) { Send-Response $s 404 'text/plain' ($enc.GetBytes('No report yet.')) $null; continue }
                Send-Response $s 200 'text/html; charset=utf-8' ($enc.GetBytes($State.reportHtml)) @{ 'Content-Security-Policy' = $State.reportCsp }
                continue
            }
            if (-not $path.StartsWith('/api/')) { Send-Response $s 404 'text/plain' ($enc.GetBytes('Not found')) $null; continue }
            if (-not $h.ContainsKey('x-vsat-token') -or -not (Test-Eq $h['x-vsat-token'] $State.token)) { Send-Json $s 401 @{ ok = $false; error = 'Missing or invalid session token. Open VSAT from the link printed in the terminal.' }; continue }
            if ($method -eq 'GET' -and $path -eq '/api/state') {
                Send-Response $s 200 'application/json; charset=utf-8' ($enc.GetBytes((ConvertTo-Json -InputObject (Get-PublicState) -Depth 14 -Compress))) @{ 'Set-Cookie' = "vsat_s=$($State.cookieToken); Path=/; HttpOnly; SameSite=Strict" }
                continue
            }
            if ($method -ne 'POST') { Send-Json $s 405 @{ ok = $false; error = 'Method not allowed' }; continue }
            if (-not $h.ContainsKey('content-type') -or $h['content-type'] -notmatch '^application/json(;|$)') { Send-Json $s 400 @{ ok = $false; error = 'JSON body required' }; continue }
            $body = $null
            try { $body = if ($req.body) { $req.body | ConvertFrom-Json } else { [pscustomobject]@{} } } catch { Send-Json $s 400 @{ ok = $false; error = 'Malformed JSON' }; continue }
            $busy = $State.phase -in @('running', 'discovering')
            switch ($path) {
                '/api/endpoints' {
                    if ($busy) { Send-Json $s 409 @{ ok = $false; error = 'An operation is in progress.' }; break }
                    $t = [string]$body.type; $addr = $body.address; $user = $body.username; $pw = $body.password; $tp = $body.thumbprint
                    if ($t -notin @('vcenter', 'esxi', 'nsx')) { Send-Json $s 400 @{ ok = $false; error = 'Endpoint type must be vcenter, esxi or nsx.' }; break }
                    if (-not (Test-Str $addr 253 '^[A-Za-z0-9][A-Za-z0-9.\-:\[\]]*$')) { Send-Json $s 400 @{ ok = $false; error = 'Enter a host name or IP address.' }; break }
                    if (-not (Test-Str $user 256 '^[^\x00-\x1f]+$')) { Send-Json $s 400 @{ ok = $false; error = 'Enter a user name.' }; break }
                    if (-not (Test-Str $pw 1024 '')) { Send-Json $s 400 @{ ok = $false; error = 'Enter a password.' }; break }
                    if ($tp -and -not (Test-Str $tp 100 '^[0-9A-Fa-f:]{64,95}$')) { Send-Json $s 400 @{ ok = $false; error = 'Fingerprint must be a SHA-256 hex value.' }; break }
                    $sec = New-Object System.Security.SecureString
                    foreach ($ch in $pw.ToCharArray()) { $sec.AppendChar($ch) }
                    $sec.MakeReadOnly()
                    $pw = $null; $body.password = $null
                    $cred = New-Object System.Management.Automation.PSCredential($user, $sec)
                    $State.queue.Enqueue(@{ type = 'add-endpoint'; endpointType = $t; address = $addr.ToLowerInvariant(); credential = $cred; thumbprint = $tp })
                    Send-Json $s 202 @{ ok = $true; endpoint = @{ type = $t; address = $addr; status = 'connecting' } }
                }
                '/api/endpoints/remove' {
                    if ($busy) { Send-Json $s 409 @{ ok = $false; error = 'An operation is in progress.' }; break }
                    if (-not (Test-Str $body.id 40 '^[a-z0-9-]+$')) { Send-Json $s 400 @{ ok = $false; error = 'Invalid endpoint id' }; break }
                    $State.queue.Enqueue(@{ type = 'remove-endpoint'; id = $body.id }); Send-Json $s 202 @{ ok = $true }
                }
                '/api/nsx' {
                    if ($body.declaredAbsent -isnot [bool]) { Send-Json $s 400 @{ ok = $false; error = 'declaredAbsent must be true or false' }; break }
                    $State.queue.Enqueue(@{ type = 'nsx'; declaredAbsent = $body.declaredAbsent }); Send-Json $s 202 @{ ok = $true }
                }
                '/api/discover' { if ($busy) { Send-Json $s 409 @{ ok = $false; error = 'An operation is in progress.' }; break }; $State.queue.Enqueue(@{ type = 'discover' }); Send-Json $s 202 @{ ok = $true } }
                '/api/run' {
                    if ($busy) { Send-Json $s 409 @{ ok = $false; error = 'An operation is in progress.' }; break }
                    $pf = [string]$body.profile; if (-not $pf) { $pf = 'standard' }
                    if ($pf -notin @('standard', 'strict')) { Send-Json $s 400 @{ ok = $false; error = 'Profile must be standard or strict.' }; break }
                    $State.phase = 'running'
                    $State.queue.Enqueue(@{ type = 'run'; profile = $pf }); Send-Json $s 202 @{ ok = $true }
                }
                '/api/cancel' { $State.progress.cancel = $true; Send-Json $s 202 @{ ok = $true } }
                '/api/shutdown' { $State.queue.Enqueue(@{ type = 'shutdown' }); Send-Json $s 202 @{ ok = $true } }
                default { Send-Json $s 404 @{ ok = $false; error = 'Unknown API' } }
            }
        }
        catch { try { Send-Json $client.GetStream() 500 @{ ok = $false; error = 'Internal error' } } catch { } }
        finally { if ($client) { try { $client.Close() } catch { } } }
    }
}

#endregion Local UI server

# ---- src/95-Doctor.ps1 ----
#region Doctor

function Invoke-VsatDoctor {
    # Readiness checks in plain language. Nothing here contacts the internet.
    param([string[]]$Endpoints = @(), [string]$OutputDir, [switch]$OfflineOnly)
    $checks = [System.Collections.Generic.List[object]]::new()
    $add = { param($name, $status, $detail) $checks.Add([ordered]@{ name = $name; status = $status; detail = $detail }) }

    $v = $PSVersionTable.PSVersion
    if ($v.Major -ge 7 -and ($v.Major -gt 7 -or $v.Minor -ge 4)) { & $add 'PowerShell runtime' 'ok' "PowerShell $v ($($PSVersionTable.PSEdition))" }
    elseif ($v.Major -ge 7) { & $add 'PowerShell runtime' 'warn' "PowerShell $v; 7.4 or later is recommended (use the runtime in the offline package)" }
    else { & $add 'PowerShell runtime' 'warn' "Windows PowerShell $v is deprecated for PowerCLI; use the PowerShell 7 runtime shipped in the offline package" }

    $lm = $ExecutionContext.SessionState.LanguageMode
    if ($lm -eq 'FullLanguage') { & $add 'Language mode' 'ok' 'FullLanguage' }
    else { & $add 'Language mode' 'fail' "$lm - application control restricts PowerShell; VSAT does not bypass it. Ask your administrator to allow the signed package." }

    try { & $add 'Execution policy' 'ok' ("Effective policy: {0} (VSAT never changes it)" -f (Get-ExecutionPolicy)) } catch { & $add 'Execution policy' 'ok' 'Not applicable on this platform' }

    $modDir = Join-Path $script:VsatRoot 'modules'
    if (Test-Path -LiteralPath $modDir) { & $add 'Offline modules folder' 'ok' "Using process-local modules from $modDir" }
    else { & $add 'Offline modules folder' 'warn' 'No ./modules folder next to vsat.ps1; using modules already installed on this machine' }

    $pc = Get-Module -ListAvailable -Name VMware.VimAutomation.Core -ErrorAction SilentlyContinue | Sort-Object Version -Descending | Select-Object -First 1
    if ($pc) { & $add 'VMware PowerCLI' 'ok' "VMware.VimAutomation.Core $($pc.Version) found" }
    elseif ($OfflineOnly) { & $add 'VMware PowerCLI' 'warn' 'Not found - only needed for live vCenter/ESXi collection (replay and demo work without it)' }
    else { & $add 'VMware PowerCLI' 'fail' 'VMware.VimAutomation.Core not found. Use the complete offline package, or install VCF.PowerCLI on a connected machine and copy it into ./modules' }

    if (Initialize-VsatTls) { & $add 'TLS helper' 'ok' 'Certificate probing and per-endpoint pinning available' }
    else { & $add 'TLS helper' 'warn' 'Unavailable; endpoints must present certificates trusted by this machine' }

    if ($OutputDir) {
        try {
            $probeDir = if (Test-Path -LiteralPath $OutputDir) { $OutputDir } else { Split-Path -Parent ([IO.Path]::GetFullPath($OutputDir)) }
            if (-not (Test-Path -LiteralPath $probeDir)) { [void](New-Item -ItemType Directory -Path $probeDir -Force) }
            $t = Join-Path $probeDir ('.vsat-write-test-' + [guid]::NewGuid().ToString('N'))
            Set-Content -LiteralPath $t -Value 'x'; Remove-Item -LiteralPath $t -Force
            & $add 'Output folder' 'ok' "Writable: $probeDir"
        }
        catch { & $add 'Output folder' 'fail' "Cannot write to output location: $($_.Exception.Message)" }
    }

    try {
        $l = New-Object System.Net.Sockets.TcpListener([System.Net.IPAddress]::Loopback, 0); $l.Start(); $p = ([System.Net.IPEndPoint]$l.LocalEndpoint).Port; $l.Stop()
        & $add 'Local UI listener' 'ok' "Can listen on 127.0.0.1 (tested port $p) without administrator rights"
    }
    catch { & $add 'Local UI listener' 'warn' "Cannot open a loopback listener ($($_.Exception.Message)); use -Cli" }

    foreach ($e in @($Endpoints | Where-Object { $_ })) {
        try {
            $c = Get-VsatCertificateInfo -HostName $e
            if (-not $c) { & $add "Endpoint $e" 'warn' 'TLS helper unavailable; connectivity not probed'; continue }
            if ($c.trusted) { & $add "Endpoint $e" 'ok' "Reachable; certificate trusted ($($c.subject), expires $($c.notAfter))" }
            else { & $add "Endpoint $e" 'warn' "Reachable; certificate NOT trusted ($($c.policyErrors)). Import the issuing CA, or approve this exact fingerprint with -TrustedThumbprint `"$e=$($c.sha256)`" after verifying it out of band." }
        }
        catch { & $add "Endpoint $e" 'fail' "Cannot reach ${e}:443 - $($_.Exception.Message)" }
    }
    & $add 'Internet access' 'ok' 'Not required: VSAT performs no downloads, telemetry or online lookups'
    return @($checks)
}

function Write-VsatDoctorReport {
    param([object[]]$Checks)
    Write-Host ''
    Write-Host 'VSAT readiness check' -ForegroundColor Cyan
    foreach ($c in $Checks) {
        $color = switch ($c.status) { 'ok' { 'Green' } 'warn' { 'Yellow' } default { 'Red' } }
        Write-Host ("  [{0,-4}] {1}: {2}" -f $c.status.ToUpperInvariant(), $c.name, (Protect-VsatText $c.detail)) -ForegroundColor $color
    }
    Write-Host ''
}

#endregion Doctor

# ---- src/99-Main.ps1 ----
#region Orchestration

$script:VsatSessions = [ordered]@{}

function Get-VsatScopeFile {
    param([string]$Path)
    if (-not $Path) { return $null }
    $txt = [System.IO.File]::ReadAllText((Resolve-Path -LiteralPath $Path).ProviderPath)
    $scope = ConvertFrom-VsatJson $txt
    # A scope file is credential-free by contract; refuse anything that looks like a secret.
    if ($txt -match '(?i)"(password|secret|token|apikey|api_key)"\s*:') { throw 'Scope files must not contain credentials. Remove password/secret/token fields.' }
    return $scope
}

function Connect-VsatTarget {
    # Connects one endpoint and records the outcome on the evidence endpoint entry.
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)]$Target)
    $ep = Add-VsatEndpoint -Evidence $Evidence -Type $Target.type -Address $Target.address
    $key = "$($Target.type)|$($Target.address)"
    if ($script:VsatSessions.Contains($key) -and $script:VsatSessions[$key].connected) { return $ep }
    Update-VsatProgress -Message "Connecting to $($Target.address)"
    try {
        if ($Target.thumbprint) { Register-VsatPins @("$($Target.address)=$($Target.thumbprint)") }
        if ($Target.type -eq 'nsx') { $sess = Connect-VsatNsx -Address $Target.address -Credential $Target.credential; $script:VsatSessions[$key] = @{ connected = $true; kind = 'nsx'; session = $sess; endpointId = $ep.id } }
        else { $conn = Connect-VsatVSphere -Address $Target.address -Credential $Target.credential; $script:VsatSessions[$key] = @{ connected = $true; kind = 'vsphere'; session = $conn; endpointId = $ep.id } }
        Write-VsatLog -Source 'session' -Message "Connected to $($Target.type) $($Target.address)"
    }
    catch {
        $msg = Protect-VsatText $_.Exception.Message
        $ep.status = 'failed'
        $ep.errors.Add($msg)
        Write-VsatLog -Level error -Source 'session' -Message "Cannot connect to $($Target.type) $($Target.address): $msg"
    }
    return $ep
}

function Disconnect-VsatAll {
    foreach ($k in @($script:VsatSessions.Keys)) {
        $s = $script:VsatSessions[$k]
        try {
            if ($s.kind -eq 'nsx') { Close-VsatRestSession $s.session }
            elseif ($s.session) { Disconnect-VIServer -Server $s.session -Force -Confirm:$false -ErrorAction SilentlyContinue | Out-Null }
        }
        catch { }
        $s.connected = $false
    }
    $script:VsatSessions = [ordered]@{}
}

function Invoke-VsatLiveCollection {
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)][object[]]$Targets)
    $vs = @($Targets | Where-Object { $_.type -in @('vcenter', 'esxi') })
    $nsx = @($Targets | Where-Object { $_.type -eq 'nsx' })
    $script:VsatProgress.totalSteps = ($vs.Count * 6) + ($nsx.Count * 7)
    $script:VsatProgress.step = 0
    try {
        foreach ($t in $vs) {
            if (Test-VsatCancel) { break }
            $ep = Connect-VsatTarget -Evidence $Evidence -Target $t
            $s = $script:VsatSessions["$($t.type)|$($t.address)"]
            if (-not $s -or -not $s.connected) { continue }
            Update-VsatProgress -Phase 'collecting'
            Invoke-VsatVSphereCollection -Evidence $Evidence -Endpoint $ep -Connection $s.session
            Set-VsatEndpointStatus -Evidence $Evidence -Endpoint $ep
        }
        foreach ($t in $nsx) {
            if (Test-VsatCancel) { break }
            $ep = Connect-VsatTarget -Evidence $Evidence -Target $t
            $s = $script:VsatSessions["$($t.type)|$($t.address)"]
            if (-not $s -or -not $s.connected) { continue }
            Update-VsatProgress -Phase 'collecting'
            Invoke-VsatNsxCollection -Evidence $Evidence -Endpoint $ep -Session $s.session
            Set-VsatEndpointStatus -Evidence $Evidence -Endpoint $ep
        }
    }
    finally {
        Disconnect-VsatAll
        $Evidence.run.endedUtc = Get-VsatUtcNow
        $Evidence.run.status = if (Test-VsatCancel) { 'canceled' } elseif (@($Evidence.scope.endpoints | Where-Object { $_.status -ne 'collected' }).Count) { 'partial' } else { 'complete' }
    }
}

function Invoke-VsatPlatformCollection {
    # Hyper-V and KVM: live collection or import of offline collector output.
    param([Parameter(Mandatory)]$Evidence, [Parameter(Mandatory)][hashtable]$A)
    foreach ($s in @($A.HyperVServer | Where-Object { $_ })) {
        $ep = Add-VsatEndpoint -Evidence $Evidence -Type hyperv -Address $s.ToLowerInvariant()
        Update-VsatProgress -Phase 'collecting' -Message "Collecting Hyper-V host $s"
        Invoke-VsatHyperVCollection -Evidence $Evidence -Endpoint $ep -Credential $A.HyperVCredential
    }
    foreach ($f in @($A.HyperVEvidence | Where-Object { $_ })) {
        $txt = [IO.File]::ReadAllText((Resolve-Path -LiteralPath $f).ProviderPath)
        $name = try { [string](ConvertFrom-VsatJson $txt).host.fqdn } catch { [IO.Path]::GetFileNameWithoutExtension($f) }
        $ep = Add-VsatEndpoint -Evidence $Evidence -Type hyperv -Address $(if ($name) { $name } else { $f })
        Write-VsatLog -Source 'hyperv' -Message "Importing offline Hyper-V collector output $f"
        Invoke-VsatHyperVCollection -Evidence $Evidence -Endpoint $ep -ImportedJson $txt
    }
    if (Get-Command Invoke-VsatKvmCollection -ErrorAction SilentlyContinue) {
        foreach ($s in @($A.KvmServer | Where-Object { $_ })) {
            $ep = Add-VsatEndpoint -Evidence $Evidence -Type kvm -Address $s.ToLowerInvariant()
            Update-VsatProgress -Phase 'collecting' -Message "Collecting KVM host $s"
            Invoke-VsatKvmCollection -Evidence $Evidence -Endpoint $ep -User $A.KvmUser
        }
        foreach ($f in @($A.KvmEvidence | Where-Object { $_ })) {
            $txt = [IO.File]::ReadAllText((Resolve-Path -LiteralPath $f).ProviderPath)
            $hn = if ($txt -match '(?m)^hostname=(.+)$') { $Matches[1].Trim() } else { [IO.Path]::GetFileNameWithoutExtension($f) }
            $ep = Add-VsatEndpoint -Evidence $Evidence -Type kvm -Address $hn.ToLowerInvariant()
            Write-VsatLog -Source 'kvm' -Message "Importing offline KVM collector output $f"
            Invoke-VsatKvmCollection -Evidence $Evidence -Endpoint $ep -ImportedText $txt
        }
    }
    if ($Evidence.run.status -ne 'canceled') {
        $Evidence.run.status = if (@($Evidence.scope.endpoints | Where-Object { $_.status -ne 'collected' }).Count) { 'partial' } else { 'complete' }
        $Evidence.run.endedUtc = Get-VsatUtcNow
    }
}

function Set-VsatEndpointStatus {
    param($Evidence, $Endpoint)
    $c = @($Evidence.collection.collectors | Where-Object { $_.endpoint -eq $Endpoint.id })
    $bad = @($c | Where-Object { $_.status -notin @('ok', 'skipped') })
    $Endpoint.status = if ($c.Count -eq 0) { 'failed' } elseif ($bad.Count -eq 0) { 'collected' } elseif ($bad.Count -eq $c.Count) { 'failed' } else { 'partial' }
}

function Get-VsatDemoEvidence {
    $ev = ConvertFrom-VsatJson (Get-VsatEmbeddedText 'fixtures/demo-evidence.json')
    $ev.run.id = [guid]::NewGuid().ToString()
    $ev.run.startedUtc = Get-VsatUtcNow
    $ev.run.endedUtc = Get-VsatUtcNow
    $ev.run.mode = 'demo'
    return (ConvertTo-VsatLiveEvidence $ev)
}

function Resolve-VsatOutputDir {
    param([string]$Path)
    if ($Path) { return [IO.Path]::GetFullPath($Path) }
    return [IO.Path]::GetFullPath((Join-Path (Get-Location).ProviderPath ('vsat-output/' + [DateTime]::Now.ToString('yyyyMMdd-HHmmss'))))
}

function Open-VsatBrowser {
    param([Parameter(Mandatory)][string]$Target)
    try {
        if (Test-VsatIsWindows) { Start-Process $Target | Out-Null }
        elseif ($IsMacOS) { & open $Target }
        else { & xdg-open $Target 2>$null | Out-Null }
    }
    catch { Write-Host "Open this address in a browser: $Target" }
}

function Write-VsatSummary {
    param([Parameter(Mandatory)]$Results, [string]$OutputDir, [string[]]$Files)
    $st = $Results.status
    $color = switch ($st.overall) { 'complete' { if ($st.exitCode -eq 0) { 'Green' } else { 'Yellow' } } default { 'Red' } }
    Write-Host ''
    Write-Host ("=" * 78)
    Write-Host (" STATUS: {0}" -f $st.label) -ForegroundColor $color
    foreach ($r in @($st.reasons | Select-Object -First 6)) { Write-Host ("   - {0}" -f (Protect-VsatText $r)) }
    Write-Host ("=" * 78)
    Write-Host ' Coverage' -ForegroundColor Cyan
    foreach ($d in $Results.coverage.domains) {
        $c = switch ($d.state) { 'ASSESSED' { 'Green' } 'NOT_APPLICABLE' { 'Gray' } 'PARTIAL' { 'Yellow' } default { 'Red' } }
        Write-Host ("   {0,-24} {1,-15} {2}" -f $d.name, $d.state, $(if ($d.mandatory) { 'mandatory' } else { '' })) -ForegroundColor $c
    }
    $s = $Results.summary
    Write-Host ' Findings (FAIL by severity)' -ForegroundColor Cyan
    Write-Host ("   critical {0}  high {1}  medium {2}  low {3}  info {4}" -f $s.severity.critical, $s.severity.high, $s.severity.medium, $s.severity.low, $s.severity.info)
    Write-Host ("   results: PASS {0}  FAIL {1}  MANUAL {2}  UNKNOWN {3}  ERROR {4}  N/A {5}" -f $s.results.PASS, $s.results.FAIL, $s.results.MANUAL, $s.results.UNKNOWN, $s.results.ERROR, $s.results.NOT_APPLICABLE)
    $top = @($Results.findings | Where-Object { $_.result -eq 'FAIL' -and $_.priority } | Sort-Object { - $_.priority.score } | Select-Object -First 10)
    if ($top.Count) {
        Write-Host ' Top priorities' -ForegroundColor Cyan
        foreach ($f in $top) { Write-Host ("   [{0,3}] {1,-8} {2} - {3}" -f $f.priority.score, $f.severity, (Protect-VsatText $f.assetName), $f.title) }
    }
    Write-Host (" Advisory data snapshot: {0} ({1} days old). Rule pack {2}, profile {3}." -f $Results.advisory.snapshotDate, $Results.advisory.ageDays, $Results.rulePack.version, $Results.rulePack.profile)
    if ($OutputDir) {
        Write-Host ' Output (contains sensitive infrastructure data)' -ForegroundColor Cyan
        foreach ($f in @($Files)) { Write-Host ("   {0}" -f (Join-Path $OutputDir $f)) }
    }
    Write-Host ''
}

function Complete-VsatRun {
    # Shared tail for CLI, replay and demo: analysis, outputs, summary.
    param($Evidence, [string]$ProfileName, [string]$OutputDir, $BaselineEvidence, [switch]$Redact)
    $results = Invoke-VsatAnalysisPipeline -Evidence $Evidence -ProfileName $ProfileName -BaselineEvidence $BaselineEvidence
    Update-VsatProgress -Phase 'writing' -Message 'Writing report and evidence package'
    $files = Write-VsatOutputs -Evidence $Evidence -Results $results -OutputDir $OutputDir -Redact:$Redact
    return @{ results = $results; files = $files }
}

function Read-VsatBaseline {
    param([string]$Path)
    if (-not $Path) { return $null }
    $b = Read-VsatPackage -Path $Path
    Write-VsatLog -Source 'drift' -Message "Baseline $Path loaded (integrity: $($b.integrity))"
    return (ConvertTo-VsatLiveEvidence $b.evidence)
}

function Get-VsatCliTargets {
    param([string[]]$Servers, [string[]]$NsxServers, $Scope, [pscredential]$Credential, [pscredential]$NsxCred, [switch]$Interactive)
    $targets = [System.Collections.Generic.List[object]]::new()
    $srv = @($Servers) + @(Get-VsatProp $Scope 'endpoints' @() | Where-Object { $_.type -in @('vcenter', 'esxi') } | ForEach-Object { $_.address }) | Where-Object { $_ } | Select-Object -Unique
    $nsx = @($NsxServers) + @(Get-VsatProp $Scope 'endpoints' @() | Where-Object { $_.type -eq 'nsx' } | ForEach-Object { $_.address }) | Where-Object { $_ } | Select-Object -Unique
    if ($Interactive -and @($srv).Count -eq 0) {
        $a = Read-Host 'vCenter or ESXi address'
        if ($a) { $srv = @($a.Trim()) }
    }
    if (@($srv).Count -and -not $Credential) { $Credential = Get-Credential -Message 'vCenter/ESXi credentials (read-only role is sufficient)' }
    foreach ($s in @($srv)) { $targets.Add(@{ type = 'vcenter'; address = $s.ToLowerInvariant(); credential = $Credential }) }
    $declared = $false
    if ($Interactive -and @($nsx).Count -eq 0 -and -not $script:VsatArgs.NsxDeclaredAbsent -and -not (Get-VsatProp $Scope 'nsxDeclaredAbsent' $false)) {
        Write-Host 'NSX is a mandatory audit domain.' -ForegroundColor Cyan
        $a = Read-Host "NSX Manager address (Enter = unknown, 'none' = NSX is not deployed in this scope)"
        if ($a -eq 'none') { $declared = $true }
        elseif ($a) { $nsx = @($a.Trim()) }
    }
    if (@($nsx).Count -and -not $NsxCred) { $NsxCred = Get-Credential -Message 'NSX Manager credentials (Auditor role is sufficient)' }
    foreach ($n in @($nsx)) { $targets.Add(@{ type = 'nsx'; address = $n.ToLowerInvariant(); credential = $NsxCred }) }
    return @{ targets = @($targets); declaredAbsent = $declared }
}

function Invoke-VsatMain {
    param([hashtable]$A)
    $script:VsatArgs = $A
    $script:VsatRoot = if ($PSScriptRoot) { $PSScriptRoot } else { (Get-Location).ProviderPath }
    $modDir = Join-Path $script:VsatRoot 'modules'
    if (Test-Path -LiteralPath $modDir) {
        # Process-local module resolution; no global installation or profile changes.
        $env:PSModulePath = $modDir + [IO.Path]::PathSeparator + $env:PSModulePath
    }
    if ($A.Version) { [Console]::Out.WriteLine("VSAT $($script:VsatVersion) (rule pack $((Get-VsatRulePack).version), advisory snapshot $((Get-VsatAdvisoryData).snapshotDate), schema $script:VsatSchemaVersion)"); return 0 }
    Register-VsatPins $A.TrustedThumbprint
    $profileName = if ($A.Profile) { $A.Profile } else { 'standard' }
    Initialize-VsatProgress
    $scope = Get-VsatScopeFile $A.ScopeFile
    if ($A.NsxDeclaredAbsent) { if (-not $scope) { $scope = [ordered]@{} }; $scope.nsxDeclaredAbsent = $true }

    if ($A.Doctor) {
        $checks = Invoke-VsatDoctor -Endpoints (@($A.Server) + @($A.NsxServer)) -OutputDir (Resolve-VsatOutputDir $A.OutputPath)
        Write-VsatDoctorReport $checks
        if (@($checks | Where-Object { $_.status -eq 'fail' }).Count) { return 3 }
        return 0
    }

    if ($A.ExportCollector) {
        $dir = if ($A.OutputPath) { $A.OutputPath } else { (Get-Location).ProviderPath }
        $p = Export-VsatCollector -Platform $A.ExportCollector -OutputDir $dir
        [Console]::Out.WriteLine("Read-only collector written to $p")
        return 0
    }

    $outDir = Resolve-VsatOutputDir $A.OutputPath
    [void](New-Item -ItemType Directory -Path $outDir -Force)
    [void](Protect-VsatDirectory -Path $outDir)
    $script:VsatLogFile = Join-Path $outDir 'collection.log'
    Write-VsatLog -Message "VSAT $($script:VsatVersion) starting; output: $outDir"
    $baseline = Read-VsatBaseline $A.Baseline

    if ($A.Replay) {
        $pkg = Read-VsatPackage -Path $A.Replay
        Write-VsatLog -Source 'replay' -Message "Replaying evidence from $($A.Replay) (integrity: $($pkg.integrity)); no connectivity or credentials used"
        $ev = ConvertTo-VsatLiveEvidence $pkg.evidence
        $ev.run.replayedUtc = Get-VsatUtcNow
        if ($scope) { foreach ($k in @('exclusions', 'nativeVlans', 'authorizedNetflowCollectors', 'authorizedSyslogTargets', 'criticalAssets', 'zones', 'exceptions')) { $v = Get-VsatProp $scope $k; if ($null -ne $v) { $ev.scope[$k] = $v } } }
        $r = Complete-VsatRun -Evidence $ev -ProfileName $profileName -OutputDir $outDir -BaselineEvidence $baseline -Redact:$A.Redact
        Write-VsatSummary -Results $r.results -OutputDir $outDir -Files $r.files
        if (-not $A.Cli -and -not $A.NoBrowser) { Open-VsatBrowser (Join-Path $outDir 'report.html') }
        return $r.results.status.exitCode
    }

    if ($A.Demo -and $A.Cli) {
        Write-VsatLog -Source 'demo' -Message 'Running against the built-in synthetic lab (no connectivity)'
        $ev = Get-VsatDemoEvidence
        $r = Complete-VsatRun -Evidence $ev -ProfileName $profileName -OutputDir $outDir -BaselineEvidence $baseline -Redact:$A.Redact
        Write-VsatSummary -Results $r.results -OutputDir $outDir -Files $r.files
        return $r.results.status.exitCode
    }

    if ($A.Cli) {
        $otherPlatforms = @($A.HyperVServer) + @($A.HyperVEvidence) + @($A.KvmServer) + @($A.KvmEvidence) | Where-Object { $_ }
        $interactive = [Environment]::UserInteractive -and -not [Console]::IsInputRedirected -and -not $otherPlatforms.Count
        $t = Get-VsatCliTargets -Servers $A.Server -NsxServers $A.NsxServer -Scope $scope -Credential $A.Credential -NsxCred $A.NsxCredential -Interactive:$interactive
        if ($t.declaredAbsent) { if (-not $scope) { $scope = [ordered]@{} }; $scope.nsxDeclaredAbsent = $true }
        $ev = New-VsatEvidence -Mode live -Scope $scope
        $cancelHandler = $null
        try {
            [Console]::TreatControlCAsInput = $false
            Invoke-VsatLiveCollection -Evidence $ev -Targets $t.targets
            Invoke-VsatPlatformCollection -Evidence $ev -A $A
        }
        catch { Write-VsatLog -Level error -Message "Collection aborted: $($_.Exception.Message)" }
        $r = Complete-VsatRun -Evidence $ev -ProfileName $profileName -OutputDir $outDir -BaselineEvidence $baseline -Redact:$A.Redact
        Write-VsatSummary -Results $r.results -OutputDir $outDir -Files $r.files
        return $r.results.status.exitCode
    }

    return (Invoke-VsatUi -A $A -Scope $scope -OutputDir $outDir -ProfileName $profileName -Baseline $baseline)
}

function Invoke-VsatUi {
    param([hashtable]$A, $Scope, [string]$OutputDir, [string]$ProfileName, $Baseline)
    $state = [hashtable]::Synchronized(@{})
    $state.version = $script:VsatVersion
    $state.mode = $(if ($A.Demo) { 'demo' } else { 'live' })
    $state.profile = $ProfileName
    $state.phase = 'setup'
    $state.token = New-VsatToken
    $state.cookieToken = New-VsatToken
    $state.queue = New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]'
    $state.shutdown = $false
    $state.endpoints = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
    $state.nsx = @{ discovery = @{ status = 'unknown'; evidence = @(); managersDiscovered = @() }; declaredAbsent = [bool](Get-VsatProp $Scope 'nsxDeclaredAbsent' $false); coverageHint = 'Add an NSX Manager or declare that NSX is not deployed.' }
    $state.result = $null
    $state.reportHtml = $null
    $state.progress = [hashtable]::Synchronized(@{})
    Initialize-VsatProgress -Shared $state.progress
    $state.doctor = @{ checks = @(Invoke-VsatDoctor -OutputDir $OutputDir -OfflineOnly:$A.Demo) }
    $css = Get-VsatEmbeddedText 'assets/ui/app.css'; $js = Get-VsatEmbeddedText 'assets/ui/app.js'
    $state.appHtml = New-VsatHtmlDocument -Template (Get-VsatEmbeddedText 'assets/ui/app.html') -Css $css -Js $js -Title 'VSAT' -ExtraCsp "; connect-src 'self'"
    $state.appCsp = "default-src 'none'; script-src 'sha256-$(Get-VsatSha256Base64 $js)'; style-src 'sha256-$(Get-VsatSha256Base64 $css)'; img-src data:; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
    $rcss = Get-VsatEmbeddedText 'assets/report/report.css'; $rjs = Get-VsatEmbeddedText 'assets/report/report.js'
    $state.reportCsp = "default-src 'none'; script-src 'sha256-$(Get-VsatSha256Base64 $rjs)'; style-src 'sha256-$(Get-VsatSha256Base64 $rcss)'; img-src data: blob:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
    $targets = [ordered]@{}
    foreach ($s in @($A.Server)) { if ($s) { [void]$state.endpoints.Add(@{ id = "pending-$($state.endpoints.Count)"; type = 'vcenter'; address = $s; authenticated = $false; status = 'needs credentials'; error = $null }) } }
    foreach ($s in @($A.NsxServer)) { if ($s) { [void]$state.endpoints.Add(@{ id = "pending-$($state.endpoints.Count)"; type = 'nsx'; address = $s; authenticated = $false; status = 'needs credentials'; error = $null }) } }
    $server = Start-VsatServer -State $state -Port $A.Port
    $url = "http://127.0.0.1:$($state.port)/#token=$($state.token)"
    Write-Host ''
    Write-Host 'VSAT is running locally. Open this private link (do not share it):' -ForegroundColor Cyan
    Write-Host "  $url"
    Write-Host 'Press Ctrl+C or use Finish in the browser to stop.'
    Write-Host ''
    if (-not $A.NoBrowser) { Open-VsatBrowser $url }
    $evidenceScope = $Scope
    $lastEvidence = $null; $exit = 2
    try {
        while (-not $state.shutdown) {
            $cmd = $null
            if (-not $state.queue.TryDequeue([ref]$cmd)) { Start-Sleep -Milliseconds 150; continue }
            switch ($cmd.type) {
                'add-endpoint' {
                    $addr = $cmd.address
                    $existing = @($state.endpoints | Where-Object { $_.address -eq $addr -and $_.type -eq $cmd.endpointType })
                    foreach ($x in $existing) { $state.endpoints.Remove($x) }
                    $entry = @{ id = ('ep-' + [guid]::NewGuid().ToString('N').Substring(0, 8)); type = $cmd.endpointType; address = $addr; authenticated = $false; status = 'connecting'; error = $null }
                    [void]$state.endpoints.Add($entry)
                    if ($state.mode -eq 'demo') {
                        $entry.authenticated = $true; $entry.status = 'demo (not contacted)'
                        $targets[$entry.id] = @{ type = $cmd.endpointType; address = $addr; credential = $cmd.credential; thumbprint = $cmd.thumbprint }
                        break
                    }
                    $probe = New-VsatEvidence -Mode live
                    $ep = Connect-VsatTarget -Evidence $probe -Target @{ type = $cmd.endpointType; address = $addr; credential = $cmd.credential; thumbprint = $cmd.thumbprint }
                    if ($ep.status -eq 'failed') { $entry.status = 'failed'; $entry.error = (Get-VsatFriendlyError $ep.errors[0]) }
                    else {
                        $entry.authenticated = $true; $entry.status = 'authenticated'
                        $targets[$entry.id] = @{ type = $cmd.endpointType; address = $addr; credential = $cmd.credential; thumbprint = $cmd.thumbprint }
                    }
                }
                'remove-endpoint' {
                    $x = @($state.endpoints | Where-Object { $_.id -eq $cmd.id })
                    foreach ($e in $x) { $state.endpoints.Remove($e); if ($targets.Contains($e.id)) { $targets.Remove($e.id) } }
                    Disconnect-VsatAll
                }
                'nsx' { $state.nsx.declaredAbsent = [bool]$cmd.declaredAbsent }
                'discover' {
                    $state.phase = 'discovering'
                    try {
                        if ($state.mode -eq 'demo') { $dev = Get-VsatDemoEvidence; $state.nsx.discovery = Update-VsatNsxDiscovery -Evidence $dev }
                        else {
                            $dev = New-VsatEvidence -Mode live
                            foreach ($t in @($targets.Values | Where-Object { $_.type -eq 'vcenter' -or $_.type -eq 'esxi' })) {
                                $ep = Connect-VsatTarget -Evidence $dev -Target $t
                                $s = $script:VsatSessions["$($t.type)|$($t.address)"]
                                if ($s -and $s.connected) {
                                    $about = $s.session.ExtensionData.Content.About
                                    if ($about.ApiType -eq 'VirtualCenter') {
                                        $root = Add-VsatAsset -Evidence $dev -Id "$($ep.id):root" -Type vcenter -Name $t.address -Endpoint $ep.id
                                        Invoke-VsatFact $root 'extensions' { $em = Get-View -Server $s.session -Id $s.session.ExtensionData.Content.ExtensionManager -Property ExtensionList; @($em.ExtensionList | ForEach-Object { [ordered]@{ key = $_.Key; version = $_.Version; urls = @($_.Server | ForEach-Object { $_.Url }) } }) }
                                    }
                                }
                            }
                            $state.nsx.discovery = Update-VsatNsxDiscovery -Evidence $dev
                        }
                    }
                    catch { Write-VsatLog -Level warn -Source 'discovery' -Message "Discovery failed: $($_.Exception.Message)" }
                    $state.nsx.coverageHint = switch ($state.nsx.discovery.status) { 'detected' { 'NSX detected: add every NSX Manager, otherwise the report will be INCOMPLETE: NSX NOT ASSESSED.' } 'not-detected' { 'No NSX found in vCenter. You may declare NSX not deployed; the report records the evidence.' } default { 'NSX presence could not be determined; add an NSX Manager or the report will show NSX coverage UNKNOWN/REVIEW.' } }
                    $state.phase = 'ready'
                }
                'run' {
                    $state.phase = 'running'
                    $state.progress.cancel = $false
                    $state.profile = $cmd.profile
                    try {
                        $sc = if ($evidenceScope) { $evidenceScope } else { [ordered]@{} }
                        $sc.nsxDeclaredAbsent = [bool]$state.nsx.declaredAbsent
                        if ($state.mode -eq 'demo') {
                            $ev = Get-VsatDemoEvidence
                            $ev.scope.nsxDeclaredAbsent = $sc.nsxDeclaredAbsent
                            $state.progress.totalSteps = 3
                            foreach ($i in 1..3) { Update-VsatProgress -Phase 'collecting' -Message "Loading synthetic lab ($i/3)" -Step; Start-Sleep -Milliseconds 300 }
                        }
                        else {
                            $ev = New-VsatEvidence -Mode live -Scope $sc
                            Invoke-VsatLiveCollection -Evidence $ev -Targets @($targets.Values)
                        }
                        $r = Complete-VsatRun -Evidence $ev -ProfileName $cmd.profile -OutputDir $OutputDir -BaselineEvidence $Baseline -Redact:$A.Redact
                        $state.reportHtml = [System.IO.File]::ReadAllText((Join-Path $OutputDir 'report.html'))
                        $state.result = @{ status = $r.results.status; summary = $r.results.summary; outputDir = $OutputDir; reportUrl = '/report'; files = @($r.files) }
                        $state.phase = $(if ($r.results.status.overall -eq 'canceled') { 'canceled' } else { 'done' })
                        $exit = $r.results.status.exitCode
                        Write-VsatSummary -Results $r.results -OutputDir $OutputDir -Files $r.files
                    }
                    catch {
                        Write-VsatLog -Level error -Message "Assessment failed: $($_.Exception.Message)"
                        $state.phase = 'failed'; $exit = 3
                    }
                }
                'shutdown' { $state.shutdown = $true }
            }
        }
    }
    finally {
        $state.shutdown = $true
        Disconnect-VsatAll
        Stop-VsatServer $server
        foreach ($k in @($targets.Keys)) { $targets[$k].credential = $null }
    }
    return $exit
}

function Get-VsatFriendlyError {
    param([string]$Message)
    if ($Message -match '(?i)incorrect user name or password|Cannot complete login|401|invalid credentials') { return 'The user name or password was rejected.' }
    if ($Message -match '(?i)certificate|SSL|TLS|trust') { return "The server certificate is not trusted by this machine. Import the issuing CA, or approve the exact fingerprint (see -Doctor output). Details: $Message" }
    if ($Message -match '(?i)timed out|timeout|No such host|could not resolve|refused|unreachable') { return "The server could not be reached on port 443. Details: $Message" }
    if ($Message -match '(?i)PowerCLI') { return $Message }
    return $Message
}

#endregion Orchestration

#region Embedded resources (base64 UTF-8; data only, never executed)
$script:VsatEmbedded = [ordered]@{
    'rules/esxi.json' = ''
    'rules/hyperv.json' = ''
    'rules/network.json' = ''
    'rules/nsx.json' = ''
    'rules/pack.json' = ''
    'rules/vcenter-cluster-storage.json' = ''
    'rules/vm.json' = ''
    'data/advisories.json' = ''
    'data/os-lifecycle.json' = ''
    'assets/report/report.html' = ''
    'assets/report/report.css' = ''
    'assets/report/report.js' = ''
    'assets/ui/app.html' = ''
    'assets/ui/app.css' = ''
    'assets/ui/app.js' = ''
    'fixtures/demo-evidence.json' = ''
}
function Get-VsatEmbeddedNames {
    param([string]$Prefix = '')
    return @($script:VsatEmbedded.Keys | Where-Object { $_.StartsWith($Prefix) })
}
function Get-VsatEmbeddedText {
    param([Parameter(Mandatory)][string]$Name)
    if (-not $script:VsatEmbedded.Contains($Name)) { throw "Embedded resource '$Name' not found" }
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($script:VsatEmbedded[$Name]))
}
#endregion Embedded resources

if (-not $LibraryMode) {
    $vsatArgs = @{
        Server = $Server; NsxServer = $NsxServer; Credential = $Credential; NsxCredential = $NsxCredential
        NsxDeclaredAbsent = [bool]$NsxDeclaredAbsent; ScopeFile = $ScopeFile; Profile = $AuditProfile; OutputPath = $OutputPath
        Cli = [bool]$Cli; Doctor = [bool]$Doctor; Replay = $Replay; Baseline = $Baseline; Redact = [bool]$Redact
        TrustedThumbprint = $TrustedThumbprint; Port = $Port; NoBrowser = [bool]$NoBrowser; Demo = [bool]$Demo; Version = [bool]$Version
    }
    foreach ($vsatOpt in 'HyperVServer', 'HyperVCredential', 'HyperVEvidence', 'ExportCollector', 'KvmServer', 'KvmUser', 'KvmEvidence') {
        $vsatVar = Get-Variable -Name $vsatOpt -Scope Script -ErrorAction SilentlyContinue
        if ($vsatVar) { $vsatArgs[$vsatOpt] = $vsatVar.Value }
    }
    try { $vsatExit = Invoke-VsatMain -A $vsatArgs }
    catch {
        Write-Host ("VSAT fatal error: {0}" -f (Protect-VsatText $_.Exception.Message)) -ForegroundColor Red
        $vsatExit = 3
    }
    exit $vsatExit
}